SELECT 'moj-all-verified-judgments-review-002-chunk-003' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6704a99e-33bb-5a0d-b5c2-3fe8a2c69aa6","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع سيارة بأقساط -االمتناع عن السداد -عدم حضور املدعى عليه -بينة املدعي العقد والكمبياالت واليمن -احلكم غيابي ا بدفع الثمن احلال واإللزام مبا تبقى -الغائب على حجته","document_number":"34235421","case_number":"341653","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/10","year":"1434","subject":"بيع -بيع سيارة بأقساط -االمتناع عن السداد -عدم حضور املدعى عليه -بينة املدعي العقد والكمبياالت واليمن -احلكم غيابي ا بدفع الثمن احلال واإللزام مبا تبقى -الغائب على حجته","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34235421 :‬‬\n                     ‫َر ْق ُم الدعوى‪341653 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34297969‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع ســيارة بأقســاط‪ -‬االمتنــاع عــن الســداد ‪ -‬عــدم حضــور‬\n‫املدعــى عليــه ‪ -‬بينــة املدعــي العقــد والكمبيــاالت واليمــن ‪ -‬احلكــم‬\n‫غيابيـ ًا بدفــع الثمــن احلــال واإللــزام مبــا تبقــى ‪ -‬الغائــب علــى حجتــه‬\n                                                               ‫متــى حضــر ‪.‬‬\n\n\n\n\n                                           ‫‪ .1‬حديث « ال ضرر وال ضرار »‬\n‫‪ .2‬للحاكــم واليــة علــى مــال الغائــب ويجــوز لــه احلكــم عليــه وعلــى‬\n‫املســتتر واملمتنــع ولــو كان يف البلــد كمــا صــرح بذلــك صاحــب‬\n                                                        ‫املبــدع والكشــاف ‪.‬‬\n\n\n\n\n‫قــام املدعــي ببيــع ســيارة إلــى املدعــى عليــه تســدد قيمتهــا علــى أقســاط‬\n‫شــهرية ‪ ،‬وقــد حــددا قيمــة كل قســط‪ ،‬ســدد املدعــى عليــه جــزء ًا مــن‬\n‫هــذه األقســاط وامتنــع عــن ســداد الباقــي‪ ،‬طلب املدعي إلزامه بالســداد‬\n‫وااللتــزام بســداد مــا تبقــى يف حينــه‪ ،‬وقــدم لصحــة دعــواه صــورة العقد‪،‬‬\n‫وكمبيــاالت موقعــة مــن املدعــى عليــه‪ ،‬كمــا حلــف اليمــن الشــرعية‪،‬‬\n‫ـاء علــى‬‫لــم يحضــر املدعــى عليــه وجــرى ســماع الدعــوى غيابي ـ ًا ‪ -‬بنـ ً‬\n‫مــا تقــدم حكمــت احملكمــة علــى املدعــى عليــه غيابي ـ ًا بدفــع الثمــن‬\n\n                                                                                    ‫‪130‬‬\n\f      ‫حــا ًال وااللتــزام بســداد املتبقــي يف حينــه ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                 ‫االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمد هلل وحده وبعد فلدي أنا (‪ )....‬القاضي يف احملكمة العامة مبكة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 341653‬وتاريــخ ‪ 1434/01/03‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 346961‬وتاريــخ ‪ 1434/01/03‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1434/06/10‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 30‬‬\n      ‫حضــر املدعــي ‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ...........‬ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه وقــد ســبق إبالغــه‬\n      ‫باحلضــور يف املوعــد املاضــي املقــرر بتاريــخ ‪1434/01/24‬ه ـ ولــم يحضر‬\n      ‫اجللســة كمــا مت إبالغــه شــخصيا باحلضــور يف هــذا اليــوم وذلك مبوجب‬\n      ‫خطــاب محضــري اخلصــوم رقــم ‪ 34208799‬وتاريــخ ‪1434/01/25‬ه ـ‬\n      ‫وطلــب املدعــي ســماع دعــواه وقــررت الســير يف الدعــوى وســماعها‬\n      ‫ـاء علــى املــادة رقــم ‪ 55‬مــن نظــام املرافعــات الشــرعية وبســؤاله‬  ‫غيابيـ ًا بنـ ً‬\n      ‫عــن دعــواه قــال لقــد بعــت علــى املدعــى عليه ‪ .................‬ســيارة إيســيوزو‬\n      ‫ونيــت ‪ 2009‬م بقيمــة إجماليــة قدرهــا واحــد وســبعون ألــف ريــال تســدد‬\n      ‫علــى أقســاط شــهرية قيمــة كل قســط ألــف وســتمائة ريــال والقســط‬\n      ‫األخيــر ســتمائة ريــال ابتــداء مــن ‪1431/06/25‬ه ـ وآخــر قســط بتاريــخ‬\n      ‫‪1435/02/25‬ه ـ وقــد ســدد منهــا حتــى اآلن ســتة عشــر ألــف ريــال‬\n      ‫وبقــي يف ذمتــه خمســة وخمســون ألــف ريــال حــل منهــا واحــد وأربعــون‬\n      ‫ألــف وســتمائة ريــال وبقــي ثالثــة عشــر ألــف وأربعمائــة ريــال لــم حتــل‬\n\n‫‪131‬‬\n\f‫حتــى اآلن أطلــب إلزامــه بالســداد وااللتــزام بســداد املتبقــي يف حينــه‬\n‫هــذه دعــواي وبطلــب البينــة منــه أبــرز أصــل العقــد املوقــع بــن الطرفــن‬\n‫وعــدد خمــس وثالثــن كمبيالــة موقعــة مــن املدعــى عليــه ممــا يثبــت‬\n‫عــدم ســداده وبطلــب ميــن االســتظهار مــن املدعــي علــى صحــة دعــواه‬\n‫ا واهلل العظيــم الــذي ال الــه إال هــو أن لــي يف ذمــة املدعــى‬‫حلــف قائ ـ ً‬\n‫عليــه مبلــغ وقــدره خمســة وخمســون ألــف ريــال منهــا واحــد وأربعــون‬\n‫ألــف وســتمائة ريــال حالــة وثالثــة عشــر ألــف وأربعمائــة ريــال لــم حتــل‬\n‫واهلل العظيــم فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث قــدم‬\n‫املدعــي بينتــه علــى دعــواه وحلــف ميــن االســتظهار بعــد طلبهــا منه وحيث‬\n‫تضــرر املدعــي مــن عــدم حضــور املدعــى عليــه وقــد جــاءت الشــريعة‬\n‫برفــع الضــرر حلديــث « ال ضــرر وال ضــرار» وألن للحاكــم واليــة علــى‬\n‫مــال الغائــب ويجــوز لــه احلكــم عليــه وعلــى املســتتر واملمتنــع ولــو كان‬\n‫يف البلــد كمــا صــرح بذلــك صاحــب املبــدع والكشــاف وبنــاء علــى‬\n‫نظــام املرافعــات مــادة خمســة وخمســون فقــد حكمــت علــى املدعــى‬\n‫عليــه بدفــع مبلــغ واحــد وأربعــن ألــف وســتمائة ريــال حــا ًال وااللتــزام‬\n‫بســداد املتبقــي يف حينــه وبعرضــه علــى املدعــي قــرر القناعــة وســيتم‬\n‫بعــث نســخة مــن صــك احلكــم للمدعــى عليــه بعــد إخراجــه وإفهامــه‬\n‫بتعليمــات االســتئناف وأنــه إذا تبلــغ املدعــى عليــه باحلكــم ومضــت‬\n‫مــدة االعتــراض وقدرهــا ثالثــون يومـ ًا ولــم يتقــدم باعتــراض يكتســب‬\n‫احلكــم القطعيــة ورفعــه حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                        ‫يف ‪1434/06/10‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n\n\n                                                                                   ‫‪132‬‬\n\f      ‫فقــد جــرت منــي الكتابــة إلــى مديــر مركــز شــرطة العزيزيــة‬\n      ‫بكتــاب احملكمــة رقــم ‪ 341452183‬وتاريــخ ‪1434/6/17‬ه ـ إلبــاغ‬\n      ‫احملكــوم عليــه ‪ ................‬باحلكــم وأن مــدة االعتــراض ثالثــون يوم ـ ًا‬\n      ‫مــن تاريــخ تبليــغ احلكــم للمحكــوم عليــه أو وكيلــه حســبما قضــت‬\n      ‫بــه املــادة السادســة والســبعون بعــد املئــة مــن نظــام املرافعــات الشــرعية‬\n      ‫فــورد اجلــواب مــن شــرطة العزيزيــة بالكتــاب رقــم ‪ 248963‬وتاريــخ‬\n      ‫‪1434/7/16‬ه ـ املتضمــن بأنــه ( جــرى طلــب احملكــوم عليــه املذكــور‬\n      ‫عــن طريــق عمــدة العزيزيــة الشــرقية الــذي أفــاد بــأن مديــر فــرع شــركة‬\n      ‫الوشــاح للحراســات األمنيــة ذكــر بــأن املدعــى عليــه ‪............‬مفصــول‬\n      ‫مــن الشــركة ) أ‪.‬ه ـ لــذا وألنــه قــد تعــذر تســليم نســخة مــن صك احلكم‬\n      ‫الصــادر يف هــذه الدعــوى برقــم ‪ 34235421‬وتاريــخ ‪1434/6/10‬ه ـ‬\n      ‫ا‬ ‫فقــد قــررت رفــع هــذا احلكــم حملكمــة االســتئناف لتدقيقــه عم ـ ً‬\n      ‫بالفقــرة اخلامســة مــن املــادة املذكــورة مــن النظــام ولوائحــه التنفيذيــة‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا وآلــه وصحبــه وســلم حــرر يف‬\n                                                                     ‫‪1434/7/22‬ه ـ ‪.‬‬\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34297969‬وتاريــخ‬\n                                                      ‫‪1434/8/15‬هـ‪.‬‬\n\n\n\n\n‫‪133‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":130,"source_page_end":133,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f6bfeca1e2fe6ca4ea06d066d0b6f03d98a7547e002754d7e9917fb901845352","normalized_text_hash":"4033bf2fb12344908ae5dca37c4a969e6b5a7662b0574582d5d8e92e33b7c62e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p130-34235421"},{"id":"36f8da63-29a7-5aaf-a53e-013d2122f0c1","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع معدات مخبز وسيارات -املطالبة بقيمة املعدات -بينة املدعي وميينه -إيجابية التقرير الفني للمدعي -احلكم بدفع الثمن للمدعي .","document_number":"33169186","case_number":"3226935","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالقطيف","circuit":"الدائرة احلقوقية األولى مبحكمة الاستئناف برقم 33169186يف","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/4","year":"1434","subject":"بيع -بيع معدات مخبز وسيارات -املطالبة بقيمة املعدات -بينة املدعي وميينه -إيجابية التقرير الفني للمدعي -احلكم بدفع الثمن للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1433/4/4 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33169186 :‬‬\n                    ‫َر ْق ُم الدعوى‪3226935 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3463325‬تاريخه‪1434/3/16 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع معــدات مخبــز وســيارات ‪ -‬املطالبــة بقيمــة املعــدات ‪ -‬بينــة‬\n‫املدعــي وميينــه ‪ -‬إيجابيــة التقريــر الفنــي للمدعــي ‪ -‬احلكــم بدفــع‬\n                                                         ‫الثمــن للمدعــي ‪.‬‬\n\n\n\n\n                                                ‫‪ -‬قاعدة املثبت مقدم على النفي ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي أنــه اشــترى مــن املدعــى عليه معــدات مخبز متنوعــة وأربع‬\n‫ســيارات مببلــغ أربعمائــة وخمســة وســبعني ألــف ريــال وقــد اتفقــا علــى أن‬\n‫يكــون دفــع القيمــة بعــد ثــاث ســنوات مــن تســليم املخبــز وقــد اســتلم‬\n‫املدعــى عليــه املخبــز بعــد البيــع مباشــرة وقــد ســلم املدعــى عليــه القيمــة‬\n‫للمدعــي مبوجــب شــيكني ومتــت مراجعتــه فلــم يتمكــن مــن الصــرف‬\n‫ملضــي مــدة طويلــة للشــيكات ولعــدم وجــود رصيــد لهــا ‪ -‬طلــب املدعــي‬\n‫احلكــم علــى املدعــى عليــه بدفــع القيمــة املذكــورة ‪ -‬أنكــر املدعــى‬\n‫عليــه الدعــوى ‪ -‬أبــرز املدعــي إقــرار ًا للمدعــى عليــه باملبلــغ والشــيكات‬\n‫الصــادرة منــه ‪ -‬طعــن املدعــى عليــه يف صحتهــا ‪ -‬جــرى بعثهــا لألدلــة‬\n‫اجلنائيــة للمطابقــة فوجــدت مطابقــة وجــرى حتليــف املدعــي اليمــن علــى‬\n‫دعــواه ونفــي التزويــر ‪ -‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ‬\n\n                                                                                       ‫‪134‬‬\n\f      ‫املدعــى بــه ‪ -‬اعتــرض املدعــى عليــه علــى احلكــم ‪ -‬صــدق احلكــم مــن‬\n                                                        ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد يــوم األربعــاء املوافــق ‪1431/3/10‬ه ـ لــدي أنــا‬\n      ‫(‪ )....‬القاضــي باحملكمــة العامــة بالقطيــف افتتحــت اجللســة وحضــر‬\n      ‫فيهــا ‪ ............‬رقــم ســجله املدنــي ‪ ................‬الوكيــل عــن ‪ ...........‬لبناني‬\n      ‫اجلنســية مبوجــب اإلقامــة رقــم ‪ .............‬الصــادرة مــن هيئــة االســتثمار‬\n      ‫بالدمــام بتاريــخ ‪1425/7/15‬ه ـ مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n      ‫عــدل الدمــام الثانيــة برقــم ‪ 11277‬يف ‪1428/2/22‬ه ـ جلــد ‪6377‬‬\n      ‫وادعــى علــى احلاضــر معــه ‪ .........‬رقــم ســجله املدنــي ‪ ...............‬الوكيــل‬\n      ‫عــن ‪ ............‬رقــم ســجله املدنــي ‪ ..............‬مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة عــدل القطيــف برقــم ‪ 15‬يف ‪ 1428/5/27‬ه ـ جلــد ‪8/5101‬‬\n      ‫ا يف دعــواه إنــه بتاريــخ ‪1420/3/2‬ه ـ اشــترى مــوكل هــذا احلاضــر‬               ‫قائـ ً‬\n      ‫مــن موكلــي معــدات مخبــز مكونــة مــن ‪ -1‬عجانــه إيطاليــة ‪ -2‬قطاعــه‬\n      ‫‪ -3‬مخبــز كبيــر ‪ -4‬مخبــز صغيــر ‪ -5‬رقاقــة ‪ -6‬كــوع فــرن ‪ -7‬بيــت‬\n      ‫نــار ‪ -8‬خــط تبريــد جنزيــر كامــل ‪ -9‬فــرن كهربائــي ثــاث طبقــات‬\n      ‫‪ -10‬فــرن غــاز طبقــه واحــده ‪ -11‬لفافــة صامولــي ‪ -12‬قطاعــة نصــف‬\n      ‫اتوماتيكيــة كمــا اشــترى منــه ثالث ســيارات فان وأيض ًا ســيارة وانيت‬\n      ‫مببلــغ أربعمائــة وخمســة وســبعني ألــف ريــال وقــد اتفقــا علــى أن يكــون‬\n      ‫دفــع القيمــة بعــد ثــاث ســنوات مــن تســليم املخبــز وقــد اســتلم املدعــى‬\n      ‫عليــه اصالــة املخبــز بعــد البيــع مباشــرة وقــد ســلم املدعــى عليــه أصالــة‬\n      ‫القيمــة ملوكلــي مبوجــب شــيكني مســحوبني علــى البنــك الســعودي‬\n\n‫‪135‬‬\n\f‫الفرنســي بالقطيــف األول برقــم ‪ 381751‬والثانــي برقــم ‪381752‬‬\n‫كالهمــا يف ‪1420/3/3‬ه ـ وكان موكلــي وقــت البيــع يعمــل حتــت‬\n‫كفالــة املشــتري ثــم إن املدعــى عليــه قــام بترحيلــه إلــى بلــده بخــروج‬\n‫نهائــي قبــل صــرف الشــيكات ثــم إن موكلــي رجــع إلــى اململكــة‬\n‫بتأشــيرة مســتثمر ومتــت مراجعتــه بعــد رجوعــه منــذ ســنتني فلــم يتمكــن‬\n‫مــن الصــرف ملضــي مــدة طويلــة للشــيكات ولعــدم وجــود رصيــد لهــا‬\n‫لــذا أطلــب احلكــم علــى املدعــى عليــه أصالــة بــأن يدفــع ملوكلــي مبلــغ‬\n‫أربعمائــة وخمســة وســبعني ألــف ريــال هــذه دعــواي وبســؤال املدعــى‬\n‫عليــه أجــاب بقولــه مــا ذكــره يف دعــواه ليــس بصحيــح فلــم يشــتر مــن‬\n‫موكلــه املخبــز الــذي وصــف معداتــه وكــذا ثــاث ســيارات فــان وانيــت‬\n‫يف التاريــخ وباملبلــغ الــذي ذكــر لــذا أطلــب رد دعــواه وصــرف النظــر‬\n‫عنهــا هــذه إجابتــي وبعــد ســماع الدعــوى واإلجابــة جــرى عــرض مــا دفــع‬\n‫بــه املدعــى عليــه وكالــة علــى املدعــي وكالــة فقــال مــا جــاء يف دفعــه‬\n‫ليــس بصحيــح والصحيــح مــا ذكرتــه يف دعــواي فســألته هــل لديــك‬\n‫بينــة قــال نعــم أطلــب مهلــة إلحضارهــا ورفعــت اجللســة لذلــك ويف جلســة‬\n‫أخــرى لــدي أنــا ‪ ..............‬القاضــي باحملكمــة العامــة بالقطيــف واخللــف‬\n‫لفضيلــة ناظــر القضيــة افتتحــت اجللســة وباالطــاع علــى مــا مت ضبطــه‬\n‫وجدتــه موقعـ ًا مــن أطــراف وفضيلــة ســلفي ناظــر القضيــة ابتــداء وبنــاء‬\n‫علــى املــادة السادســة والســتني بعــد املائــة مــن نظــام املرافعــات الشــرعية‬\n‫ولوائحهــا التنفيذيــة فقــد مت اعتمــاده وقــد حضــر املتداعيــان وكالــة‬\n‫وقــدم املدعــى عليــه وكالــة مذكــرة مكونــة مــن ورقــة واحــده وبرفقتــه‬\n‫بعــض املرفقــات وبعــد االطــاع علــى هــذه املذكــرة وجــدت أن ملخصهــا‬\n‫يتضمــن ‪ :‬أو ًال أن املدعــي كان يعمــل لــدى موكلــي براتــب شــهري‬\n\n\n                                                                                      ‫‪136‬‬\n\f      ‫وانتهــت خدماتــه بعــد توقيــع مخالصــة يقــر فيهــا بــأن ليــس لــه أي حقــوق‬\n      ‫ال ســابقة وال الحقــه ثانيـ ًا عــدم صحــة ادعــاء املدعــي مــن كــون موكلــه‬\n      ‫قــام بشــراء املعــدات منــه الن املدعــي كان مجــرد موظــف ويقــدح يف‬\n      ‫صــورة املبايعــة املرفقــة يف صحيفــة الدعــوى وأن املدعــي أســتغل عملــه‬\n      ‫مــع موكلــه ككاتــب حســابات بحفــظ بعــض األوراق ثالث ـ ًا بالنســبة‬\n      ‫للســيارات فيطلــب إحضــار املبايعــة ومخاطبــة املــرور لإلفــادة عــن‬\n      ‫الســيارات انتهــى كامــل مضمونــه وقــد أرفقــت كامــل املرفقــات‬\n      ‫واملذكــرة باملعاملــة ثــم جــرى ســؤال املدعــي البينــة فقــال بينتــي إقــرار‬\n      ‫املدعــى عليــه أصالــة بالشــراء وكــذا أصــل الشــيكني الصادريــن مــن‬\n      ‫املدعــى عليــه أصالــة مــن موكلــي بكامــل املبلــغ وآمــل االطــاع عليهــا‬\n      ‫هكــذا قــرر ثــم قدمهــا وباالطــاع عليهــا وجدتهــا ورقــة مــن مطبوعــات‬\n      ‫مخبــز ‪ ................‬احلديــث وتضمنــت مــا نصــه التاريــخ ‪1420/3/3‬ه ـ‬\n      ‫بســم اهلل الرحمــن الرحيــم أنــا املوقــع أدنــاه ‪ ............‬ســعودي اجلنســية‬\n      ‫مبوجــب حفيظــة رقــم ‪ ...........‬تاريخهــا ‪1378/8/14‬ه ـ اقــر واعتــرف‬\n      ‫بأننــي اتفقــت مــع مكفولــي ‪ ...........‬لبنانــي اجلنســية مبوجــب اإلقامــة‬\n      ‫رقــم ‪ .............‬علــى شــراء املعــدات والســيارات التابعــة للمخبــز املســجل‬\n      ‫باســمي يف القطيــف باســم مخبــز ‪ .................‬املعــدات هــي عبــارة عــن‬\n      ‫(عجانــة إيطاليــة قطاعــة مخمــرة عــدد ‪3‬كبيــر مخمــر عــدد ‪ 1‬صغيــر‬\n      ‫رقاقــة كــوع فــرن عــدد ‪ 1‬بيــت نــار خــط تبريــد جنزيــر كامــل عجانــه‬\n      ‫كهربائيــة فــرن كهربائــي ثــاث طبقــات فــرن غــاز طبقــه واحــده‬\n      ‫لفافــة صامولــي قطاعــة نصــف أوتوماتيكيــة الســيارات هــي فــان عــدد‬\n      ‫‪ 3‬وســيارة وانيــت عــدد ‪ 1‬وذلــك مببلــغ (‪ )475000‬اربعمائــة وخمســة‬\n      ‫وســبعون ألــف ريــال ســعودي ال غيــر تدفــع ثــاث ســنوات مــن اســتالمي‬\n\n\n‫‪137‬‬\n\f‫املخبــز علــى دفعــات ويف حــال التأخــر عــن الدفــع يحــق لــه أو ملــن ينــوب‬\n‫ا داخــل اململكــة‬    ‫عنــه مبوجــب وكالــه رســمية املطالبــة باملبلــغ كام ـ ً‬\n‫أو خارجهــا يف حــال عــدم متكنــه مــن العــودة إلــى اململكــة واملطالبــة‬\n‫بحقــه مــن خــال قنصليــة اململكــة يف بلــده علمـ ًا بأننــي قــد حــررت لــه‬\n‫شــيك ًا باملبلــغ املذكــور كضمــان حــق مخبــز ‪( ...................‬توقيــع )أ‬\n‫ه ـ وهــذه الورقــة مختومــة بختــم تضمــن مــا نصــه (مخبــز ‪ ........‬لصاحبــه‬\n‫‪ ) ......‬كمــا وجــدت شــيك ًا مســحوب ًا علــى البنــك الســعودي الفرنســي‬\n‫فــرع القطيــف شــارع اخلليفــة عمــر القطيــف ومــؤرخ يف ‪1420/3/2‬ه ـ‬\n‫رقــم الشــيك ‪ 381752‬ألمــر الســيد ‪ ...........‬مببلــغ مائتــن وخمســة‬\n‫وســبعني ألــف ريــال (‪ )275000‬مــن الســادة مخبــز ‪ ...................‬وموقــع‬\n‫كمــا وجــدت شــيك ًا مســحوب ًا علــى البنــك الســعودي ى الفرنســي‬\n‫فــرع القطيــف شــارع اخلليفــة عمــر القطيــف ومــؤرخ يف ‪1420/3/2‬ه ـ‬\n‫رقــم الشــيك ‪ 381751‬ألمــر الســيد ‪ ............‬مببلــغ مائتــن ألــف ريــال‬\n‫(‪ )200000‬مــن الســادة مخبــز ‪ ...........‬وموقــع وبعــرض جميــع ذلــك‬\n‫علــى املدعــى عليــه وكالــة قــال مــا تضمنتــه هــذه املســتندات غيــر‬\n‫صحيــح والتوقيــع مــزور علــى موكلــي هكــذا قــرر وبعــرض ذلــك‬\n‫علــى املدعــي وكالــة قــال ســبق أن دفــع املدعــى عليــه بهــذا الدفــع أمــام‬\n‫مكتــب الفصــل يف منازعــات األوراق التجاريــة باملنطقــة الشــرقية ومتــت‬\n‫الكتابــة لألدلــة اجلنائيــة التــي أثبتــت صحــة التواقيــع املنســوبة للمدعــى‬\n‫عليــه وأطلــب الكتابــة لهــا لالستفســار عــن ذلــك هكــذا قــرر ثــم متــت‬\n‫الكتابــة إلــى فــرع وزارة التجــارة باملنطقــة الشــرقية بخطابنــا رقــم‬\n‫‪ 31/3217‬يف ‪1431/8/6‬ه ـ إلفــادة مبــا لديهــم مــن نتائج حيال التحقيق‬\n‫بشــأن التواقيــع املنســوبة للمدعــى عليــه فوردنــا اجلــواب بخطابهــم رقــم‬\n\n\n                                                                                    ‫‪138‬‬\n\f      ‫‪/4/19/11117‬ف د يف ‪1431/8 /13‬ه ـ برفقــه التقريــر الصــادر مــن‬\n      ‫إدارة الفحــوص الفنيــة بالتزييــف والتزويــر بــاإلدارة العامــة لألدلــة‬\n      ‫اجلنائيــة ويحمــل الرقــم ‪ 30524‬يف ‪1431/6/30‬ه ـ وتضمــن مــا نصــه‬\n      ‫فحــص الشــيكني املســحوبني علــى البنــك الســعودي الفرنســي فــرع‬\n      ‫القطيــف األول برقــم ‪ 381751‬والثانــي برقــم ‪ 381752‬ومؤرخــن يف‬\n      ‫‪1420/3/2‬ه ـ ألمــر املســتفيد الســيد ‪ ..............‬ويحمــل توقيــع منســوب‬\n      ‫للمدعــو ‪ ...............‬علــى حســاب مخبــز ‪ ...............‬مببلــغ إجمالــي قــدره‬\n      ‫أربعمائــة ومئتــان وخمســة وســبعون ألف ـ ًا ومبضاهــاة التوقيعــن الذيــن‬\n      ‫علــى الشــيكني بتواقيــع أخــرى للمدعــو ‪ ..............‬أثبتــت النتيجــة اتفــاق‬\n          ‫التوقيعــن اللذيــن علــى الشــيكني مــع تواقيعــه الثابتــة األخــرى أ ه ـ‬\n      ‫ثــم جــرى االطــاع علــى اإلقــرار الــذي أشــار لــه املدعــى عليــه وكالــة‬\n      ‫واملنســوب للمدعــي أصالــة ‪ ........‬واملتمثــل بصــورة ورقــة مــن مطبوعــات‬\n      ‫مخبــز ‪ ..................‬ومــؤرخ يف ‪98/12/18‬م ويتضمــن إقــراره باســتالم‬\n      ‫جميــع رواتبــه الشــهرية وبــدل اإلجــازة ومكافــأة نهايــة اخلدمــة حتــى‬\n      ‫تاريــخ ‪98/12/20‬م ثــم قــرر املدعــى عليــه وكالــة لــدي إقــرار أخــر‬\n      ‫للمدعــي أصالــة يتضمــن عــدم وجــود أي مســتحقات أو حقــوق يف ذمــة‬\n      ‫موكلــي لصالــح املدعــي أصالــة ثــم قــدم هــذا اإلقــرار وبعــد االطــاع‬\n      ‫عليــه وجدتــه أصــل ورقــة مــن مطبوعــات مخبــز ‪ ...........‬مــؤرخ يف‬\n      ‫‪1420/3/1‬ه ـ ويتضمــن إقــرار املدعــي أصالــة مبــا نصــه ليــس لــي يف‬\n      ‫ذمــة ‪ .................‬صاحــب مخبــز ‪ ..................‬أي حــق وال مســتحق وال‬\n      ‫أي دعــوى وال بــأي وجــه آخــر ومبــا أنــي أعمــل يف املخبــز املذكــور‬\n      ‫بوظيفــة كاتــب حســابات بأنــه ليــس عنــدي أي توقيــع منســوب إلــى‬\n      ‫ـواء كان شــيك ًا أو ورقــة أو يف دفتــر وإذا ظهــر شــيء مــن‬      ‫‪ ..............‬سـ ً‬\n\n‫‪139‬‬\n\f‫هــذا القبيــل يعتبــر الغيـ ًا وال قيمــة لــه وهــذا إقــرار يف ذلــك اعتبــار ًا مــن‬\n‫تاريــخ ‪1420/3/1‬ه ـ أ ه ـ توقيعــه ثــم جــرى ســؤال املدعــي وكالــة عــن‬\n‫اســتعداد موكلــه بــأداء اليمــن علــى صحــة دعــواه فقــال اطلــب إمهالــي‬\n‫حتــى أمتكــن مــن الرجــوع ملوكلــي وســؤاله كمــا إننــي أرى أن اليمــن‬\n‫غيــر متوجهــه علــى موكلــي ألن مــا قدمــه مــن أوراق ومســتندات كافية‬\n‫يف إثبــات اســتحقاق للمبلــغ املدعــى بــه وال حاجــة لليمــن هكــذا قــرر‬\n‫فأجبتــه لذلــك ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه‬\n‫وكالــة وحضــر املدعــي أصالــة ‪ .............‬لبنانــي اجلنســية مبوجــب جــواز‬\n‫الســفر الصــادر مــن اجلمهوريــة اللبنانيــة برقــم ‪ RL.......‬ثــم جــرى عــرض‬\n‫اليمــن علــى املدعــي أصالــة علــى صحــة الشــيكات والتواقيــع املدونــة‬\n‫عليهــا فاســتعد بــأداء اليمــن وحلــف بعــد تخويفــه بــاهلل واإلذن لــه قائــا‬\n‫واهلل العظيــم الــذي ال إلــه غيــره وال رب ســواه ان الشــيكني املؤرخــن‬\n‫يف ‪1420 /3/2‬ه ـ املســحوبني علــى البنــك الفرنســي مــن حســاب املدعى‬\n‫عليــه ‪ ..........‬والذيــن يحمــان مبلــغ وقــدره أربعمائــة و خمســة وســبعون‬\n‫ألــف ريــال وذلــك لــي أنــا كمســتفيد صحيحــان وان التوقيعــن احملررين‬\n‫عليهمــا صــادران مــن املدعــى عليــه نفســه ولــم أقــم بتزويرهــا ومــا زال‬\n‫هــذا املبلــغ مســتحق ًا لــي يف ذمــة املدعــى عليــه حتــى اآلن واهلل العظيــم‬\n‫هكــذا حلــف ثــم جــرى عــرض اإلقــرار املقــدم مــن املدعــى عليــه وكالــة‬\n‫واملنســوب للمدعــي أصالــة عليــه فقــال هــذا اإلقــرار غيــر صحيــح مطلقـ ًا‬\n‫هكــذا قــرر ثــم قفلــت املرافعــة وبعــد ســماع الدعــوى وجوابهــا وحيــث‬\n‫أنكــر املدعــى عليــه الدعــوى وأثبــت املدعــي وكالــة دعــواه بالشــيكني‬\n‫املدونــن بضبــط القضيــة وحيــث دفــع املدعــى عليــه وكالــة بتزويــر‬\n‫الشــيكني وأثبتــت اجلهــة املختصــة بتطابــق التواقيــع احملــررة علــى‬\n\n\n                                                                                           ‫‪140‬‬\n\f      ‫الشــيكني مــع توقيــع املدعــى عليــه األخــرى وحلــف املدعــي أصالــة‬\n      ‫تكملــة لهــذه البينــة لنفــي احتمــال صحــة التزويــر وحيــث إن مــا دفــع بــه‬\n      ‫املدعــى عليــه وكالــة مــن كــون املدعــي أصالــة أقــر بأنــه ليــس لديــه أي‬\n      ‫ا أنــه بينــة‬\n                   ‫توقيــع يف حــال ثبوتــه فتاريخــه ســابق لتاريــخ الشــيكات فضـ ً‬\n      ‫علــى النفــي والشــيكات بينــة علــى اإلثبــات واإلثبــات مقــدم علــى النفــي‬\n      ‫لــذا كلــه فقــد حكمــت بإلــزام املدعــى عليــه بتســليم املدعــي مبلــغ‬\n      ‫أربعمائــة وخمســه وســبعني ألــف (‪ )475000‬ريــال وبعرضــه لــم يقنــع‬\n      ‫بــه املدعــى عليــه وكالــة طالبــا متييــزه فأفهــم باملراجعــة يــوم الســبت‬\n      ‫املوافــق ‪1433/2/13‬ه ـ الســتالم نســخة احلكــم وتقــدمي اعتراضــه‬\n      ‫عليــه خــال ثالثــن يومــا مــن التاريــخ املذكــور وبعــد انتهائهــا دون‬\n      ‫تقــدمي اعتراضــه يســقط حقــه فيــه ويكتســب احلكــم القطعيــة وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                             ‫يف ‪1433/01/04‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1433/8/18‬ه ـ افتتحت‬\n      ‫اجللســة يف متــام الســاعة التاســعة والنصــف وكانــت املعاملــة قــد عــادت‬\n      ‫مــن محكمــة االســتئناف باملنطقــة الشــرقية بخطــاب ســماحة رئيســها‬\n      ‫رقــم ‪3114679‬يف ‪1433/6/4‬ه ـ مرفــق بهــا القــرار الصــادر مــن قضــاة‬\n      ‫الدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف برقــم‪ 33169186‬يف‬\n      ‫‪1433/4/4‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ أن املدعــى عليــه أنكــر‬\n      ‫توقيعــه علــى عقــد املبايعــة كمــا أنكــر توقيعــه علــى اإلقــرار املتضمــن‬\n      ‫أن أي شــيك بتوقيع منســوب ل‪ ...............‬ملغي وألهمية هذين الســندين‬\n      ‫وتأثيرهمــا علــى مجــرى القضيــة فإنــه يلــزم التحقــق مــن صحــة الســندين‬\n\n\n‫‪141‬‬\n\f‫املذكوريــن عــن طريــق اجلهــة املختصــة يف معرفــة صحــة التواقيــع‬\n‫إضافــة إلــى التحقــق مــن قبــل اجلهــة املذكــورة ممــا إذا كان مضمــون‬\n‫الشــيكني قــد متــت كتابتــه يف نفــس وقــت التوقيــع عليهمــا ‪ ،‬فعلــى‬\n‫فضيلتــه مالحظــة ذلــك وإحلــاق مــا يجـ ّـد يف الضبــط وصورتــه وملخصــه‬\n‫يف الصــك وســجله ‪ ،‬ومــن ثــم إعــادة رفــع املعاملــة إلينــا ملواصلــة تدقيــق‬\n‫احلكــم واهلل املوفــق ) أ‪.‬ه ـ وجواب ـ ًا علــى ذلــك أن احلكــم اســتند‬\n‫علــى الشــيكني املســحوبني علــى حســاب املدعــى عليــه ونفــت جهــات‬\n‫التحقيــق صحــة مــا دفــع بــه مــن تزويــر والشــيك أداة وفــاء عرفـ ًا ونظامـ ًا‬\n‫ممــا يؤكــد صحــة الدعــوى ويجعــل جانــب املدعــي قويـ ًا جــد ًا ثــم قمـ ُـت‬\n‫بتحليفــه اليمــن علــى صحــة الدعــوى اســتناد ًا علــى مــا قــرره الفقهــاء ـ ـ‬\n‫رحمهــم اهلل ـ ـ مــن أن اليمــن تشــرع يف جانــب أقــوى املتداعيــن وعليــه‬\n‫فلــم يظهــر لــي خــاف مــا حكمـ ُـت بــه وبــاهلل التوفيــق وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/8/18‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فقــد‬\n‫عــادت املعاملــة مــن الدائــرة احلقوقيــة األولــى ق‪ 1/‬مبحكمــة‬\n‫االســتئناف باملنطقــة الشــرقية وبهــا القــرار ذو الرقــم ‪ 33474175‬يف‬\n‫‪1433/12/20‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة ‪( :‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك وصــورة ضبطــه بنــاء علــى‬\n‫قرارنــا رقــم ‪/33365178‬ق‪/1‬ب يف ‪1433/8/4‬ه ـ لوحــظ أن إجابــة‬\n‫فضيلتــه غيــر مقنعــة ‪ ،‬فعلــى فضيلتــه إجــراء الــازم نحــو مــا ورد يف‬\n‫ـراء للذمــة) أ ‪ .‬ه ـ وجوابـ ًا علــى مشــايخي الفضــاء أنــه‬ ‫قرارنــا الســابق إبـ ً‬\n‫يف حــال كتابتــي للجهــات املختصــة فــإن جوابهــم ال يخلــو مــن حالتــن‬\n\n\n                                                                                        ‫‪142‬‬\n\f      ‫إمــا إثبــات تزويــر الســندين وهــو مــا يكــذب دفــع املدعــى عليــه وإمــا‬\n      ‫بإثبــات صحــة الســندين وذلــك ال يخالــف الدعــوى ألن تاريــخ الشــيكني‬\n      ‫متأخــر عــن الســندين وبقــاء الشــيكني لــدى املدعــي مــع ثبــوت تطابــق‬\n      ‫التواقيــع التــي عليهمــا مــع تواقيــع املدعــى عليــه أصالــة يجعــل جانــب‬\n      ‫ا‬\n      ‫املدعــي هــو املصــدق بيمينــه وقــد حلــف املدعــى علــى ضــوء ذلــك فضـ ً‬\n      ‫أن الســندين ـ ـ يف حــال ثبوتهمــا ‪ -‬بينــة علــى نفــي ســابق والشــيكان بينــة‬\n      ‫علــى إثبــات الحــق واإلثبــات مقــدم علــى النفــي لــذا وبعــد تكــرار وإعــادة‬\n      ‫التأمــل لــم يظهــر لــي خــاف مــا حكمـ ُـت بــه وبــاهلل التوفيــق وصلــى اهلل‬\n             ‫وســلم علــى نبينــا محمــد وآلــه وصحبــه حــرر يف ‪1433/12/29‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق ‪1434/3/6‬ه ـ افتتحــت‬\n      ‫اجللســة يف متام الســاعة التاســعة والنصف وكانت املعاملة قد عادت من‬\n      ‫محكمــة االســتئناف باملنطقــة الشــرقية بخطــاب ســماحة رئيســها رقــم‬\n      ‫‪ 34235153‬يف ‪1434/3/27‬ه ـ مرفــق بهــا القــرار الصــادر مــن قضــاة‬\n      ‫الدائــرة احلقوقيــة األولــى ق‪ 1/‬مبحكمــة االســتئناف برقــم ‪3463325‬‬\n      ‫يف ‪1434/3/16‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n      ‫ـاء علــى قرارنــا رقــم‬\n                           ‫فضيلــة القاضــي وأحلقــه بالصــك وصــورة ضبطــه بنـ ً‬\n      ‫‪ 33365178‬ق‪/1/‬ب يف ‪1433/8/4‬ه ـ وقرارنــا رقــم ‪/33474175‬‬\n      ‫ق‪/1‬ب يف ‪1433/12/20‬ه ـ فقــد قررنــا املصادقــة علــى احلكــم واهلل‬\n      ‫املوفــق ) أ ‪ .‬ه ـ وحتــى ال يخفــى جــرى حتريــره وبــاهلل التوفيــق وصلــى اهلل‬\n          ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/3/6‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n      ‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى‬\n\n\n‫‪143‬‬\n\f‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة القطيــف برقــم‬\n‫‪ 34/24657‬وتاريــخ ‪1434/1/24‬ه ـ واملقيــدة لدينــا برقــم ‪34/235153‬‬\n‫وتاريــخ ‪1434/1/27‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ ‪ ........‬املسـ ّـجل برقــم ‪ 33169186‬وتاريــخ‬\n‫‪1433/4/4‬ه ـ اخلــاص بدعــوى ‪ ( ...........‬لبنانــي اجلنســية ) ضــد ‪............‬‬\n‫يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه‬\n‫ـاء علــى قرارنــا رقــم ‪/33365178‬ق‪/1‬ب يف‬             ‫بالصــك وصــورة ضبطــه بنـ ً‬\n‫‪1433/8/4‬ه ـ و قرارنــا رقــم ‪/33474175‬ق‪/1‬ب يف ‪1433/12/20‬ه ـ‬\n‫فقــد قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه حــرر يف ‪1434/3/16‬ه ـ‬\n                                                              ‫‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                          ‫‪144‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":134,"source_page_end":144,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6aa87361d2a134c94d8a8de771cd288e389b633d4e8e1566d1672ece8dcd8c9e","normalized_text_hash":"582b9efa75217df935e63dc3d936347b1414bd4c9c2c9738e218abc45c6dc30e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p134-33169186"},{"id":"56a62032-84a3-5ca0-8040-42098a2475db","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع سيارة معيبة -املطالبة برد الثمن -التقرير الفني بعيب السيارة -إعادة الثمن .","document_number":"33466823","case_number":"3331141","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام فتحت اجللسة متام بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/27","year":"1434","subject":"بيع -بيع سيارة معيبة -املطالبة برد الثمن -التقرير الفني بعيب السيارة -إعادة الثمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/27 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33466823 :‬‬\n                           ‫َر ْق ُم الدعوى‪3331141 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 3431085‬تاريخه‪1434/2/5 :‬هـ‬\n\n\n       ‫بيــع ‪ -‬بيــع ســيارة معيبــة ‪ -‬املطالبــة بــرد الثمــن ‪ -‬التقريــر الفنــي بعيــب‬\n                                                             ‫الســيارة ‪ -‬إعــادة الثمــن ‪.‬‬\n\n\n\n\n        ‫‪ -‬خيار العيب يثبت فيه إما اإلمساك مع األرش أو الرد وأخذ الثمن‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي بأنــه اشــترى ســيارة مــن مؤسســة املدعــى عليــه وســلمه‬\n       ‫كامــل الثمــن واســتلم الســيارة إال أنــه اكتشــف أنهــا معيبــة فرجــع‬\n       ‫إلــى املؤسســة وتــرك الســيارة عندهــم مطالب ـ ًا رد ثمنهــا‪ ،‬نفــى املدعــى‬\n       ‫عليــه وكالــة وجــود عيــب يف الســيارة‪ ،‬اســتعان املدعــي بشــهود أكــدوا‬\n       ‫صــدق كالمــه متــت الكتابــة إلــى املــرور لفحــص الســيارة وجــاء التقريــر‬\n       ‫مبعيبهــا ‪ ،‬ومبــا أن املدعــى عليــه وكالــة صــا َدق علــى أن املدعــي أرجــع‬\n       ‫الســيارة مباشــرة ومبــا أنــه لــم يظهــر مــن املدعــي مــا يــدل علــى الرضــا‬\n       ‫أن املقــرر عنــد أهــل العلــم أن خيــار العيــب يثبــت‬\n                                                             ‫بالعيــب املذكــور ومبــا َّ‬\n       ‫أن املدعــي‬‫فيــه إمــا اإلمســاك مــع األرش أو الــرد وأخــذ الثمــن ومبــا َّ‬\n       ‫اختــار الــرد وأخــذ ثمنــه ومبــا أن خيــار العيــب ال يحتــاج إلــى حكــم‬\n       ‫حاكــم لــذا فقــد ثبــت أن الســيارة املوصوفــة معيبــة عيبـ ًا شــرعي ًا كمــا‬\n       ‫ثبــت انفســاخ بيــع الســيارة املوصوفــة وصــدر احلكــم علــى املدعــى عليــه‬\n‫‪145‬‬\n\f‫بتســليم املدعــي املبلــغ املدعــى بــه ‪ -‬اعتــرض املدعــى عليــه علــى احلكــم‬\n                            ‫‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫ـدي‬‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لـ َّ‬\n‫أنــا ‪ ...............‬القاضــي باحملكمــة العامــة بالدمــام فتحــت اجللســة متــام‬\n‫بناء على املعاملة‬‫الساعة العاشرة والربع من صباح يوم ‪1433/3/15‬هـ ً‬\n‫احملالــة مــن فضيلــة الرئيــس برقــم ‪ 3331141‬واملقيــدة لــدى احملكمــة‬\n‫برقــم‪ 3379530‬يف ‪1433/ 01 / 11‬ه ـ وبهــا حضــر ‪ ............‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...............‬الوكيــل الشــرعي عــن‬\n‫‪ ...........‬مبوجــب الوكالــة الصــادرة مــن كاتــب عــدل رابغ رقم ‪ 3098‬يف‬\n‫‪1432/12/19‬ه ـ واملتضمنــة أن لــه احلــق يف املرافعــة واملدافعــة وحضــور‬\n‫اجللســات وإقامــة البينــة واالســتالم ولــم يحضــر املدعــى عليــه وقــد جــرى‬\n‫حتديــد هــذا اليــوم متــام الســاعة التاســعة وخمــس وأربعــن دقيقــة موعــد ًا‬\n‫لنظرهــا تبلــغ بهــا املدعــى عليــه لشــخصه حســب إفــادة رئيــس قســم‬\n‫محضــري اخلصــوم حســن عبــد اهلل الزهرانــي ومضــى وقــت اجللســة‬\n‫ولــم يحضــر‪ .‬اهــ‪ .‬بعدهــا قــال املدعــي وكالــة يف حتريــر دعــواه‪ :‬لقــد‬\n‫اشــترى موكلــي مــن مؤسســة املدعــى عليــه وهــي مؤسســة ‪...............‬‬\n‫ســيارة نــوع كامــري جــي إل إكــس فتحــة أوتوماتيــك صنــع عــام ‪2011‬‬\n‫اللــون لؤلــؤي رقــم الشاســيه ‪ .........‬وذلــك بتاريــخ ‪ 1432/11/17‬املوافــق‬\n‫‪2011/10/14‬م بثمــن قــدره ثمــان وثمانــون ألف ـ ًا وثالثمائــة ريــال وســلم‬\n‫لهــم كامــل املبلــغ واســتلم الســيارة والــذي حصــل أن موكلــي بعــد أن‬\n‫خــرج بالســيارة مــن معــرض املدعــى عليــه ذهــب بهــا إلــى قســم الفحــص‬\n\n                                                                                      ‫‪146‬‬\n\f      ‫فوجــد أن الســيارة مغشوشــة وذلــك أنهــا مصبوغــة يف أطــراف الســيارة‬\n      ‫كاملــة فرجــع إلــى املعــرض بعــد أربعــن دقيقــة مــن اســتالمها تقريب ـ ًا‬\n      ‫ووضــع الســيارة عندهــم فوعــده املدعــى عليــه بفحصهــا عــن طريــق‬\n      ‫وكالــة ‪ ............‬ولــم يحصــل شــيء مــن ذلــك ومازالــت الســيارة عندهــم‬\n      ‫حتى اآلن وقد تر َّتب على ذلك اســتئجار موكلي لســيارة أخرى أجرتها‬\n      ‫الشــهرية مبلــغ وقــدره ألــف وثالثمائــة ريــال كمــا أن موكلــي تضــرر‬\n      ‫ضــرر ًا بالغـ ًا حيــث كان يخــرج مــن عملــه ويتــر َّدد علــى مؤسســة املدعــى‬\n      ‫عليــه دون جــدوى لــذا فإنــي موكلــي يطلــب اآلتــي‪ :‬أوالً‪ /‬مبلــغ وقــدره‬\n      ‫ثمــان وثمانــون ألفـ ًا وثالثمائــة ريــال ثمــن الســيارة املوصوفــة‪ .‬ثانيـاً‪ /‬مبلــغ‬\n      ‫وقــدره ســبعة آالف ريــال ثمــن إيجــار الســيارة التــي اســتأجرها موكلــي‪.‬‬\n      ‫ليكــون إجمالــي مــا يطالــب بــه موكلــي املدعــى عليــه مبلــغ وقــدره‬\n      ‫خمســة وتســعون ألف ـ ًا وثالثمائــة ريــال أطلــب إلزامــه بتســليمها‪ .‬هــذه‬\n      ‫ـدي البينــة علــى مــا‬\n                            ‫إجابتــي‪ .‬وبطلــب البينــة مــن املدعــي وكالــة قــال‪ :‬لـ َّ‬\n      ‫ذكــرت أطلــب إمهالــي إلحضارهــا؛ ويف يــوم األربعــاء ‪1433/6/18‬ه ـ‬\n      ‫فتحــت اجللســة متــام الســاعة العاشــرة وبهــا حضــر املدعــي وكالــة كمــا‬\n      ‫حضــر املدعــى عليــه ‪ ..................‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ .................‬الوكيــل الشــرعي عــن ‪ ..................‬مبوجــب‬\n      ‫الوكالــة الصــادرة مــن كتابــة عــدل الدمــام الثانيــة برقــم ‪ 32318‬يف‬\n      ‫‪1432/6/27‬ه ـ واملتضمنــة أن لــه احلــق يف املطالبــة واملرافعــة واملدافعــة‬\n      ‫والصلــح التنــازل ويف هــذه اجللســة جــرى عــرض الدعــوى علــى املدعــى‬\n      ‫عليــه وكالــة وبســؤاله عنهــا أجــاب قائـاً‪ :‬مــا ذكــره املدعــي يف دعــواه‬\n      ‫بعضــه صحيــح وبعضــه غيــر صحيــح فمــا ذكــره مــن كــون موكلــه‬\n      ‫اشــترى الســيارة املذكورة من مؤسســة موكلي وســلم له كامل ثمنها‬\n\n\n‫‪147‬‬\n\f‫وأنــه أرجــع الســيارة إلــى املعــرض فهــذا صحيــح أمــا مــا ذكــره من كون‬\n‫الســيارة مغشوشــة وأنــه أرجعهــا بعــد أربعــن دقيقــة مــن اســتالمها فهــذا‬\n‫غيــر صحيــح والــذي حصــل أن الســيارة وردت إلينــا مــن الوكيــل ومت‬\n‫اســتالمها وبعــد ثالثــة أيــام باعهــا موكلــي للمدعــي أصالــة ثــم أرجعهــا‬\n‫ال‬‫لنــا بعــد يــوم تقريب ـ ًا لكونهــا مغشوشــة ومت فحصهــا فحص ـ ًا شــام ً‬\n‫عــن طريــق وكالــة ‪ .............‬فتبــن أنهــا ســليمة ومــا زالــت الســيارة عنــد‬\n‫موكلــي وال مانــع لديــه مــن تســليمه إياهــا‪ .‬لــذا فــا يســتحق املدعــي‬\n‫علــى دعــواه شــيئ ًا وال ســبيل لــه علــى موكلــي‪ .‬هــذه إجابتــي‪ .‬وبعــد‬\n‫ـدي البينــة‬‫ســماع اإلجابــة قــال املدعــي وكالــة الصحيــح مــا ذكرتــه ولـ َّ‬\n‫علــى مــا ذكــرت وأحضــر للشــهادة وأدائهــا ‪ ...........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .................‬البالــغ مــن العمــر ثالثــن عامـ ًا‬\n‫ويعمــل بــوزارة الصحــة وال قرابــة لــه باملدعــي أصالــة وبســؤاله عمــا لديــه‬\n‫مــن شــهادة أجــاب قائ ـاً‪ :‬أشــهد أنــه يف إحــدى األيــام ال أذكــر تاريــخ‬\n‫ذلــك بالتحديــد رافقــت املدعــي وكالــة إلــى معــرض ‪ ...........‬حيــث‬\n‫أخبرنــي أن أخــاه اشــترى ســيارة منهــم نــوع كامــري صنــع عــام ‪2012‬‬\n‫فقمــت بالشــخوض معــه إلــى املعــرض وأحضــر شــخص فلبينــي يعمــل‬\n‫يف محــات فحــص الســيارات فقــام بفحــص الســيارة التــي أشــار إليهــا‬\n‫املدعــي وكالــة وكان معــه جهــاز وقــام بالفحــص مــن عــدة أماكــن‬\n‫يف الســيارة ثــم قــال للمدعــي وكالــة إن قــراءات الســيارة تختلــف ولــم‬\n‫ـدي‬‫أشــهد عقـ َـد شــراء الســيارة يــن املدعــي واملدعــى عليــه‪ .‬هــذا مــا لـ َّ‬\n‫وبــه أشــهد‪ .‬اهــ‪ .‬كمــا أحضــر للشــهادة وأدائهــا ‪ .........................‬مينــي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...................‬البالــغ مــن العمــر‬\n‫خمســة وعشــرين عام ـ ًا ويعمــل بســمكرة الســيارات وال قرابــة لــه‬\n\n\n                                                                                         ‫‪148‬‬\n\f      ‫باملدعــي وبســؤاله عمــا لديــه مــن شــهادة أجــاب قائ ـاً‪ :‬أشــهد أنــه يف‬\n      ‫أحــد األيــام ال أذكــر تاريــخ ذلــك بالتحديــد أخبرنــي املدعــي وكالــة‬\n      ‫أنــه اشــترى ســيارة مــن ‪ .....‬وطلــب منــي الشــخوص لرؤيتهــا فذهبــت إلــى‬\n      ‫معــرض ‪ .....‬وأشــار إلــى ســيارة نــوع كامــري لونهــا أبيــض أظــن أنهــا‬\n      ‫صنــع عــام ‪2011‬م وحينمــا رأيتهــا اتضــح لــي أن عليهــا أثــر ســمكرة‬\n      ‫يف اجلانــب األيســر ولــم أشــهد عقــد املبايعــة بــن املدعــي واملدعــى عليــه‪.‬‬\n      ‫ـدي وبــه أشــهد‪ .‬اهــ‪ .‬وبعــرض الشــاهدين وشــهادتهما علــى‬       ‫هــذا مــا لـ َّ‬\n      ‫إن‬\n       ‫املدعــى عليــه وكالــة قــال‪ :‬مــا ذكــره الشــاهدان غيــر صحيــح ثــم َّ‬\n      ‫مــا يتعلــق باجلهــاز الــذي مت فحصــه مــن قبــل الفلبينــي فهــو غيــر معتــرف‬\n      ‫بــه وال أقــول يف الشــاهدين شــيئ ًا وال مطعــن فيــه فيهمــا‪ .‬اهــ‪ .‬بعدهــا‬\n      ‫قــررت الكتابــة إلــى مــرور الدمــام مــن أجــل إجــراء الفحــص علــى‬\n      ‫الســيارة عــن طريــق اجلهــة املختصــة بفحــص الســيارات واإلفــادة عــن‬\n      ‫حالتهــا؛ ويف يــوم الثالثــاء ‪1433/8/13‬ه ـ فتحــت اجللســة متــام احلاديــة‬\n      ‫عشــرة وعشــر دقائــق وبهــا حضــر املدعــي وكالــة ولــم حتضــر املدعــى‬\n      ‫عليهــا ولــم يحضــر وكيــل عنهــا وقــد جــرت الكتابــة إلــى مديــر مــرور‬\n      ‫معــارض الدمــام بخطابنــا رقــم ‪ 33/1486355‬يف ‪1433/8/7‬ه ـ فــورد‬\n      ‫إلـ َّـي خطــاب مــرور الدمــام رقــم ‪/298‬م‪/‬ط يف ‪1433/8/12‬ه ـ وبرفقــه‬\n      ‫كشــف املهنــدس وقــد تضمــن أنه مت الكشــف على الســيارة نــوع تويوتا‬\n      ‫صنــع عــام ‪2011‬م نــوع كامــري رقــم اللوحــة ‪ ...............‬اللــون أبيــض‬\n      ‫ملالكهــا ‪ ..................‬وقــد مت االســتعانة بجهــاز حســاب كثافــة الصبــغ‬\n      ‫ووجــد فــارق يف الكثافــة باملقارنــة مــع ســيارات أخــرى لــذا تبــن بعــد‬\n      ‫الكشــف أنــه مت إعــادة صبــغ الســيارة بالكــرو أو الصبــغ حيــث اجلهــاز‬\n      ‫يعطــي عــدة قــراءات يف عــدة أماكــن مــن الســيارة‪ .‬املهنــدس‪ .‬التوقيــع‪.‬‬\n\n\n‫‪149‬‬\n\f‫رئيــس قســم رخــص الســير النقيــب ‪...................‬اهــ‪ .‬ويف يــوم الســبت‬\n‫‪1433/11/27‬ه ـ فتحــت اجللســة متــام الثانيــة عشــرة والنصــف ولــم يتــم‬\n‫فتحهــا يف موعدهــا حللــول وقــت الصــاة وبهــا حضــر املدعــي وكالــة‬\n‫وقــد أبــرز يف هــذه اجللســة وكالــة أخــرى صــادرة مــن كتابــة عــدل رابــغ‬\n‫برقــم ‪ 3093‬يف ‪1433/11/23‬ه ـ وقــد تضمنــت أن لــه احلــق يف املطالبــة‬\n‫واملدافعــة والتنــازل كمــا حضــر املدعــى عليــه وكالــة ‪......................‬‬\n‫املــدون هويتــه ووكالتــه ســابقاً‪ .‬ويف هــذه اجللســة قــرر املدعــي وكالــة‬\n‫قائ ـاً‪ :‬إن موكلــي يحصــر دعــواه يف املطالبــة بــرد ثمــن الســيارة فقــط‬\n‫مــع االحتفــاظ بحقــه يف رفــع دعــوى مســتقلة بشــأن الضــرر املــادي الــذي‬\n‫حلقــه بســبب العيــب يف الســيارة محــل النــزاع‪ .‬اهــ‪ .‬بعدهــا جــرى عــرض‬\n‫خطــاب مــرور الدمــام املــدون ســابق ًا وهــو ذو الرقــم ‪/298‬م‪/‬ط يف‬\n‫‪1433/8/12‬ه ـ مــع قــرار املهنــدس املرفــق علــى املدعــى عليــه وكالــة‬\n‫ـاء‬\n‫فقــال‪ :‬ال أعلــم عــن هــذا القــرار شــيئ ًا وال مطعــن لــي فيــه‪ .‬اهــ‪ .‬فبنـ ً‬\n‫علــى مــا تقـ َّـدم مــن دعــوى املدعــي وكالــة املتضمنــة أن موكلــه اشــترى‬\n‫الســيارة املوصوفــة وأنــه وجــد بهــا عيبـ ًا فأرجــع الســيارة مــن حــن علمــه‬\n‫وطلــب َر َّد ثمنهــا وأن الســيارة لــدى املدعــى عليهــا وجــواب املدعــى عليــه‬\n‫وكالــة املتضمــن املصادقــة علــى شــراء الســيارة بالثمــن املذكــور وأن‬\n‫املدعــي قــام بإرجــاع الســيارة بعــد شــرائها بيــوم تقريبـ ًا وأنكــر كونهــا‬\n‫معيبــة ومبــا أ َّنــه قــد جــرت الكتابــة إلــى مديــر مــرور املعــارض وقــد‬\n‫تضمــن قــرار املهنــدس أنــه مت إعــادة صبــغ الســيارة محــل النــزاع ومبــا‬\n‫أن إعــادة صبــغ الســيارة يعــده التجــار نقص ـ ًا يف قيمــة املبيــع وهــذا هــو‬\n‫ضابــط العيــب الــذي يثبــت بــه اخليــار ( ينظــر‪ :‬الــروض املربــع ‪)441/4‬‬\n‫ومبــا أن املدعــى عليــه وكالــة صــا َدق علــى أن املدعــي أرجــع الســيارة‬\n\n\n                                                                                     ‫‪150‬‬\n\f      ‫مباشــرة ومبــا أنــه لــم يظهــر مــن املدعــي مــا يــدل علــى الرضــا بالعيــب‬\n      ‫أن املقــرر عنــد أهــل العلــم أن خيــار العيــب يثبــت فيــه إمــا‬\n                                                                         ‫املذكــور ومبــا َّ‬\n      ‫أن املدعــي اختــار الــرد‬‫اإلمســاك مــع األرش أو الــرد وأخــذ الثمــن ومبــا َّ‬\n      ‫وأخــذ ثمنــه ومبــا أن خيــار العيــب ال يحتــاج إلــى حكــم حاكــم لــذا فقــد‬\n                                       ‫ـدي أن الســيارة املوصوفــة معيبــة عيب ـ ًا‬‫ثبــت لـ َّ‬\n      ‫ـدي انفســاخ بيــع املؤسســة املدعــى عليهــا الســيارة‬ ‫شــرعي ًا كمــا ثبــت لـ َّ‬\n      ‫املوصوفــة للمدعــي وحكمــت علــى املؤسســة املدعــى عليهــا مؤسســة‬\n      ‫‪ ...............‬بتســليم املدعــي ‪ ..............‬املبلــغ املدعــى بــه وقــدره ثمــان‬\n      ‫وثمانــون ألف ـ ًا وثالثمائــة ريــال وبعــرض احلكــم علــى املدعــى عليــه‬\n      ‫وكالــة قــرر عــدم القناعــة وطلــب رفــع املعاملــة إلى محكمة االســتئناف‬\n      ‫بالئحــة اعتراضيــة فأفهــم بــأن مــدة االعتــراض ثالثــون يوم ـ ًا تبــدأ مــن‬\n      ‫يــوم األربعــاء ‪1433/12/1‬ه ـ إذا مضــت ولــم يقــدم اعتراضــه اكتســب‬\n      ‫احلكــم القطعيــة وأصبــح با َّت ـ ًا واجــب التنفيــذ وكانــت ســاعة النطــق‬\n      ‫باحلكــم متــام الواحــدة ظهــر ًا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/11/27‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/2/25‬ه ـ فتحــت‬\n      ‫اجللسة متام الساعة العاشرة والنصف بناء على ورود املعاملة من محكمة‬\n      ‫االســتئناف باملنطقــة الشــرقية برقم‪34396314‬وتاريخ‪1434/2/13‬ه ـ‬\n      ‫ورفقهــا القــرار رقــم ‪3431085‬وتاريخ‪1434/2/5‬ه ـ واملتضمــن ‪:‬‬\n      ‫املصادقــة علــى احلكــم‪ ،‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                       ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/2/25‬ه ـ ‪.‬‬\n\n\n\n\n‫‪151‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":145,"source_page_end":151,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9b8748591f60ecfeb92fb472ef620e2674ec9f32628e696b872e4604039e0d80","normalized_text_hash":"ee847094cead13b83c85a80b1aefa96429944bca7e920a0d588212c468749d79","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p145-33466823"},{"id":"0bb671d6-fa27-5310-b69e-5afd47ec1e8d","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع أرض محددة احلدود واملعالم بعقد -النص على خلو املبيع من املشاكل وإال فالعقد الغي ا مع اإللزام بإعادة القيمة كاملة -مصادقة املدعى عليه على العقد -وجود مشاكل يف األرض -األصل يف العقود اإللزام -إلزام املدعى عليه بإعادة الثمن.","document_number":"3435647","case_number":"3358940","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط مبوجب قرار رئيس مجلس القضاء األعلى","circuit":"الدائرة احلقوقية األولى برقم 34251014وتاريخ 1434/6/25ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/11","year":"1434","subject":"بيع -بيع أرض محددة احلدود واملعالم بعقد -النص على خلو املبيع من املشاكل وإال فالعقد الغي ا مع اإللزام بإعادة القيمة كاملة -مصادقة املدعى عليه على العقد -وجود مشاكل يف األرض -األصل يف العقود اإللزام -إلزام املدعى عليه بإعادة الثمن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/11 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3435647 :‬‬\n                    ‫َر ْق ُم الدعوى‪3358940 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34251014‬تاريخه‪1434/6/25 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع أرض محــددة احلــدود واملعالــم بعقــد ‪ -‬النــص علــى خلــو‬\n‫املبيــع مــن املشــاكل وإال فالعقــد الغي ـ ًا مــع اإللــزام بإعــادة القيمــة‬\n‫كاملــة ‪ -‬مصادقــة املدعــى عليــه علــى العقــد ‪ -‬وجــود مشــاكل يف‬\n‫األرض ‪ -‬األصــل يف العقــود اإللــزام ‪ -‬إلــزام املدعــى عليــه بإعــادة الثمــن‪.‬‬\n\n\n\n\n                     ‫‪ -‬قوله تعالى ( يا أيها الذين آمنوا أوفوا بالعقود ) ‪.‬‬\n               ‫‪ -‬قوله صلى اهلل عليه وسلم ( املسلمون على شروطهم ) ‪.‬‬\n\n\n\n\n‫اشــترى املدعــي مــن املدعــى عليــه قطعــة أرض محــددة احلــدود واملعالــم‬\n‫مبوجــب عقــد ‪ -‬وقــد نــص يف العقــد علــى تســليم األرض خاليــة مــن‬\n‫املشــاكل ويف حالــة ثبــوت خــاف ذلــك فــإن العقــد يعتبــر الغي ـ ًا مــع‬\n‫إعــادة قيمــة األرض كاملــة ‪ -‬وقــد صــادق املدعــى عليــه علــى ذلــك‪ ،‬إال‬\n‫أن املدعــي بعــد تســلمه لــأرض وجــد بهــا مشــاكل‪ .‬وملــا كان األصــل‬\n‫يف العقــود اإللــزام حكمــت احملكمــة بإلــزام املدعــى عليــه بــرد الثمــن‬\n‫إلــى املدعــي ‪ -‬اعتــرض املدعــى عليــه ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                 ‫االســتئناف ‪.‬‬\n\n\n\n                                                                                    ‫‪152‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي املنتــدب يف احملكمــة‬\n      ‫العامة بخميس مشــيط مبوجب قرار رئيس مجلس القضاء األعلى رقم‬\n      ‫‪ 22536‬يف ‪1433/11/29‬ه ـ واملكلــف بعمــل املكتــب القضائــي الرابع‬\n      ‫مبوجــب خطــاب رئيــس هــذه احملكمــة رقــم ‪ 3433830‬يف ‪1434/1/5‬‬\n      ‫ه ـ وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بخميــس مشــيط برقــم ‪ 3358940‬وتاريــخ ‪ 1433/01/23‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33151869‬وتاريــخ ‪ 1433/01/23‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافــق‪ 1434/02/10‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 30‬‬\n      ‫وفيهــا حضــر ‪ ............... /‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم‪ ...........‬وحضــر حلضــوره ‪ ..........‬يحمــل ســجل مدنــي رقــم ‪..............‬‬\n      ‫ا لقــد اشــتريت مــن هــذا احلاضــر أرض ـ ًا مبدينــة‬      ‫فادعــى األول قائ ـ ً‬\n      ‫‪ ..........‬وحدودهــا وأطوالهــا كالتالــي ‪( :‬الشــمال مخطــط احلســنية‬\n      ‫بطــول الضلــع ‪25‬م اجلنــوب شــارع عــرض ‪15‬م بطــول الضلــع ‪25‬م الشــرق‬\n      ‫قطعــة أرض رقــم ‪ 5‬بطــول الضلــع ‪30‬م الغــرب قطعــة أرض رقــم ‪7‬‬\n      ‫بطــول الضلــع ‪30‬م وكامــل املســاحة اإلجماليــة ‪750‬م) مببلــغ وقــدره‬\n      ‫ثالثــة وخمســون ألــف ريــال وقــد اتفقنــا يف العقــد علــى تســليم األرض‬\n      ‫خاليــة مــن املشــاكل وال يكــون عليهــا أي خــاف وإن ثبــت خــاف ذلــك‬\n      ‫فتلغــى املبايعــة ويعــد العقــد الغيـ ًا وبعــد إمتــام العقــد وتســليم املبلــغ نزلــت‬\n      ‫إلــى األرض املذكــورة وبــدأت يف إنشــاء جــدار حولهــا إال أن أصحــاب‬\n      ‫األراضــي املجــاورة منعونــي وقالــوا إن هــذه األرض ليســت للشــخص‬\n      ‫الــذي باعــك وعليهــا عــدة مشــاكل ولــن منكنــك مــن العمــل فيهــا عندها‬\n\n‫‪153‬‬\n\f‫رجعــت إلــى املدعــى عليــه وأفهمتــه بذلــك ولكنــه رفــض إرجــاع املبلــغ لي‬\n‫لــذا فإنــي أطلــب تنفيــذ العقــد الــذي بيننــا بكامــل شــروطه ‪ ،‬وبعــرض‬\n‫ذلــك علــى املدعــى عليــه أجــاب مــا ذكــره املدعــي يف دعــواه صحيــح‬\n‫ا ولكــن قــد بينــت لــه أن األرض ليــس عليهــا صــك متلــك‬        ‫جملــة وتفصيـ ً‬\n‫والعقــد املبــرم بيننــا صحيــح والتوقيــع توقيعــي وبالرجــوع ألوراق املعاملــة‬\n‫جــرى االطــاع علــى عقــد املبايعــة فوجدتــه متضمنـ ًا مــا يلــي ‪ ( :‬ففــي يــوم‬\n‫الســبت بتاريــخ ‪1433/1/15‬ه ـ مت االتفــاق بــن كل مــن األشــخاص ‪-1‬‬\n‫طــرف أول البائــع ‪ .............‬وعنوانــه خميــس مشــيط حامــل احلفيظــة رقــم‬\n‫‪ ................‬وتاريــخ ‪1416/2/21‬ه ـ ســجل خميــس مشــيط ‪ -2‬طــرف‬\n‫ثانــي املشــتري ‪ .................‬وعنوانــه خميــس مشــيط حامــل احلفيظــة رقــم‬\n‫‪ ...........‬وتاريــخ ‪1406/5/11‬ه ـ ســجل ظهــران اجلنــوب فقــرر الطــرف‬\n‫األول بأنــه بــاع برضائــه واختيــاره ومــن غيــر جبــر وال إكــراه وال تغريــر‬\n‫إلــى الطــرف الثانــي أرض رقــم ‪ 6‬مخطــط الروضــة ( الكــدره ) الكائن‬\n‫يف حــي الــدرب مبدينــة ‪ ...............‬احملــدودة كاآلتــي ‪ :‬الشــمال مخطــط‬\n‫احلســنية بطــول الضلــع ‪25‬م اجلنــوب شــارع عــرض ‪15‬م بطــول الضلع ‪25‬م‬\n‫الشــرق قطعــة أرض رقــم ‪ 5‬بطــول الضلــع ‪30‬م الغــرب قطعــة أرض رقــم‬\n‫‪ 7‬بطــول الضلــع ‪30‬م وكامــل املســاحة اإلجماليــة ‪750‬م وذلــك مبوجــب‬\n‫عقــود مسلســلة حســب العقــود الســابقة وذلــك مبلــغ وقــدره وبيانــه ثالثــة‬\n‫وخمســون ألــف ريــال وقــد اســتلم البائــع مــن القيمــة كامــل املبلــغ‬\n‫ال مــن الطرفــن املبيــع ومت التوقيــع‬    ‫والباقــي ال يوجــد وقــد اســتلم ك ً‬\n‫مبجلــس البيــع وأكــد الطــرف األول بــأن املبــاع خالــي ممــا قــد يســبب‬\n‫عرقلــة اســتفادة الطــرف الثانــي منــه وفيمــا لــو تبــن خــاف ذلــك فــإن‬\n‫الطــرف األول ملــزم بإعــادة القيمــة كاملــة وحتمــل داللــة املكتــب ‪ ،‬أن‬\n\n\n                                                                                      ‫‪154‬‬\n\f      ‫توقيــع الطرفــن علــى هــذا العقــد يعنــي فهمهمــا لــكل الشــروط الــواردة‬\n      ‫بــه وموافقتهمــا علــى مــا جــاء بــه هــذا واهلل ولــي التوفيــق والنجاح ‪ .‬شــهود‬\n      ‫احلــال شــهد بذلــك ‪ .............‬اســمه وتوقيعــه وشــهد بذلــك ‪ ..........‬اســمه‬\n      ‫وتوقيعــه البائــع ‪ ..........‬اســمه وتوقيعــه املشــتري ‪ ...........‬اســمه وتوقيعــه )‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــر ًا لكــون املدعــى عليــه‬\n      ‫قــد أقــر وصــادق علــى العقــد الصــادر بينهمــا وألن األصــل يف العقــود‬\n      ‫اإللــزام والنفــاذ لقولــه تعالــى ( يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود )‬\n      ‫ولقولــه صلــى اهلل عليــه وســلم ( املســلمون علــى شــروطهم ) لذلــك فقــد‬\n      ‫ألزمــت املدعــى عليــه بتســليم املدعــي مبلغـ ًا وقــدره ثــاث وخمســون ألــف‬\n      ‫ريــال وبعــرض احلكــم علــى الطرفــن قــرر املدعــي القناعــة واملدعــى‬\n      ‫عليــه عــدم القناعــة وطلــب االســتئناف مــع تقــدمي الئحــة اعتــراض‬\n      ‫فأجبتــه لطلبــه ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/11‬ه ـ ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/7/18‬ه ـ‬\n      ‫فتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف مبنطقــة‬\n      ‫عســير برقــم ‪ 341461888‬وتاريــخ ‪1434/7/8‬ه ـ واملرفــق بهــا قــرار‬\n      ‫الدائــرة احلقوقيــة األولــى برقــم ‪ 34251014‬وتاريــخ ‪1434/6/25‬ه ـ‬\n      ‫واملوقــع مــن قضــاة الدائــرة احلقوقيــة األولــى واملتضمــن بدراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر املوافقــة‬\n      ‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬قاضــي اســتئناف ‪ .............‬توقيعــه وختمــه وقاضــي‬\n      ‫اســتئناف ‪ ............‬توقيعــه وختمــه ورئيــس الدائــرة ‪ ...............‬توقيعــه‬\n      ‫وختمــه وللبيــان جــرى إحلاقــه حتــى ال يحفــى وبــاهلل التوفيــق وصلــى اهلل‬\n\n\n‫‪155‬‬\n\f                                    ‫نبينــا محمــد حــرر يف ‪1434/7/18‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬املــازم القضائــي يف احملكمــة‬\n‫العامــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بخميــس مشــيط برقــم ‪ 3358940‬وتاريــخ‬\n‫‪ 1433/01/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33151869‬وتاريــخ‬\n‫‪ 1433/01/23‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/09/13‬ه ـ افتتحــت‬\n‫اجللســة الســاعة الواحــدة بعــد الظهــر ‪ ،‬وفيهــا حضــر ‪ ............‬ســعودي‬\n‫اجلنســية بالســجل املدنــي رقــم ‪ ...........‬وقــرر اســتالمه كامــل املبلــغ‬\n‫املدعــى بــه أعــاه وقــدره ثالثــة وخمســون ألــف (‪ )53000‬ريــال ولــم‬\n‫يبــق لــه مطالبــة جتــاه املدعــى عليــه بخصــوص هــذه الدعــوى وعليــه‬\n‫تكــون هــذه الدعــوى منتهيــة ‪ .‬وللبيــان جــرى إحلاقــه ‪ .‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                          ‫‪ 1434/09/13‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪156‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":152,"source_page_end":156,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f95ba851b930938b62eaf1a855d076a7902ca275b6cdf70ad6786e857eafcc21","normalized_text_hash":"f4566def7894b47205dbe319bfc0fce564563138665a9d14978063ad3c67ece6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p152-3435647"},{"id":"ad081d27-ff0f-5cad-9381-670615c8fe15","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -ثمن مبيع -مطالبة املضمون له الضام ن بتسليم ما بقي من ثمن املكيفات -غياب املدعى عليه وتبلغه لشخصه -االطاع على العقود والكمبياالت ،وحلف املدعي مين االستظهار -احلكم على الضامن بتسليم باقي ثمن املكيفات -اعتبار احلكم حضوري ا .","document_number":"33132641","case_number":"3361783","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبنطقة تبوك لتقرير ما يرونه أصحاب الفضيلة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/3/14","year":"1434","subject":"بيع -ثمن مبيع -مطالبة املضمون له الضام ن بتسليم ما بقي من ثمن املكيفات -غياب املدعى عليه وتبلغه لشخصه -االطاع على العقود والكمبياالت ،وحلف املدعي مين االستظهار -احلكم على الضامن بتسليم باقي ثمن املكيفات -اعتبار احلكم حضوري ا .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/3/14 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33132641 :‬‬\n                          ‫َر ْق ُم الدعوى‪3361783 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34232762‬تاريخه‪1434/2/9 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬ثمــن مبيــع ‪ -‬مطالبــة املضمــون لــه الضامـ َـن بتســليم مــا بقــي‬\n      ‫مــن ثمــن املكيفــات‪ -‬غيــاب املدعــى عليــه وتبلغــه لشــخصه ‪ -‬االطــاع‬\n      ‫علــى العقــود والكمبيــاالت ‪ ،‬وحلــف املدعــي ميــن االســتظهار ‪ -‬احلكــم‬\n      ‫علــى الضامــن بتســليم باقــي ثمــن املكيفــات‪ -‬اعتبــار احلكــم حضوريـ ًا ‪.‬‬\n\n\n\n\n                    ‫‪ .1‬قوله تعالى‪( :‬وملن جاء به حمل بعير وأنا به زعيم) ‪.‬‬\n                           ‫‪ .2‬قوله صلى اهلل عليه وسلم‪ ( :‬الزعيم غارم ) ‪.‬‬\n      ‫‪ .3‬املــواد ‪ 1/55‬و ‪ 2/55‬و‪ 178‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n                                                               ‫التنفيذيــة ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي أنــه بــاع خمســة مكيفــات بقيمــة إجماليــة قدرهــا اثنــا‬\n      ‫عشــر ألف ـ ًا وخمســمائة ريــال مقســطة علــى أقســاط شــهرية مقــدار‬\n      ‫القســط الواحــد ألفــان وخمســمائة ريــال وأن املشــتري ســلم مــن الثمــن‬\n      ‫ألفــن وســتمائة ريــال وبقــي يف ذمتــه تســعة آالف وتســعمائة ريــال‬\n      ‫كلهــا حالــة ‪ ،‬وأن املدعــى عليــه الغائــب عــن مجلــس احلكــم‪ ،‬واملتبلــغ‬\n      ‫لشــخصه ‪ ،‬قــد كفــل املشــتري كفالــة غرميــة‪ ،‬وطلــب إلــزام املدعــى‬\n      ‫عليــه بتســليم املبلــغ الــذي يدعــي بــه وقــدره تســعة آالف وتســعمائة ريــال‬\n\n‫‪157‬‬\n\f‫حــا ًال ‪ -‬بطلــب البينــة مــن املدعــي علــى صحــة دعــواه أبــرز عقديــن‪،‬‬\n‫وســندين ‪ ،‬وبتفحصهــا وجــد مضمونهــا كمــا ذكــر املدعــي يف دعــواه‬\n‫‪ -‬بطلــب ميــن االســتظهار مــن املدعــي علــى دعــواه‪ ،‬حلفهــا ‪ -‬بنــاء علــى‬\n‫مــا أبــرزه املدعــي مــن العقــود والســندات املبرمــة بينــه وبــن املدعــى عليــه‬\n‫‪ -‬وأداء املدعــي ميــن االســتظهار علــى بقــاء حقــه يف ذمــة املدعــى عليــه‬\n‫‪ -‬وتبلــغ املدعــى عليــه لشــخصه‪ ،‬ولــم يحضــر واســتناد ًا للمــواد ‪ 1/55‬و‬\n‫‪ 2/55‬و‪ 178‬مــن نظــام املرافعــات الشــرعية ولوائحــه ‪ -‬ولقولــه تعالــى‬\n‫(وملــن جــاء بــه حمــل بعيــر وأنــا بــه زعيــم ) وقولــه صلــى اهلل عليــه وســلم‬\n‫( الزعيــم غــارم ) ‪ -‬ثبــت أن يف ذمــة املدعــى عليــه لصالــح املدعــي مبلغـ ًا‬\n‫وقــدره تســعة آالف وتســعمائة ريــال كلهــا حالــة يف ذمتــه ‪ -‬مت احلكــم‬\n‫بإلزامــه بدفــع هــذا املبلــغ حــا ًال ‪ -‬يعــد احلكــم يف حــق املدعــى عليــه‬\n‫حضوريـ ًا ‪ -‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫هــذا اليــوم األحــد املوافــق ‪1433/2/21‬ه ـ الســاعة الثامنــة والنصــف‬\n‫صباح ـ ًا فتحــت اجللســة لــدي أنــا (‪ )....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫ـاء علــى املعاملــة احملالــة لــي بشــرح فضيلــة الرئيــس املســاعد‬ ‫بتبــوك بنـ ً‬\n‫برقــم ‪ 3361783‬وتاريــخ ‪1433/1/24‬هـ ـ وفيهــا حضــر املدعــي ‪...........‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )............‬ولــم يحضــر‬\n‫املدعــى عليــه ‪ ...........‬ولــم تــرد إفــادة بتبلغــه مــن عدمــه لــذا ســيجري‬\n‫حتديــد موعــد آخــر وذلــك يف يــوم األحد املوافق ‪1433/3/13‬هـ الســاعة‬\n‫احلاديــة عشــرة والنصــف صباحـ ًا وعليــه جــرى التوقيــع وصلــى اهلل وســلم‬\n\n                                                                                        ‫‪158‬‬\n\f      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن وحــرر يف الســاعة الثامنــة‬\n                        ‫والنصــف مــن ضحــى يــوم األحــد املوافــق ‪1433/2/21‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعده وبعــد ففي هذا‬\n      ‫اليــوم االثنــن املوافــق ‪1433/3/14‬ه ـ الســاعة احلاديــة عشــرة والنصــف‬\n      ‫صباحـ ًا فتحــت اجللســة لــدي أنــا ‪ ...............‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫ـاء علــى املعاملــة احملالــة لــي مــن فضيلــة الرئيــس املســاعد‬     ‫بتبــوك بنـ ً‬\n      ‫برقــم ‪ 3361783‬يف ‪1433/1/24‬ه ـ وفيهــا حضــر املدعــي ‪............‬‬\n      ‫ســعودي مبوجــب الســجل املدنــي رقــم ( ‪ ) ............‬فادعــى ضــد الغائــب‬\n      ‫عــن مجلــس احلكــم الشــرعي ‪ .........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم (………‪ )..‬ويعمــل عســكري ًا يف ســرية ‪ ........‬مبنطقــة‬\n      ‫ا يف حتريــر دعــواه عليــه ‪ :‬لقــد بعــت للمدعــو ‪ ............‬عــدد‬  ‫تبــوك قائ ـ ً‬\n      ‫خمســة مكيفــات مــن نــوع هوائــي بقيمــة إجماليــة قدرهــا اثنــا عشــر‬\n      ‫ألفـ ًا وخمســمائة ريــال وذلــك علــى أقســاط شــهرية قيمــة القســط الواحد‬\n      ‫ـداء مــن تاريــخ ‪1433/12/27‬ه ـ وقــد‬    ‫ألفــان وخمســمائة ريــال وذلــك ابتـ ً‬\n      ‫ســدد مبلغ ـ ًا وقــدره ألفــان وســتمائة ريــال وتبقــى يف ذمتــه تســعة آالف‬\n      ‫وتســعمائة ريــال كلهــا حالــة يف ذمتــه وقــد كفلــه املدعــى عليــه الغائــب‬\n      ‫عــن مجلــس احلكــم الشــرعي كفالــة غــرم وأداء وذلــك حســب العقــد‬\n      ‫املرفــق باملعاملــة برقــم (‪ )00570‬وتاريــخ ‪1432/1/3‬ه ـ والعقــد املرفــق‬\n      ‫برقــم (‪ )00551‬وتاريــخ ‪1431/12/27‬ه ـ وحســب الســندين املرفقــن‬\n      ‫برقــم (‪ )0061‬ورقــم (‪ )0159‬لــذا أطلــب إلــزام املدعــى عليــه بتســديد‬\n      ‫جميــع املبلــغ الــذي أدعــي بــه وقــدره تســعة آالف وتســعمائة ريــال حــا ًال‬\n      ‫هــذه دعــواي ومبــا أن املدعــى عليــه قــد تبلــغ بنفســه مبوعــد األمــس يف‬\n      ‫يــوم األحــد املوافــق ‪1433/3/13‬ه ـ يف الســاعة احلاديــة عشــرة والنصــف‬\n\n\n‫‪159‬‬\n\f‫صباحـ ًا حســب خطــاب محضــري اخلصــوم يف احملكمــة واملرفــق أصلــه‬\n‫يف املعاملــة ومت انتظــاره حتــى نهايــة الــدوام ولــم يحضــر ولــم يقــدم عــذر ًا‬\n‫عــن عــدم حضــوره ولــم يقــدم مذكــرة بدفاعــه لــذا فقــد طلبــت مــن‬\n‫املدعــي البينــة علــى صحــة دعــواه فأبــرز العقــد املرفــق باملعاملــة برقــم‬\n‫(‪ )00570‬وتاريــخ ‪1432/1/3‬ه ـ والعقــد املرفــق برقــم (‪ )00551‬وتاريــخ‬\n‫‪1431/12/27‬ه ـ كمــا أبــرز الســندين املرفقني باملعاملــة برقم (‪)0061‬‬\n‫ورقــم (‪ )0159‬وبتفحصهــا وجــدت مضمونهــا كمــا ذكــر املدعــي يف‬\n‫دعــواه وقــد أرفقــت يف املعاملــة صــورة مــن جميــع مــا ذكــر ثــم أفهمــت‬\n‫املدعــي أن عليــه اليمــن الشــرعية علــى بقــاء حقــه يف ذمــة املدعــى‬\n‫ا ( أقســم بــاهلل العظيــم أننــي‬ ‫عليــه فتفهــم ذلــك فأذنــت لــه فحلــف قائ ـ ً‬\n‫قــد بعــت املدعــو ‪ .......‬عــدد خمســة مكيفــات مــن نــوع هوائــي بقيمــة‬\n‫إجماليــة قدرهــا اثنــا عشــر ألف ـ ًا وخمســمائة ريــال وقــد وصلنــي مــن‬\n‫املبلــغ ألفــان وســتمائة ريــال وتبقــى يف ذمتــه تســعة آالف وتســعمائة ريــال‬\n‫لــم يســدده لــي حتــى اآلن وهــي حالــة يف ذمتــه وقــد كفلــه املدعــى عليــه‬\n‫الغائــب عــن مجلــس احلكــم الشــرعي ‪ .........‬كفالــة غــرم وأداء أقســم‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى وللبينــة‬  ‫بــاهلل العظيــم علــى هــذا ) فبنـ ً‬\n‫التــي ذكرهــا املدعــي يف دعــواه وهــي العقــود والســندات املبرمــة بينــه‬\n‫وبــن املدعــى عليــه وذلــك بتوقيعــه وإمضائــه ونظــر ًا ألداء املدعــي ميــن‬\n‫االســتظهار علــى بقــاء حقــه يف ذمــة املدعــى عليــه ونظــر ًا لتبلــغ املدعــى‬\n‫عليــه بنفســه مبوعــد هــذه اجللســة ولــم يحضــر واســتناد ًا للمادتــن ‪1/55‬‬\n‫و ‪ 2/55‬و‪ 178‬مــن نظــام املرافعــات الشــرعية ولوائحــه وبعــد اطالعــي‬\n‫علــى الكمبيالــة املشــار إليهــا وجــدت مضمونــه كمــا ذكــر املدعــي‬\n‫يف دعــواه ولقولــه تعالــى ( وملــن جــاء بــه حمــل بعيــر وأنــا بــه زعيــم )‬\n\n\n                                                                                        ‫‪160‬‬\n\f      ‫وقولــه صلــى اهلل عليــه وســلم ( الزعيــم غــارم ) لــذا فقــد ثبــت لــدي أن‬\n      ‫يف ذمــة املدعــى عليــه ‪ ...........‬لصالــح املدعــي مبلغ ـ ًا وقــدره تســعة آالف‬\n      ‫وتســعمائة ريــال كلهــا حالــة يف ذمتــه وقــررت إلزامــه بدفــع املبلــغ حــا ًال‬\n      ‫هــذا مــا ظهــر لــي وبــه حكمــت ويعــد احلكــم يف حــق املدعــى عليــه‬\n      ‫حضوري ـ ًا وقــد قــررت بعــث نســخة مــن الصــك لــه إلبالغــه بــه وإفهامــه‬\n      ‫بــأن لــه حــق االعتــراض علــى احلكــم مــدة ثالثــن يومــا مــن تاريــخ التبليــغ‬\n      ‫فــإن لــم يقــدم اعتراضــه فــإن احلكــم يكتســب الصفــة القطعيــة وعليــه‬\n      ‫جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫أجمعــن حــرر يف الســاعة احلاديــة عشــرة وأربعــن دقيقــة مــن ضحــى‬\n      ‫يــوم االثنــن املوافــق ‪1433/3/14‬ه ـ حمــد هلل وحــده وبعــد ففــي هــذا‬\n      ‫اليــوم الثالثــاء املوافــق ‪1434/1/20‬ه ـ الســاعة احلاديــة عشــرة صباح ـ ًا‬\n      ‫فتحــت اجللســة وفيهــا مت االطــاع علــى هــذه املعاملــة وقــد متــت الكتابــة‬\n      ‫بشــأن تبليــغ املدعــى عليــه بنســخة احلكــم أكثــر مــن مــرة ولــم جنــد‬\n      ‫جوابـ ًا حيــث مت متــت الكتابــة ألول مــرة بتاريــخ ‪1433/3/15‬ه ـ لســعادة‬\n      ‫قائــد مجموعــة الشــرطة ‪ ..........‬بتبوك ـ بشــأن تبليــغ املدعــى عليــه ولــم‬\n      ‫تــرد إفــادة ثــم جــرت الكتابــة بخطــاب إحلاقــي بتاريــخ ‪1433/6/22‬ه‬\n      ‫ولــم تــرد إفــادة ثــم جــرت الكتابــة مــرة ثالثــة حســب اخلطــاب املــؤرخ يف‬\n      ‫‪1433/9/12‬ه ـ ولــم تــرد إفــادة حتــى تاريخــه ‪ ،‬وحيــث األمــر مــا ذكــر‬\n      ‫وألن أمــد القضيــة قــد طــال ‪ ،‬والظــن أنــه يصعــب تبلــغ املدعــى عليــه‬\n      ‫باحلكــم لــذا فإنــي أرفــع املعاملــة إلــى أصحــاب الفضيلــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة تبــوك لتقريــر مــا يرونــه أصحــاب الفضيلــة ‪ ،‬وعليــه‬\n      ‫جــرى التوقيــع ‪ ،‬حــرر يف الســاعة احلاديــة عشــرة والنصــف مــن ضحــى‬\n                                                 ‫يــوم الثالثــاء املوافــق ‪1434/1/20‬ه ـ‬\n\n\n‫‪161‬‬\n\f‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ :‬فقــد اطلعنــا نحــن‬\n‫قضــاة الدائــرة احلقوقيــة األولــى يف محكمــة االســتئناف مبنطقــة تبــوك‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك‬\n‫برقــم ‪ 33159943‬وتاريــخ ‪1434/1/25‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة الشــيخ ‪ .............‬وفقــه اهلل برقــم ‪ 33132641‬وتاريــخ‬\n‫‪1433/3/14‬ه ـ اخلــاص بدعــوى ‪ ...........‬ضــد ‪ ...........‬وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة جــرت املصادقــة علــى احلكــم وبــاهلل‬\n          ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                               ‫‪162‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":157,"source_page_end":162,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b18f9c7dfd559bb910ac9783028a798f34b995afd7e80a664c5984213841c571","normalized_text_hash":"a31117343cb9885d95613a29f8414e497602dde1a79a537ff3f6fab267f96a7f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p157-33132641"},{"id":"51b81cfa-4dd1-5deb-89da-c2200286291d","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع رؤوس غنم دون قبض الثمن -عدم حضور املدعى عليه -شهادة الشهود العدول ومين املدعي -احلكم غيابي ا بدفع الثمن املطالب به -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","document_number":"33457039","case_number":"3384608","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/16","year":"1434","subject":"بيع -بيع رؤوس غنم دون قبض الثمن -عدم حضور املدعى عليه -شهادة الشهود العدول ومين املدعي -احلكم غيابي ا بدفع الثمن املطالب به -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/16 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33457039 :‬‬\n                           ‫َر ْق ُم الدعوى‪3384608 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34214353‬تاريخه‪1434/5/18 :‬هـ‬\n\n\n       ‫بيــع ‪ -‬بيــع رؤوس غنــم دون قبــض الثمــن ‪ -‬عــدم حضــور املدعــى عليــه‬\n       ‫‪ -‬شــهادة الشــهود العــدول وميــن املدعــي ‪ -‬احلكــم غيابيـ ًا بدفــع الثمــن‬\n       ‫املطالــب بــه ‪ -‬الغائــب علــى حجتــه متــى حضــر ‪ -‬رفــع احلكــم حملكمــة‬\n                                ‫االســتئناف لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪.‬‬\n\n\n\n\n       ‫‪ -1‬قــال ابــن تيميــة‪( :‬وقــد ثبــت يف صحيــح مســلم عــن ابــن عبــاس أن‬\n       ‫النبــي صلــى اهلل عليــه وســلم قضــى بشــاهد وميــن رواه الترمــذي وابــن‬\n       ‫ماجــه مــن حديــث جابــر ورواه أبــو داود والترمــذي وابــن ماجــه مــن‬\n       ‫حديــث أبــي هريــره وروي ذلــك عــن النبــي مــن وجــوه كثيــره وهــذه‬\n       ‫األحاديــث أصــح وأشــهر مــا روي عــن النبــي صلــى اهلل عليــه وســلم يف‬\n       ‫هــذا البــاب وابــن عبــاس رضــي اهلل عنــه الــذي يــروي عــن النبــي صلــى‬\n       ‫اهلل عليــه وســلم أنــه قضــى باليمــن مــع الشــاهد وأن هــذا قضــي بــه يف‬\n                  ‫دعــاوى وأقــر بهــذا بدعاوى)أ‪.‬ه ـ مجمــوع الفتــاوى ‪،139/35‬‬\n       ‫‪ -2‬قــال ابــن القيــم رحمــه اهلل تعالــى يف كتابــه الطــرق احلكميــة يف‬\n       ‫السياســة الشــرعية ص ‪172‬مانصــه (احلكــم بالشــاهد واليمــن وهــو‬\n       ‫مذهــب فقهــاء احلديــث كلهــم ومذهــب فقهــاء األمصــار مــا خــا أبــي‬\n                                                        ‫حنيفــة وأصحابــه) أ‪.‬هــ‪.‬‬\n       ‫‪ -3‬قــال ابــن قدامــة رحمــه اهلل تعالــى يف كتابــه الــكايف ‪ 128/6‬مــا‬\n\n\n‫‪163‬‬\n\f‫نصه(فــإن امتنــع اخلصــم مــن احلضــور عنــد احلاكــم حكــم عليــه‬\n‫ألنــه لــو لــم يحكــم عليــه جلعــل االمتنــاع واالســتتار طريق ـ ًا لتضييــع‬\n                                                                 ‫احلقــوق) ا‪.‬هــ‪.‬‬\n‫‪ -4‬قــال أبــو إســحاق إبراهيــم بــن احلســن يف كتابــه معــن احلــكام‬\n‫‪ 615/2‬مــا نصــه ( مســألة قــال املــاوردي يف تفســير قــول اهلل تعالــى « وإذا‬\n‫دعــوا إلــى اهلل ورســوله ليحكــم بينهــم » اآليــة دليــل علــى أنــه مــن دعــي‬\n‫إلــى حاكــم مــن حــكام املســلمني فعليــه اإلجابــة ويجــرح إن تأخــر وقــد‬\n‫ورد عــن احلســن بــن علــي رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه‬\n‫وســلم قــال « مــن دعــي إلــى حاكــم مــن حــكام املســلمني فلــم يجــب فهــو‬\n                                                            ‫ظالــم ال حــق لــه) ‪.‬‬\n                     ‫‪ -5‬املواد (‪ 53‬و‪ 55‬و‪ )56‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫بــاع املدعــي للمدعــى عليــه بعضـ ًا مــن رؤوس املاعــز دون قبــض الثمــن‪،‬‬\n‫طالــب املدعــي املدعــى عليــه بالســداد إال أنــه لــم يحضــر‪ ،‬قــدم املدعــي‬\n‫لصحــة دعــواه ورقــة أقّ ــر فيهــا املدعــى عليــه مبديونيــة للمدعــي باملبلــغ‬\n‫املطالــب بــه‪ ،‬كمــا قــدم شــاهدين عدلــن وحلــف اليمــن الشــرعية‬\n‫تأكيــد ًا لذلــك‪ .‬لــذا حكمــت احملكمــة غيابي ـ ًا بإلــزام املدعــى عليــه‬\n‫بدفــع املبلــغ املطالــب بــه‪ ،‬مصادقــة محكمــة االســتئناف علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪164‬‬\n\f      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ..............‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 3384608‬وتاريــخ ‪ 1433/2/2‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33222671‬وتاريــخ ‪ 1433/2/2‬ه ـ املتعلقــة بدعــوى‬\n      ‫‪ .............‬ضــد ‪ ...........‬يف دعــوى يف مبلــغ ويف يــوم االحــد ‪1433/4/18‬‬\n      ‫ه ـ افتتحــت اجللســة يف متــام الســاعة العاشــرة والنصــف صباحــا وجــرى‬\n      ‫النــداء علــى املدعــي واملدعــى عليــه فلــم يحضــر منهمــا أحــد ولــم يقدمــا‬\n      ‫عــذر لتخلفهمــا عــن هــذه اجللســة ولــم يتقــدم وكيــل عــن اي منهمــا وقــد‬\n      ‫حــدد لهمــا موعــد يف هــذا اليــوم يف متــام الســاعة العاشــرة صباحــا وجــرى‬\n      ‫النــداء واالنتظــار مــن بدايــة وقــت اجللســة وحتــى انتهــاء وقتهــا فلم يحضر‬\n      ‫أحــد وقــد مت بعــث تبليــغ للمدعــى عليــه عــن طريــق محضــري اخلصــوم‬\n      ‫بهــذه احملكمــة برقــم ‪ 33235040‬يف ‪1433/2/6‬ه ـ ووقــد أفادنــا‬\n      ‫احملضــر بهــذه احملكمــة ‪ ..........‬انــه مت تســليم التبليــغ لعمــدة حــي نخــب‬\n      ‫ولــم يردنــا مــا يفيــد بتبليــغ املدعــى عليــه مــن عدمــه فعليــه وبنــاء علــى‬\n      ‫املــادة (‪ )53‬مــن نظــام املرافعــات الشــرعية فقــد أمــرت بشــطب هــذه‬\n      ‫القضيــة للمــرة األولــى وال تنظــر إال بعــذر يتقــدم بــه املدعــي أو وكيــل‬\n      ‫عنــه وتقبلــه احملكمــة وأمــرت بحفــظ هــذه الدعــوى يف األرشــيف وباهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                       ‫‪1433/4/18‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n\n\n‫‪165‬‬\n\f‫العامــة بالطائــف برقــم ‪ 3384608‬وتاريــخ ‪ 1433/02/02‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33222671‬وتاريــخ ‪ 1433/02/02‬ه ـ ويف يــوم‬\n‫الســبت ‪ 1433/07/12‬ه ـ افتتحــت اجللســة الســاعة ‪11.20‬للنظــر يف‬\n‫الدعــوى املرفوعــة مــن ‪ ............‬ضــد ‪ ...........‬يف دعــوى يف مبلــغ مالــي‬\n‫وفيهــا حضــر املدعــي ‪ ............‬يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪...........‬‬\n‫ولــم يحضــر املدعــى عليــه ‪ .......‬ولــم يــرد إلينــا مــا يفيــد بتبليغــه فعليــه‬\n‫وبنــاء علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية فقــد‬\n‫قــررت النظــر يف دعــوى املدعــي يف غيــاب املدعــى عليــه فجــرى ســؤال‬\n‫املدعــي عــن دعــواه علــى الغائــب عــن املجلــس الشــرعي فقــال ادعــي علــى‬\n‫الغائــب عــن املجلــس الشــرعي ‪ ........‬بــأن قــد اشــترى منــي أربعــن رأســا‬\n‫مــن املاعــز يف ‪1431/9/14‬ه ـ مببلــغ خمســة وعشــرين ألــف ريــال علــى‬\n‫أن يســددها يف ‪1432/10/30‬ه ـ مببلــغ خمســة وعشــرين ألــف ريــال‬\n‫ولــم يصلنــي منهــا أي شــيء ولــم أقــم بإعفائــه عــن أي جــزء وهــذا املبلــغ‬\n‫جميعــه حــال لــذا أطلــب إلــزام املدعــى عليــه بــأن يدفــع لــي مبلــغ خمســة‬\n‫وعشــرين ألــف ريــال هــذه دعــواي فجــرى ســؤاله هــل لديــك البينــة علــى‬\n‫صحــة دعــواك فقــال نعــم ثــم ابــرز ورقــة وتتضمــن مــا نصــه( أقــر انــا‬\n‫‪ .........‬بــأن يف ذمتــي مبلــغ خمســة وعشــرين ألــف ريــال لــأخ ‪ ..........‬يقــوم‬\n‫بســدادها يف ‪1432/1/30‬ه ـ املقــر بصمتــه ) أ‪.‬ه ـ فجــرى ســؤاله هــل‬\n‫لديــك زيــادة بينــة فقــال نعــم وأطلــب املهلــة إلحضارهــا هكــذا قــرر ثــم‬\n‫رفعــت اجللســة يف الســاعه‪ 11.30‬وحتــى يــوم الثالثــاء ‪1433/11/16‬ه ـ‬\n‫الســاعة ‪10.00‬صباحــا و حــرر يف ‪ 1433/07/12‬ه ـ ‪ ،‬وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء ‪ 1433/11/16‬ه ـ افتتحــت‬\n\n\n                                                                                          ‫‪166‬‬\n\f      ‫اجللســة الســاعة ‪ 11،00‬وفيهــا حضــر املدعــي ‪............‬املدونــة هويتــه‬\n      ‫ســابقا ولــم يحضــر املدعــى عليــه ‪ .........‬ولــم يــرد إلينــا مــا يفيــد بتبليغــه‬\n      ‫فجــرى ســؤال املدعــي هــل أحضــرت البينــة التــي وعــدت بهــا فقــال نعــم‬\n      ‫ثــم احضــر ‪ ........‬يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪ ...............‬من مواليد‬\n      ‫‪1364/7/1‬ه ـ وذكــر بأنــه يســكن يف الشــهداء اجلنوبيــة ومتقاعــد وان‬\n      ‫املدعــي مــن اجلماعــة أمــا املدعــى عليــه فليــس بينــي وبينــه أي قرابــه‬\n      ‫وبســؤاله عمــا لديــه مــن شــهاده قــال اشــهد هلل تعالــى انــه باألمــس يــوم‬\n      ‫االثنــن ‪1433/11/15‬ه ـ ذهبــت أنــا واملدعــي علــى منــزل املدعــى عليــه‬\n      ‫‪ ............‬والوقــع بــوادي النمــل وتقابلنــا مــع املدعــى عليــه يف الشــارع‬\n      ‫وقــد قــرر أمامــي املدعــى عليــه ‪................‬بــأن يف ذمتــه ل‪ .........‬مبلــغ‬\n      ‫خمســة وعشــرين ألــف ريــال وذلــك قيمــة غنــم ولكنــه يطلــب الصلــح يف‬\n      ‫ذلــك ولــم يوافقــه املدعــي وكان ذلــك قبــل آذان املغــرب هــذا مــا لــدي‬\n      ‫وبــه اشــهد هكــذا اشــهد فجــرى ســؤال املدعــي هــل لديــك زيــادة بينــة‬\n      ‫فقــال ليــس لــدي ســوى مــا أحضــرت هكــذا قــرر ثــم احضــر مزكيــن‬\n      ‫لشــاهده وهمــا ‪ ..........‬يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪.........‬و‪..........‬‬\n      ‫يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪.............‬وبســؤالهما عمــا لديهمــا مــن‬\n      ‫شــهاده شــهدا كل واحــد منهمــا مبفــرده قائــا اشــهد هلل تعالــى بــأن‬\n      ‫شــاهد املدعــي وهــو ‪ ............‬ثقــة عــدل مرضــي الشــاهدة هــذا مــا لدينــا‬\n      ‫وبــه نشــهد هكــذا شــهدا فجــرى ســؤال املدعــي هــل انــت مســتعد ببــذل‬\n      ‫اليمــن تكملــة للشــاهد فقــال نعــم فجــرى نصحــه وتخويفــه بــاهلل عــز‬\n      ‫وجــل مــن مغبــة هــذه اليمــن إال انــه أصــر فأذنــت فحلــف قائــا واهلل‬\n      ‫العظيــم الــذي ال إلــه هــو املهلــك املــدرك بــأن املدعــى عليــه الغائــب عــن‬\n      ‫املجلــس الشــرعي ‪ .............‬قــد اشــترى منــي اربعــن رأســا مــن املاعــز‬\n\n\n‫‪167‬‬\n\f‫مببلــغ خمســة وعشــرين ألــف ريــال وهــذا املبلــغ جميعــه حــال ولــم يصلنــي‬\n‫منــه أي شــيء ولــم أقــم بإعفائــه عــن أي جــزء واهلل العظيــم هكــذا حلــف‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى وبنــاء علــى املــادة اخلامســة واخلمســن‬\n‫ومبــا أن املدعــي قــد احضــر شــاهده واملدونــة شــهادته آنفــا واملعدلــة‬\n‫التعديــل الشــرعي وقــد تضمنــت شــهادته بــأن يف ذمــة املدعــى عليــه ‪........‬‬\n‫للمدعــي ‪ .............‬مبلــغ خمســة وعشــرين ألــف ريــال ومبــا أن املدعــي قــد‬\n‫بــذل اليمــن املكملــة للشــاهد وقــد ذكــر شــيخ اإلســام ابــن تيميــه يف‬\n‫مجمــوع الفتــاوى ‪ 391/35‬مــا نصــه (وقــد ثبــت يف صحيــح مســلم عــن‬\n‫ابــن عبــاس أن النبــي صلــى اهلل عليــه وســلكم قضــى بشــاهد وميــن‬\n‫رواه الترمــذي وابــن ماجــه مــن حديــث جابــر ورواه أبــو داود والترمــذي‬\n‫وابــن ماجــه مــن حديــث أبــي هريــره وروي ذلــك عــن النبــي مــن وجــوه‬\n‫كثيــره وهــذه األحاديــث أصــح واشــهر مــا روي عــن النبــي صلــى اهلل‬\n‫عليــه وســلم يف هــذا البــاب وابــن عبــاس رضــي اهلل عنــه الــذي يــروي‬\n‫عــن النبــي صلــى اهلل عليــه وســلم انــه قضــى باليمــن مــع الشــاهد وان‬\n‫هــذا قضــي بــه يف دعــاوى واقــر بهــذا بدعاوى)أ‪.‬ه ـ وقــد ذكــر ابــن القيــم‬\n‫رحمــه اهلل تعالــى يف كتابــه الطــرق احلكميــة يف السياســة الشــرعية‬\n‫ص ‪172‬مانصه(احلكــم بالشــاهد واليمــن وهــو مذهــب فقهــاء احلديــث‬\n‫كلهــم ومذهــب فقهــاء األمصــار مــا خــا أبــي حنيفــة وأصحابه)أ‪.‬ه ـ‬\n‫وقــد ذكــر ابــن قدامــة رحمــه اهلل تعالــى يف كتابــه الــكايف ‪128/6‬‬\n‫مــا نصــه (فــإن امتنــع اخلصــم مــن احلضــور عنــد احلاكــم حكــم عليــه‬\n‫ألنــه لــو لــم يحكــم عليــه جلعــل االمتنــاع واالســتتار طريق ـ ًا لتضييــع‬\n‫احلقــوق) ا‪.‬ه ـ وقــد ذكــر أبــو إســحاق إبراهيــم بــن احلســن يف كتابــه‬\n‫معــن احلــكام ‪ 615/2‬مــا نصــه (مســألة قــال املــاوردي يف تفســير قــول‬\n\n\n                                                                                     ‫‪168‬‬\n\f      ‫اهلل تعالــى « وإذا دعــوا إلــى اهلل ورســوله ليحكــم بينهــم » اآليــة دليــل‬\n      ‫علــى أنــه مــن دعــي إلــى حاكــم مــن حــكام املســلمني فعليــه اإلجابــة‬\n      ‫ويجــرح إن تأخــر وقــد ورد عــن احلســن بــن علــي رضــي اهلل عنهمــا أن‬\n      ‫النبــي صلــى اهلل عليــه وســلم قــال « مــن دعــي إلــى حاكــم مــن حــكام‬\n      ‫املســلمني فلــم يجــب فهــو ظالــم ال حــق لــه » جلميــع ذلــك فقــد ألزمــت‬\n      ‫املدعــى عليــه ‪ ............‬بــأن يدفــع للمدعــي ‪ .............‬مبلــغ وقــدره خمســة‬\n      ‫وعشــرين ألــف ريــال وبــه حكمــت وبعرضــه عليــه قنــع بــه املدعــي وأفهــم‬\n      ‫بــأن هــذا احلكــم حكــم غيابــي خاضــع لالســتئناف حســب التعليمــات‬\n                                                        ‫و حــرر يف ‪ 1433/11/16‬ه ـ‬\n                            ‫وصلى اهلل على نبينا محمد وعلى آله وصحبه وسلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .........‬رئيــس احملكمــة العامــة‬\n      ‫بالطائف‪/‬املســاعد والقائــم بعمــل املكتــب القضائــي الســادس ويف هذا‬\n      ‫اليــوم األحد‪1434/01/04‬ه ـ افتتحــت اجللســة يف متــام الســاعة الثامنــة‬\n      ‫وخمســة وأربعــن دقيقــة وفيهــا قــد مت بعــث صــورة مــن صــك احلكــم‬\n      ‫رقــم ‪ 33457039‬يف ‪1433/11/16‬ه ـ للمدعــى عليــه ‪ ........‬لتقــدمي‬\n      ‫الالئحــة االعتراضيــة علــى احلكــم إن رغــب يف ذلــك خــال ثالثــن يومــا‬\n      ‫مــن اســتالمه لهــا وإذا مضــت املــدة ولــم يتقــدم بالالئحــة فســوف يســقط‬\n      ‫حقــه يف طلــب االســتئناف وبذلــك يعتبــر احلكــم نافــذا وذلــك مبوجــب‬\n      ‫خطابنــا رقــم ‪ 33/2070206‬يف ‪1433/11/21‬ه ـ وقــد أفادنــا احملضــر‬\n      ‫بهــذه احملكمــة ‪ .............‬أنــه تعــذر تســليم صــورة الصــك املشــار إلــى‬\n      ‫رقمــه أعــاه لعــدم وضــوح العنــوان ولعــدم مراجعــة املدعــي علمــا بــأن‬\n      ‫النظام ال يســمح بتســليم صورة احلكم اال للمدعي أو وكيله الشــرعي‬\n      ‫فعليــه وبنــاء علــى املــادة السادســة والســبعني بعــد املائــة واملــادة السادســة‬\n\n\n‫‪169‬‬\n\f‫واخلمســن مــن نظــام املرافعــات الشــرعية فقــد أمــرت برفــع هــذا احلكــم‬\n‫مــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                           ‫يف‪1434/01/04‬ه ـ‬\n‫احلمد هلل وحده وبعد لدي أنا (‪ )....‬القاضي باحملكمة العامة بالطائف‬\n‫واخللــف لفضيلــة الشــيخ (‪ )....‬ويف هــذا اليــوم اإلثنــن ‪1434/06/05‬ه ـ‬\n‫افتتحــت اجللســة يف متــام الســاعة الثامنــة وخمســة وأربعــن دقيقــة وفيهــا‬\n‫وردت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم‬\n‫‪ 34635067‬يف ‪1434/05/22‬ه ـ وقــد جــرى تدقيــق احلكــم مــن الدائرة‬\n‫احلقوقيــة األولــى مبحكمــة االســتئناف وصــدر بشــأنه القــرار رقــم‬\n‫‪ 34214353‬يف ‪1434/05/18‬ه ـ املــدون علــى ظهــر الصــك واملتضمــن‬\n‫(احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم ‪33457039‬‬\n‫وتاريــخ ‪1433/11/16‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ............‬واصدرنــا‬\n‫القــرار رقــم ‪ 34214353‬وتاريــخ ‪1434/05/18‬ه ـ املتضمــن املوافقــة‬\n‫علــى احلكــم والغائــب علــى دعــواه واهلل املوفــق عضــو ‪ ...........‬ختمــه‬\n‫وتوقيعــه عضــو ‪ .............‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ .........‬ختمــه‬\n‫وتوقيعه)أ‪.‬ه ـ وعليــه فقــد أمــرت بإحلــاق ذلــك بضبطــه وســجله وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                             ‫يف‪1434/06/05‬ه ـ الســاعة التاســعة صباح ـاً‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى احلكــم الصــادر مــن‬\n‫فضيلــة الشــيخ (‪ )....‬القاضــي باحملكمــة العامــة بالطائــف واملســجل‬\n\n\n                                                                                   ‫‪170‬‬\n\f      ‫بعــدد ‪ 33457039‬وتاريــخ ‪ 1433/11/16‬هـ ـ واملتضمــن دعــوى (‪)....‬‬\n      ‫ضــد (‪ )....‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬وبدراســة احلكــم وصــورة‬\n      ‫ضبطــه تقــررت املوافقــة علــى احلكــم والغائــب علــى دعــواه واهلل املوفــق‪.‬‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪171‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":163,"source_page_end":171,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f5a3c9d286ba1a272012a82c7458b1220b2534b088828fc126fed78973597fda","normalized_text_hash":"eb818761d565269c0648ffcba55da119efa131eb81347d48cd4a10d23618658a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p163-33457039"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6704a99e-33bb-5a0d-b5c2-3fe8a2c69aa6","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع سيارة بأقساط -االمتناع عن السداد -عدم حضور املدعى عليه -بينة املدعي العقد والكمبياالت واليمن -احلكم غيابي ا بدفع الثمن احلال واإللزام مبا تبقى -الغائب على حجته","document_number":"34235421","case_number":"341653","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/10","year":"1434","subject":"بيع -بيع سيارة بأقساط -االمتناع عن السداد -عدم حضور املدعى عليه -بينة املدعي العقد والكمبياالت واليمن -احلكم غيابي ا بدفع الثمن احلال واإللزام مبا تبقى -الغائب على حجته","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34235421 :‬‬\n                     ‫َر ْق ُم الدعوى‪341653 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34297969‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع ســيارة بأقســاط‪ -‬االمتنــاع عــن الســداد ‪ -‬عــدم حضــور‬\n‫املدعــى عليــه ‪ -‬بينــة املدعــي العقــد والكمبيــاالت واليمــن ‪ -‬احلكــم‬\n‫غيابيـ ًا بدفــع الثمــن احلــال واإللــزام مبــا تبقــى ‪ -‬الغائــب علــى حجتــه‬\n                                                               ‫متــى حضــر ‪.‬‬\n\n\n\n\n                                           ‫‪ .1‬حديث « ال ضرر وال ضرار »‬\n‫‪ .2‬للحاكــم واليــة علــى مــال الغائــب ويجــوز لــه احلكــم عليــه وعلــى‬\n‫املســتتر واملمتنــع ولــو كان يف البلــد كمــا صــرح بذلــك صاحــب‬\n                                                        ‫املبــدع والكشــاف ‪.‬‬\n\n\n\n\n‫قــام املدعــي ببيــع ســيارة إلــى املدعــى عليــه تســدد قيمتهــا علــى أقســاط‬\n‫شــهرية ‪ ،‬وقــد حــددا قيمــة كل قســط‪ ،‬ســدد املدعــى عليــه جــزء ًا مــن‬\n‫هــذه األقســاط وامتنــع عــن ســداد الباقــي‪ ،‬طلب املدعي إلزامه بالســداد‬\n‫وااللتــزام بســداد مــا تبقــى يف حينــه‪ ،‬وقــدم لصحــة دعــواه صــورة العقد‪،‬‬\n‫وكمبيــاالت موقعــة مــن املدعــى عليــه‪ ،‬كمــا حلــف اليمــن الشــرعية‪،‬‬\n‫ـاء علــى‬‫لــم يحضــر املدعــى عليــه وجــرى ســماع الدعــوى غيابي ـ ًا ‪ -‬بنـ ً‬\n‫مــا تقــدم حكمــت احملكمــة علــى املدعــى عليــه غيابي ـ ًا بدفــع الثمــن‬\n\n                                                                                    ‫‪130‬‬\n\f      ‫حــا ًال وااللتــزام بســداد املتبقــي يف حينــه ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                 ‫االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمد هلل وحده وبعد فلدي أنا (‪ )....‬القاضي يف احملكمة العامة مبكة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 341653‬وتاريــخ ‪ 1434/01/03‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 346961‬وتاريــخ ‪ 1434/01/03‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1434/06/10‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 30‬‬\n      ‫حضــر املدعــي ‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ...........‬ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه وقــد ســبق إبالغــه‬\n      ‫باحلضــور يف املوعــد املاضــي املقــرر بتاريــخ ‪1434/01/24‬ه ـ ولــم يحضر‬\n      ‫اجللســة كمــا مت إبالغــه شــخصيا باحلضــور يف هــذا اليــوم وذلك مبوجب‬\n      ‫خطــاب محضــري اخلصــوم رقــم ‪ 34208799‬وتاريــخ ‪1434/01/25‬ه ـ‬\n      ‫وطلــب املدعــي ســماع دعــواه وقــررت الســير يف الدعــوى وســماعها‬\n      ‫ـاء علــى املــادة رقــم ‪ 55‬مــن نظــام املرافعــات الشــرعية وبســؤاله‬  ‫غيابيـ ًا بنـ ً‬\n      ‫عــن دعــواه قــال لقــد بعــت علــى املدعــى عليه ‪ .................‬ســيارة إيســيوزو‬\n      ‫ونيــت ‪ 2009‬م بقيمــة إجماليــة قدرهــا واحــد وســبعون ألــف ريــال تســدد‬\n      ‫علــى أقســاط شــهرية قيمــة كل قســط ألــف وســتمائة ريــال والقســط‬\n      ‫األخيــر ســتمائة ريــال ابتــداء مــن ‪1431/06/25‬ه ـ وآخــر قســط بتاريــخ‬\n      ‫‪1435/02/25‬ه ـ وقــد ســدد منهــا حتــى اآلن ســتة عشــر ألــف ريــال‬\n      ‫وبقــي يف ذمتــه خمســة وخمســون ألــف ريــال حــل منهــا واحــد وأربعــون‬\n      ‫ألــف وســتمائة ريــال وبقــي ثالثــة عشــر ألــف وأربعمائــة ريــال لــم حتــل‬\n\n‫‪131‬‬\n\f‫حتــى اآلن أطلــب إلزامــه بالســداد وااللتــزام بســداد املتبقــي يف حينــه‬\n‫هــذه دعــواي وبطلــب البينــة منــه أبــرز أصــل العقــد املوقــع بــن الطرفــن‬\n‫وعــدد خمــس وثالثــن كمبيالــة موقعــة مــن املدعــى عليــه ممــا يثبــت‬\n‫عــدم ســداده وبطلــب ميــن االســتظهار مــن املدعــي علــى صحــة دعــواه‬\n‫ا واهلل العظيــم الــذي ال الــه إال هــو أن لــي يف ذمــة املدعــى‬‫حلــف قائ ـ ً‬\n‫عليــه مبلــغ وقــدره خمســة وخمســون ألــف ريــال منهــا واحــد وأربعــون‬\n‫ألــف وســتمائة ريــال حالــة وثالثــة عشــر ألــف وأربعمائــة ريــال لــم حتــل‬\n‫واهلل العظيــم فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث قــدم‬\n‫املدعــي بينتــه علــى دعــواه وحلــف ميــن االســتظهار بعــد طلبهــا منه وحيث‬\n‫تضــرر املدعــي مــن عــدم حضــور املدعــى عليــه وقــد جــاءت الشــريعة‬\n‫برفــع الضــرر حلديــث « ال ضــرر وال ضــرار» وألن للحاكــم واليــة علــى‬\n‫مــال الغائــب ويجــوز لــه احلكــم عليــه وعلــى املســتتر واملمتنــع ولــو كان‬\n‫يف البلــد كمــا صــرح بذلــك صاحــب املبــدع والكشــاف وبنــاء علــى‬\n‫نظــام املرافعــات مــادة خمســة وخمســون فقــد حكمــت علــى املدعــى‬\n‫عليــه بدفــع مبلــغ واحــد وأربعــن ألــف وســتمائة ريــال حــا ًال وااللتــزام‬\n‫بســداد املتبقــي يف حينــه وبعرضــه علــى املدعــي قــرر القناعــة وســيتم‬\n‫بعــث نســخة مــن صــك احلكــم للمدعــى عليــه بعــد إخراجــه وإفهامــه‬\n‫بتعليمــات االســتئناف وأنــه إذا تبلــغ املدعــى عليــه باحلكــم ومضــت‬\n‫مــدة االعتــراض وقدرهــا ثالثــون يومـ ًا ولــم يتقــدم باعتــراض يكتســب‬\n‫احلكــم القطعيــة ورفعــه حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                        ‫يف ‪1434/06/10‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n\n\n                                                                                   ‫‪132‬‬\n\f      ‫فقــد جــرت منــي الكتابــة إلــى مديــر مركــز شــرطة العزيزيــة‬\n      ‫بكتــاب احملكمــة رقــم ‪ 341452183‬وتاريــخ ‪1434/6/17‬ه ـ إلبــاغ‬\n      ‫احملكــوم عليــه ‪ ................‬باحلكــم وأن مــدة االعتــراض ثالثــون يوم ـ ًا‬\n      ‫مــن تاريــخ تبليــغ احلكــم للمحكــوم عليــه أو وكيلــه حســبما قضــت‬\n      ‫بــه املــادة السادســة والســبعون بعــد املئــة مــن نظــام املرافعــات الشــرعية‬\n      ‫فــورد اجلــواب مــن شــرطة العزيزيــة بالكتــاب رقــم ‪ 248963‬وتاريــخ‬\n      ‫‪1434/7/16‬ه ـ املتضمــن بأنــه ( جــرى طلــب احملكــوم عليــه املذكــور‬\n      ‫عــن طريــق عمــدة العزيزيــة الشــرقية الــذي أفــاد بــأن مديــر فــرع شــركة‬\n      ‫الوشــاح للحراســات األمنيــة ذكــر بــأن املدعــى عليــه ‪............‬مفصــول‬\n      ‫مــن الشــركة ) أ‪.‬ه ـ لــذا وألنــه قــد تعــذر تســليم نســخة مــن صك احلكم‬\n      ‫الصــادر يف هــذه الدعــوى برقــم ‪ 34235421‬وتاريــخ ‪1434/6/10‬ه ـ‬\n      ‫ا‬ ‫فقــد قــررت رفــع هــذا احلكــم حملكمــة االســتئناف لتدقيقــه عم ـ ً‬\n      ‫بالفقــرة اخلامســة مــن املــادة املذكــورة مــن النظــام ولوائحــه التنفيذيــة‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا وآلــه وصحبــه وســلم حــرر يف‬\n                                                                     ‫‪1434/7/22‬ه ـ ‪.‬‬\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34297969‬وتاريــخ‬\n                                                      ‫‪1434/8/15‬هـ‪.‬‬\n\n\n\n\n‫‪133‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":130,"source_page_end":133,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f6bfeca1e2fe6ca4ea06d066d0b6f03d98a7547e002754d7e9917fb901845352","normalized_text_hash":"4033bf2fb12344908ae5dca37c4a969e6b5a7662b0574582d5d8e92e33b7c62e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p130-34235421"},{"id":"36f8da63-29a7-5aaf-a53e-013d2122f0c1","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع معدات مخبز وسيارات -املطالبة بقيمة املعدات -بينة املدعي وميينه -إيجابية التقرير الفني للمدعي -احلكم بدفع الثمن للمدعي .","document_number":"33169186","case_number":"3226935","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالقطيف","circuit":"الدائرة احلقوقية األولى مبحكمة الاستئناف برقم 33169186يف","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/4","year":"1434","subject":"بيع -بيع معدات مخبز وسيارات -املطالبة بقيمة املعدات -بينة املدعي وميينه -إيجابية التقرير الفني للمدعي -احلكم بدفع الثمن للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1433/4/4 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33169186 :‬‬\n                    ‫َر ْق ُم الدعوى‪3226935 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3463325‬تاريخه‪1434/3/16 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع معــدات مخبــز وســيارات ‪ -‬املطالبــة بقيمــة املعــدات ‪ -‬بينــة‬\n‫املدعــي وميينــه ‪ -‬إيجابيــة التقريــر الفنــي للمدعــي ‪ -‬احلكــم بدفــع‬\n                                                         ‫الثمــن للمدعــي ‪.‬‬\n\n\n\n\n                                                ‫‪ -‬قاعدة املثبت مقدم على النفي ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي أنــه اشــترى مــن املدعــى عليه معــدات مخبز متنوعــة وأربع‬\n‫ســيارات مببلــغ أربعمائــة وخمســة وســبعني ألــف ريــال وقــد اتفقــا علــى أن‬\n‫يكــون دفــع القيمــة بعــد ثــاث ســنوات مــن تســليم املخبــز وقــد اســتلم‬\n‫املدعــى عليــه املخبــز بعــد البيــع مباشــرة وقــد ســلم املدعــى عليــه القيمــة‬\n‫للمدعــي مبوجــب شــيكني ومتــت مراجعتــه فلــم يتمكــن مــن الصــرف‬\n‫ملضــي مــدة طويلــة للشــيكات ولعــدم وجــود رصيــد لهــا ‪ -‬طلــب املدعــي‬\n‫احلكــم علــى املدعــى عليــه بدفــع القيمــة املذكــورة ‪ -‬أنكــر املدعــى‬\n‫عليــه الدعــوى ‪ -‬أبــرز املدعــي إقــرار ًا للمدعــى عليــه باملبلــغ والشــيكات‬\n‫الصــادرة منــه ‪ -‬طعــن املدعــى عليــه يف صحتهــا ‪ -‬جــرى بعثهــا لألدلــة‬\n‫اجلنائيــة للمطابقــة فوجــدت مطابقــة وجــرى حتليــف املدعــي اليمــن علــى‬\n‫دعــواه ونفــي التزويــر ‪ -‬صــدر احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ‬\n\n                                                                                       ‫‪134‬‬\n\f      ‫املدعــى بــه ‪ -‬اعتــرض املدعــى عليــه علــى احلكــم ‪ -‬صــدق احلكــم مــن‬\n                                                        ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد يــوم األربعــاء املوافــق ‪1431/3/10‬ه ـ لــدي أنــا‬\n      ‫(‪ )....‬القاضــي باحملكمــة العامــة بالقطيــف افتتحــت اجللســة وحضــر‬\n      ‫فيهــا ‪ ............‬رقــم ســجله املدنــي ‪ ................‬الوكيــل عــن ‪ ...........‬لبناني‬\n      ‫اجلنســية مبوجــب اإلقامــة رقــم ‪ .............‬الصــادرة مــن هيئــة االســتثمار‬\n      ‫بالدمــام بتاريــخ ‪1425/7/15‬ه ـ مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n      ‫عــدل الدمــام الثانيــة برقــم ‪ 11277‬يف ‪1428/2/22‬ه ـ جلــد ‪6377‬‬\n      ‫وادعــى علــى احلاضــر معــه ‪ .........‬رقــم ســجله املدنــي ‪ ...............‬الوكيــل‬\n      ‫عــن ‪ ............‬رقــم ســجله املدنــي ‪ ..............‬مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة عــدل القطيــف برقــم ‪ 15‬يف ‪ 1428/5/27‬ه ـ جلــد ‪8/5101‬‬\n      ‫ا يف دعــواه إنــه بتاريــخ ‪1420/3/2‬ه ـ اشــترى مــوكل هــذا احلاضــر‬               ‫قائـ ً‬\n      ‫مــن موكلــي معــدات مخبــز مكونــة مــن ‪ -1‬عجانــه إيطاليــة ‪ -2‬قطاعــه‬\n      ‫‪ -3‬مخبــز كبيــر ‪ -4‬مخبــز صغيــر ‪ -5‬رقاقــة ‪ -6‬كــوع فــرن ‪ -7‬بيــت‬\n      ‫نــار ‪ -8‬خــط تبريــد جنزيــر كامــل ‪ -9‬فــرن كهربائــي ثــاث طبقــات‬\n      ‫‪ -10‬فــرن غــاز طبقــه واحــده ‪ -11‬لفافــة صامولــي ‪ -12‬قطاعــة نصــف‬\n      ‫اتوماتيكيــة كمــا اشــترى منــه ثالث ســيارات فان وأيض ًا ســيارة وانيت‬\n      ‫مببلــغ أربعمائــة وخمســة وســبعني ألــف ريــال وقــد اتفقــا علــى أن يكــون‬\n      ‫دفــع القيمــة بعــد ثــاث ســنوات مــن تســليم املخبــز وقــد اســتلم املدعــى‬\n      ‫عليــه اصالــة املخبــز بعــد البيــع مباشــرة وقــد ســلم املدعــى عليــه أصالــة‬\n      ‫القيمــة ملوكلــي مبوجــب شــيكني مســحوبني علــى البنــك الســعودي‬\n\n‫‪135‬‬\n\f‫الفرنســي بالقطيــف األول برقــم ‪ 381751‬والثانــي برقــم ‪381752‬‬\n‫كالهمــا يف ‪1420/3/3‬ه ـ وكان موكلــي وقــت البيــع يعمــل حتــت‬\n‫كفالــة املشــتري ثــم إن املدعــى عليــه قــام بترحيلــه إلــى بلــده بخــروج‬\n‫نهائــي قبــل صــرف الشــيكات ثــم إن موكلــي رجــع إلــى اململكــة‬\n‫بتأشــيرة مســتثمر ومتــت مراجعتــه بعــد رجوعــه منــذ ســنتني فلــم يتمكــن‬\n‫مــن الصــرف ملضــي مــدة طويلــة للشــيكات ولعــدم وجــود رصيــد لهــا‬\n‫لــذا أطلــب احلكــم علــى املدعــى عليــه أصالــة بــأن يدفــع ملوكلــي مبلــغ‬\n‫أربعمائــة وخمســة وســبعني ألــف ريــال هــذه دعــواي وبســؤال املدعــى‬\n‫عليــه أجــاب بقولــه مــا ذكــره يف دعــواه ليــس بصحيــح فلــم يشــتر مــن‬\n‫موكلــه املخبــز الــذي وصــف معداتــه وكــذا ثــاث ســيارات فــان وانيــت‬\n‫يف التاريــخ وباملبلــغ الــذي ذكــر لــذا أطلــب رد دعــواه وصــرف النظــر‬\n‫عنهــا هــذه إجابتــي وبعــد ســماع الدعــوى واإلجابــة جــرى عــرض مــا دفــع‬\n‫بــه املدعــى عليــه وكالــة علــى املدعــي وكالــة فقــال مــا جــاء يف دفعــه‬\n‫ليــس بصحيــح والصحيــح مــا ذكرتــه يف دعــواي فســألته هــل لديــك‬\n‫بينــة قــال نعــم أطلــب مهلــة إلحضارهــا ورفعــت اجللســة لذلــك ويف جلســة‬\n‫أخــرى لــدي أنــا ‪ ..............‬القاضــي باحملكمــة العامــة بالقطيــف واخللــف‬\n‫لفضيلــة ناظــر القضيــة افتتحــت اجللســة وباالطــاع علــى مــا مت ضبطــه‬\n‫وجدتــه موقعـ ًا مــن أطــراف وفضيلــة ســلفي ناظــر القضيــة ابتــداء وبنــاء‬\n‫علــى املــادة السادســة والســتني بعــد املائــة مــن نظــام املرافعــات الشــرعية‬\n‫ولوائحهــا التنفيذيــة فقــد مت اعتمــاده وقــد حضــر املتداعيــان وكالــة‬\n‫وقــدم املدعــى عليــه وكالــة مذكــرة مكونــة مــن ورقــة واحــده وبرفقتــه‬\n‫بعــض املرفقــات وبعــد االطــاع علــى هــذه املذكــرة وجــدت أن ملخصهــا‬\n‫يتضمــن ‪ :‬أو ًال أن املدعــي كان يعمــل لــدى موكلــي براتــب شــهري‬\n\n\n                                                                                      ‫‪136‬‬\n\f      ‫وانتهــت خدماتــه بعــد توقيــع مخالصــة يقــر فيهــا بــأن ليــس لــه أي حقــوق‬\n      ‫ال ســابقة وال الحقــه ثانيـ ًا عــدم صحــة ادعــاء املدعــي مــن كــون موكلــه‬\n      ‫قــام بشــراء املعــدات منــه الن املدعــي كان مجــرد موظــف ويقــدح يف‬\n      ‫صــورة املبايعــة املرفقــة يف صحيفــة الدعــوى وأن املدعــي أســتغل عملــه‬\n      ‫مــع موكلــه ككاتــب حســابات بحفــظ بعــض األوراق ثالث ـ ًا بالنســبة‬\n      ‫للســيارات فيطلــب إحضــار املبايعــة ومخاطبــة املــرور لإلفــادة عــن‬\n      ‫الســيارات انتهــى كامــل مضمونــه وقــد أرفقــت كامــل املرفقــات‬\n      ‫واملذكــرة باملعاملــة ثــم جــرى ســؤال املدعــي البينــة فقــال بينتــي إقــرار‬\n      ‫املدعــى عليــه أصالــة بالشــراء وكــذا أصــل الشــيكني الصادريــن مــن‬\n      ‫املدعــى عليــه أصالــة مــن موكلــي بكامــل املبلــغ وآمــل االطــاع عليهــا‬\n      ‫هكــذا قــرر ثــم قدمهــا وباالطــاع عليهــا وجدتهــا ورقــة مــن مطبوعــات‬\n      ‫مخبــز ‪ ................‬احلديــث وتضمنــت مــا نصــه التاريــخ ‪1420/3/3‬ه ـ‬\n      ‫بســم اهلل الرحمــن الرحيــم أنــا املوقــع أدنــاه ‪ ............‬ســعودي اجلنســية‬\n      ‫مبوجــب حفيظــة رقــم ‪ ...........‬تاريخهــا ‪1378/8/14‬ه ـ اقــر واعتــرف‬\n      ‫بأننــي اتفقــت مــع مكفولــي ‪ ...........‬لبنانــي اجلنســية مبوجــب اإلقامــة‬\n      ‫رقــم ‪ .............‬علــى شــراء املعــدات والســيارات التابعــة للمخبــز املســجل‬\n      ‫باســمي يف القطيــف باســم مخبــز ‪ .................‬املعــدات هــي عبــارة عــن‬\n      ‫(عجانــة إيطاليــة قطاعــة مخمــرة عــدد ‪3‬كبيــر مخمــر عــدد ‪ 1‬صغيــر‬\n      ‫رقاقــة كــوع فــرن عــدد ‪ 1‬بيــت نــار خــط تبريــد جنزيــر كامــل عجانــه‬\n      ‫كهربائيــة فــرن كهربائــي ثــاث طبقــات فــرن غــاز طبقــه واحــده‬\n      ‫لفافــة صامولــي قطاعــة نصــف أوتوماتيكيــة الســيارات هــي فــان عــدد‬\n      ‫‪ 3‬وســيارة وانيــت عــدد ‪ 1‬وذلــك مببلــغ (‪ )475000‬اربعمائــة وخمســة‬\n      ‫وســبعون ألــف ريــال ســعودي ال غيــر تدفــع ثــاث ســنوات مــن اســتالمي‬\n\n\n‫‪137‬‬\n\f‫املخبــز علــى دفعــات ويف حــال التأخــر عــن الدفــع يحــق لــه أو ملــن ينــوب‬\n‫ا داخــل اململكــة‬    ‫عنــه مبوجــب وكالــه رســمية املطالبــة باملبلــغ كام ـ ً‬\n‫أو خارجهــا يف حــال عــدم متكنــه مــن العــودة إلــى اململكــة واملطالبــة‬\n‫بحقــه مــن خــال قنصليــة اململكــة يف بلــده علمـ ًا بأننــي قــد حــررت لــه‬\n‫شــيك ًا باملبلــغ املذكــور كضمــان حــق مخبــز ‪( ...................‬توقيــع )أ‬\n‫ه ـ وهــذه الورقــة مختومــة بختــم تضمــن مــا نصــه (مخبــز ‪ ........‬لصاحبــه‬\n‫‪ ) ......‬كمــا وجــدت شــيك ًا مســحوب ًا علــى البنــك الســعودي الفرنســي‬\n‫فــرع القطيــف شــارع اخلليفــة عمــر القطيــف ومــؤرخ يف ‪1420/3/2‬ه ـ‬\n‫رقــم الشــيك ‪ 381752‬ألمــر الســيد ‪ ...........‬مببلــغ مائتــن وخمســة‬\n‫وســبعني ألــف ريــال (‪ )275000‬مــن الســادة مخبــز ‪ ...................‬وموقــع‬\n‫كمــا وجــدت شــيك ًا مســحوب ًا علــى البنــك الســعودي ى الفرنســي‬\n‫فــرع القطيــف شــارع اخلليفــة عمــر القطيــف ومــؤرخ يف ‪1420/3/2‬ه ـ‬\n‫رقــم الشــيك ‪ 381751‬ألمــر الســيد ‪ ............‬مببلــغ مائتــن ألــف ريــال‬\n‫(‪ )200000‬مــن الســادة مخبــز ‪ ...........‬وموقــع وبعــرض جميــع ذلــك‬\n‫علــى املدعــى عليــه وكالــة قــال مــا تضمنتــه هــذه املســتندات غيــر‬\n‫صحيــح والتوقيــع مــزور علــى موكلــي هكــذا قــرر وبعــرض ذلــك‬\n‫علــى املدعــي وكالــة قــال ســبق أن دفــع املدعــى عليــه بهــذا الدفــع أمــام‬\n‫مكتــب الفصــل يف منازعــات األوراق التجاريــة باملنطقــة الشــرقية ومتــت‬\n‫الكتابــة لألدلــة اجلنائيــة التــي أثبتــت صحــة التواقيــع املنســوبة للمدعــى‬\n‫عليــه وأطلــب الكتابــة لهــا لالستفســار عــن ذلــك هكــذا قــرر ثــم متــت‬\n‫الكتابــة إلــى فــرع وزارة التجــارة باملنطقــة الشــرقية بخطابنــا رقــم‬\n‫‪ 31/3217‬يف ‪1431/8/6‬ه ـ إلفــادة مبــا لديهــم مــن نتائج حيال التحقيق‬\n‫بشــأن التواقيــع املنســوبة للمدعــى عليــه فوردنــا اجلــواب بخطابهــم رقــم‬\n\n\n                                                                                    ‫‪138‬‬\n\f      ‫‪/4/19/11117‬ف د يف ‪1431/8 /13‬ه ـ برفقــه التقريــر الصــادر مــن‬\n      ‫إدارة الفحــوص الفنيــة بالتزييــف والتزويــر بــاإلدارة العامــة لألدلــة‬\n      ‫اجلنائيــة ويحمــل الرقــم ‪ 30524‬يف ‪1431/6/30‬ه ـ وتضمــن مــا نصــه‬\n      ‫فحــص الشــيكني املســحوبني علــى البنــك الســعودي الفرنســي فــرع‬\n      ‫القطيــف األول برقــم ‪ 381751‬والثانــي برقــم ‪ 381752‬ومؤرخــن يف‬\n      ‫‪1420/3/2‬ه ـ ألمــر املســتفيد الســيد ‪ ..............‬ويحمــل توقيــع منســوب‬\n      ‫للمدعــو ‪ ...............‬علــى حســاب مخبــز ‪ ...............‬مببلــغ إجمالــي قــدره‬\n      ‫أربعمائــة ومئتــان وخمســة وســبعون ألف ـ ًا ومبضاهــاة التوقيعــن الذيــن‬\n      ‫علــى الشــيكني بتواقيــع أخــرى للمدعــو ‪ ..............‬أثبتــت النتيجــة اتفــاق‬\n          ‫التوقيعــن اللذيــن علــى الشــيكني مــع تواقيعــه الثابتــة األخــرى أ ه ـ‬\n      ‫ثــم جــرى االطــاع علــى اإلقــرار الــذي أشــار لــه املدعــى عليــه وكالــة‬\n      ‫واملنســوب للمدعــي أصالــة ‪ ........‬واملتمثــل بصــورة ورقــة مــن مطبوعــات‬\n      ‫مخبــز ‪ ..................‬ومــؤرخ يف ‪98/12/18‬م ويتضمــن إقــراره باســتالم‬\n      ‫جميــع رواتبــه الشــهرية وبــدل اإلجــازة ومكافــأة نهايــة اخلدمــة حتــى‬\n      ‫تاريــخ ‪98/12/20‬م ثــم قــرر املدعــى عليــه وكالــة لــدي إقــرار أخــر‬\n      ‫للمدعــي أصالــة يتضمــن عــدم وجــود أي مســتحقات أو حقــوق يف ذمــة‬\n      ‫موكلــي لصالــح املدعــي أصالــة ثــم قــدم هــذا اإلقــرار وبعــد االطــاع‬\n      ‫عليــه وجدتــه أصــل ورقــة مــن مطبوعــات مخبــز ‪ ...........‬مــؤرخ يف‬\n      ‫‪1420/3/1‬ه ـ ويتضمــن إقــرار املدعــي أصالــة مبــا نصــه ليــس لــي يف‬\n      ‫ذمــة ‪ .................‬صاحــب مخبــز ‪ ..................‬أي حــق وال مســتحق وال‬\n      ‫أي دعــوى وال بــأي وجــه آخــر ومبــا أنــي أعمــل يف املخبــز املذكــور‬\n      ‫بوظيفــة كاتــب حســابات بأنــه ليــس عنــدي أي توقيــع منســوب إلــى‬\n      ‫ـواء كان شــيك ًا أو ورقــة أو يف دفتــر وإذا ظهــر شــيء مــن‬      ‫‪ ..............‬سـ ً‬\n\n‫‪139‬‬\n\f‫هــذا القبيــل يعتبــر الغيـ ًا وال قيمــة لــه وهــذا إقــرار يف ذلــك اعتبــار ًا مــن‬\n‫تاريــخ ‪1420/3/1‬ه ـ أ ه ـ توقيعــه ثــم جــرى ســؤال املدعــي وكالــة عــن‬\n‫اســتعداد موكلــه بــأداء اليمــن علــى صحــة دعــواه فقــال اطلــب إمهالــي‬\n‫حتــى أمتكــن مــن الرجــوع ملوكلــي وســؤاله كمــا إننــي أرى أن اليمــن‬\n‫غيــر متوجهــه علــى موكلــي ألن مــا قدمــه مــن أوراق ومســتندات كافية‬\n‫يف إثبــات اســتحقاق للمبلــغ املدعــى بــه وال حاجــة لليمــن هكــذا قــرر‬\n‫فأجبتــه لذلــك ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه‬\n‫وكالــة وحضــر املدعــي أصالــة ‪ .............‬لبنانــي اجلنســية مبوجــب جــواز‬\n‫الســفر الصــادر مــن اجلمهوريــة اللبنانيــة برقــم ‪ RL.......‬ثــم جــرى عــرض‬\n‫اليمــن علــى املدعــي أصالــة علــى صحــة الشــيكات والتواقيــع املدونــة‬\n‫عليهــا فاســتعد بــأداء اليمــن وحلــف بعــد تخويفــه بــاهلل واإلذن لــه قائــا‬\n‫واهلل العظيــم الــذي ال إلــه غيــره وال رب ســواه ان الشــيكني املؤرخــن‬\n‫يف ‪1420 /3/2‬ه ـ املســحوبني علــى البنــك الفرنســي مــن حســاب املدعى‬\n‫عليــه ‪ ..........‬والذيــن يحمــان مبلــغ وقــدره أربعمائــة و خمســة وســبعون‬\n‫ألــف ريــال وذلــك لــي أنــا كمســتفيد صحيحــان وان التوقيعــن احملررين‬\n‫عليهمــا صــادران مــن املدعــى عليــه نفســه ولــم أقــم بتزويرهــا ومــا زال‬\n‫هــذا املبلــغ مســتحق ًا لــي يف ذمــة املدعــى عليــه حتــى اآلن واهلل العظيــم‬\n‫هكــذا حلــف ثــم جــرى عــرض اإلقــرار املقــدم مــن املدعــى عليــه وكالــة‬\n‫واملنســوب للمدعــي أصالــة عليــه فقــال هــذا اإلقــرار غيــر صحيــح مطلقـ ًا‬\n‫هكــذا قــرر ثــم قفلــت املرافعــة وبعــد ســماع الدعــوى وجوابهــا وحيــث‬\n‫أنكــر املدعــى عليــه الدعــوى وأثبــت املدعــي وكالــة دعــواه بالشــيكني‬\n‫املدونــن بضبــط القضيــة وحيــث دفــع املدعــى عليــه وكالــة بتزويــر‬\n‫الشــيكني وأثبتــت اجلهــة املختصــة بتطابــق التواقيــع احملــررة علــى‬\n\n\n                                                                                           ‫‪140‬‬\n\f      ‫الشــيكني مــع توقيــع املدعــى عليــه األخــرى وحلــف املدعــي أصالــة‬\n      ‫تكملــة لهــذه البينــة لنفــي احتمــال صحــة التزويــر وحيــث إن مــا دفــع بــه‬\n      ‫املدعــى عليــه وكالــة مــن كــون املدعــي أصالــة أقــر بأنــه ليــس لديــه أي‬\n      ‫ا أنــه بينــة‬\n                   ‫توقيــع يف حــال ثبوتــه فتاريخــه ســابق لتاريــخ الشــيكات فضـ ً‬\n      ‫علــى النفــي والشــيكات بينــة علــى اإلثبــات واإلثبــات مقــدم علــى النفــي‬\n      ‫لــذا كلــه فقــد حكمــت بإلــزام املدعــى عليــه بتســليم املدعــي مبلــغ‬\n      ‫أربعمائــة وخمســه وســبعني ألــف (‪ )475000‬ريــال وبعرضــه لــم يقنــع‬\n      ‫بــه املدعــى عليــه وكالــة طالبــا متييــزه فأفهــم باملراجعــة يــوم الســبت‬\n      ‫املوافــق ‪1433/2/13‬ه ـ الســتالم نســخة احلكــم وتقــدمي اعتراضــه‬\n      ‫عليــه خــال ثالثــن يومــا مــن التاريــخ املذكــور وبعــد انتهائهــا دون‬\n      ‫تقــدمي اعتراضــه يســقط حقــه فيــه ويكتســب احلكــم القطعيــة وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                             ‫يف ‪1433/01/04‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1433/8/18‬ه ـ افتتحت‬\n      ‫اجللســة يف متــام الســاعة التاســعة والنصــف وكانــت املعاملــة قــد عــادت‬\n      ‫مــن محكمــة االســتئناف باملنطقــة الشــرقية بخطــاب ســماحة رئيســها‬\n      ‫رقــم ‪3114679‬يف ‪1433/6/4‬ه ـ مرفــق بهــا القــرار الصــادر مــن قضــاة‬\n      ‫الدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف برقــم‪ 33169186‬يف‬\n      ‫‪1433/4/4‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ أن املدعــى عليــه أنكــر‬\n      ‫توقيعــه علــى عقــد املبايعــة كمــا أنكــر توقيعــه علــى اإلقــرار املتضمــن‬\n      ‫أن أي شــيك بتوقيع منســوب ل‪ ...............‬ملغي وألهمية هذين الســندين‬\n      ‫وتأثيرهمــا علــى مجــرى القضيــة فإنــه يلــزم التحقــق مــن صحــة الســندين‬\n\n\n‫‪141‬‬\n\f‫املذكوريــن عــن طريــق اجلهــة املختصــة يف معرفــة صحــة التواقيــع‬\n‫إضافــة إلــى التحقــق مــن قبــل اجلهــة املذكــورة ممــا إذا كان مضمــون‬\n‫الشــيكني قــد متــت كتابتــه يف نفــس وقــت التوقيــع عليهمــا ‪ ،‬فعلــى‬\n‫فضيلتــه مالحظــة ذلــك وإحلــاق مــا يجـ ّـد يف الضبــط وصورتــه وملخصــه‬\n‫يف الصــك وســجله ‪ ،‬ومــن ثــم إعــادة رفــع املعاملــة إلينــا ملواصلــة تدقيــق‬\n‫احلكــم واهلل املوفــق ) أ‪.‬ه ـ وجواب ـ ًا علــى ذلــك أن احلكــم اســتند‬\n‫علــى الشــيكني املســحوبني علــى حســاب املدعــى عليــه ونفــت جهــات‬\n‫التحقيــق صحــة مــا دفــع بــه مــن تزويــر والشــيك أداة وفــاء عرفـ ًا ونظامـ ًا‬\n‫ممــا يؤكــد صحــة الدعــوى ويجعــل جانــب املدعــي قويـ ًا جــد ًا ثــم قمـ ُـت‬\n‫بتحليفــه اليمــن علــى صحــة الدعــوى اســتناد ًا علــى مــا قــرره الفقهــاء ـ ـ‬\n‫رحمهــم اهلل ـ ـ مــن أن اليمــن تشــرع يف جانــب أقــوى املتداعيــن وعليــه‬\n‫فلــم يظهــر لــي خــاف مــا حكمـ ُـت بــه وبــاهلل التوفيــق وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/8/18‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فقــد‬\n‫عــادت املعاملــة مــن الدائــرة احلقوقيــة األولــى ق‪ 1/‬مبحكمــة‬\n‫االســتئناف باملنطقــة الشــرقية وبهــا القــرار ذو الرقــم ‪ 33474175‬يف‬\n‫‪1433/12/20‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة ‪( :‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك وصــورة ضبطــه بنــاء علــى‬\n‫قرارنــا رقــم ‪/33365178‬ق‪/1‬ب يف ‪1433/8/4‬ه ـ لوحــظ أن إجابــة‬\n‫فضيلتــه غيــر مقنعــة ‪ ،‬فعلــى فضيلتــه إجــراء الــازم نحــو مــا ورد يف‬\n‫ـراء للذمــة) أ ‪ .‬ه ـ وجوابـ ًا علــى مشــايخي الفضــاء أنــه‬ ‫قرارنــا الســابق إبـ ً‬\n‫يف حــال كتابتــي للجهــات املختصــة فــإن جوابهــم ال يخلــو مــن حالتــن‬\n\n\n                                                                                        ‫‪142‬‬\n\f      ‫إمــا إثبــات تزويــر الســندين وهــو مــا يكــذب دفــع املدعــى عليــه وإمــا‬\n      ‫بإثبــات صحــة الســندين وذلــك ال يخالــف الدعــوى ألن تاريــخ الشــيكني‬\n      ‫متأخــر عــن الســندين وبقــاء الشــيكني لــدى املدعــي مــع ثبــوت تطابــق‬\n      ‫التواقيــع التــي عليهمــا مــع تواقيــع املدعــى عليــه أصالــة يجعــل جانــب‬\n      ‫ا‬\n      ‫املدعــي هــو املصــدق بيمينــه وقــد حلــف املدعــى علــى ضــوء ذلــك فضـ ً‬\n      ‫أن الســندين ـ ـ يف حــال ثبوتهمــا ‪ -‬بينــة علــى نفــي ســابق والشــيكان بينــة‬\n      ‫علــى إثبــات الحــق واإلثبــات مقــدم علــى النفــي لــذا وبعــد تكــرار وإعــادة‬\n      ‫التأمــل لــم يظهــر لــي خــاف مــا حكمـ ُـت بــه وبــاهلل التوفيــق وصلــى اهلل‬\n             ‫وســلم علــى نبينــا محمــد وآلــه وصحبــه حــرر يف ‪1433/12/29‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق ‪1434/3/6‬ه ـ افتتحــت‬\n      ‫اجللســة يف متام الســاعة التاســعة والنصف وكانت املعاملة قد عادت من‬\n      ‫محكمــة االســتئناف باملنطقــة الشــرقية بخطــاب ســماحة رئيســها رقــم‬\n      ‫‪ 34235153‬يف ‪1434/3/27‬ه ـ مرفــق بهــا القــرار الصــادر مــن قضــاة‬\n      ‫الدائــرة احلقوقيــة األولــى ق‪ 1/‬مبحكمــة االســتئناف برقــم ‪3463325‬‬\n      ‫يف ‪1434/3/16‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n      ‫ـاء علــى قرارنــا رقــم‬\n                           ‫فضيلــة القاضــي وأحلقــه بالصــك وصــورة ضبطــه بنـ ً‬\n      ‫‪ 33365178‬ق‪/1/‬ب يف ‪1433/8/4‬ه ـ وقرارنــا رقــم ‪/33474175‬‬\n      ‫ق‪/1‬ب يف ‪1433/12/20‬ه ـ فقــد قررنــا املصادقــة علــى احلكــم واهلل‬\n      ‫املوفــق ) أ ‪ .‬ه ـ وحتــى ال يخفــى جــرى حتريــره وبــاهلل التوفيــق وصلــى اهلل‬\n          ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/3/6‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n      ‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى‬\n\n\n‫‪143‬‬\n\f‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة القطيــف برقــم‬\n‫‪ 34/24657‬وتاريــخ ‪1434/1/24‬ه ـ واملقيــدة لدينــا برقــم ‪34/235153‬‬\n‫وتاريــخ ‪1434/1/27‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ ‪ ........‬املسـ ّـجل برقــم ‪ 33169186‬وتاريــخ‬\n‫‪1433/4/4‬ه ـ اخلــاص بدعــوى ‪ ( ...........‬لبنانــي اجلنســية ) ضــد ‪............‬‬\n‫يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه‬\n‫ـاء علــى قرارنــا رقــم ‪/33365178‬ق‪/1‬ب يف‬             ‫بالصــك وصــورة ضبطــه بنـ ً‬\n‫‪1433/8/4‬ه ـ و قرارنــا رقــم ‪/33474175‬ق‪/1‬ب يف ‪1433/12/20‬ه ـ‬\n‫فقــد قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه حــرر يف ‪1434/3/16‬ه ـ‬\n                                                              ‫‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                          ‫‪144‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":134,"source_page_end":144,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6aa87361d2a134c94d8a8de771cd288e389b633d4e8e1566d1672ece8dcd8c9e","normalized_text_hash":"582b9efa75217df935e63dc3d936347b1414bd4c9c2c9738e218abc45c6dc30e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p134-33169186"},{"id":"56a62032-84a3-5ca0-8040-42098a2475db","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع سيارة معيبة -املطالبة برد الثمن -التقرير الفني بعيب السيارة -إعادة الثمن .","document_number":"33466823","case_number":"3331141","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام فتحت اجللسة متام بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/27","year":"1434","subject":"بيع -بيع سيارة معيبة -املطالبة برد الثمن -التقرير الفني بعيب السيارة -إعادة الثمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/27 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33466823 :‬‬\n                           ‫َر ْق ُم الدعوى‪3331141 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 3431085‬تاريخه‪1434/2/5 :‬هـ‬\n\n\n       ‫بيــع ‪ -‬بيــع ســيارة معيبــة ‪ -‬املطالبــة بــرد الثمــن ‪ -‬التقريــر الفنــي بعيــب‬\n                                                             ‫الســيارة ‪ -‬إعــادة الثمــن ‪.‬‬\n\n\n\n\n        ‫‪ -‬خيار العيب يثبت فيه إما اإلمساك مع األرش أو الرد وأخذ الثمن‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي بأنــه اشــترى ســيارة مــن مؤسســة املدعــى عليــه وســلمه‬\n       ‫كامــل الثمــن واســتلم الســيارة إال أنــه اكتشــف أنهــا معيبــة فرجــع‬\n       ‫إلــى املؤسســة وتــرك الســيارة عندهــم مطالب ـ ًا رد ثمنهــا‪ ،‬نفــى املدعــى‬\n       ‫عليــه وكالــة وجــود عيــب يف الســيارة‪ ،‬اســتعان املدعــي بشــهود أكــدوا‬\n       ‫صــدق كالمــه متــت الكتابــة إلــى املــرور لفحــص الســيارة وجــاء التقريــر‬\n       ‫مبعيبهــا ‪ ،‬ومبــا أن املدعــى عليــه وكالــة صــا َدق علــى أن املدعــي أرجــع‬\n       ‫الســيارة مباشــرة ومبــا أنــه لــم يظهــر مــن املدعــي مــا يــدل علــى الرضــا‬\n       ‫أن املقــرر عنــد أهــل العلــم أن خيــار العيــب يثبــت‬\n                                                             ‫بالعيــب املذكــور ومبــا َّ‬\n       ‫أن املدعــي‬‫فيــه إمــا اإلمســاك مــع األرش أو الــرد وأخــذ الثمــن ومبــا َّ‬\n       ‫اختــار الــرد وأخــذ ثمنــه ومبــا أن خيــار العيــب ال يحتــاج إلــى حكــم‬\n       ‫حاكــم لــذا فقــد ثبــت أن الســيارة املوصوفــة معيبــة عيبـ ًا شــرعي ًا كمــا‬\n       ‫ثبــت انفســاخ بيــع الســيارة املوصوفــة وصــدر احلكــم علــى املدعــى عليــه‬\n‫‪145‬‬\n\f‫بتســليم املدعــي املبلــغ املدعــى بــه ‪ -‬اعتــرض املدعــى عليــه علــى احلكــم‬\n                            ‫‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫ـدي‬‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لـ َّ‬\n‫أنــا ‪ ...............‬القاضــي باحملكمــة العامــة بالدمــام فتحــت اجللســة متــام‬\n‫بناء على املعاملة‬‫الساعة العاشرة والربع من صباح يوم ‪1433/3/15‬هـ ً‬\n‫احملالــة مــن فضيلــة الرئيــس برقــم ‪ 3331141‬واملقيــدة لــدى احملكمــة‬\n‫برقــم‪ 3379530‬يف ‪1433/ 01 / 11‬ه ـ وبهــا حضــر ‪ ............‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...............‬الوكيــل الشــرعي عــن‬\n‫‪ ...........‬مبوجــب الوكالــة الصــادرة مــن كاتــب عــدل رابغ رقم ‪ 3098‬يف‬\n‫‪1432/12/19‬ه ـ واملتضمنــة أن لــه احلــق يف املرافعــة واملدافعــة وحضــور‬\n‫اجللســات وإقامــة البينــة واالســتالم ولــم يحضــر املدعــى عليــه وقــد جــرى‬\n‫حتديــد هــذا اليــوم متــام الســاعة التاســعة وخمــس وأربعــن دقيقــة موعــد ًا‬\n‫لنظرهــا تبلــغ بهــا املدعــى عليــه لشــخصه حســب إفــادة رئيــس قســم‬\n‫محضــري اخلصــوم حســن عبــد اهلل الزهرانــي ومضــى وقــت اجللســة‬\n‫ولــم يحضــر‪ .‬اهــ‪ .‬بعدهــا قــال املدعــي وكالــة يف حتريــر دعــواه‪ :‬لقــد‬\n‫اشــترى موكلــي مــن مؤسســة املدعــى عليــه وهــي مؤسســة ‪...............‬‬\n‫ســيارة نــوع كامــري جــي إل إكــس فتحــة أوتوماتيــك صنــع عــام ‪2011‬‬\n‫اللــون لؤلــؤي رقــم الشاســيه ‪ .........‬وذلــك بتاريــخ ‪ 1432/11/17‬املوافــق‬\n‫‪2011/10/14‬م بثمــن قــدره ثمــان وثمانــون ألف ـ ًا وثالثمائــة ريــال وســلم‬\n‫لهــم كامــل املبلــغ واســتلم الســيارة والــذي حصــل أن موكلــي بعــد أن‬\n‫خــرج بالســيارة مــن معــرض املدعــى عليــه ذهــب بهــا إلــى قســم الفحــص‬\n\n                                                                                      ‫‪146‬‬\n\f      ‫فوجــد أن الســيارة مغشوشــة وذلــك أنهــا مصبوغــة يف أطــراف الســيارة‬\n      ‫كاملــة فرجــع إلــى املعــرض بعــد أربعــن دقيقــة مــن اســتالمها تقريب ـ ًا‬\n      ‫ووضــع الســيارة عندهــم فوعــده املدعــى عليــه بفحصهــا عــن طريــق‬\n      ‫وكالــة ‪ ............‬ولــم يحصــل شــيء مــن ذلــك ومازالــت الســيارة عندهــم‬\n      ‫حتى اآلن وقد تر َّتب على ذلك اســتئجار موكلي لســيارة أخرى أجرتها‬\n      ‫الشــهرية مبلــغ وقــدره ألــف وثالثمائــة ريــال كمــا أن موكلــي تضــرر‬\n      ‫ضــرر ًا بالغـ ًا حيــث كان يخــرج مــن عملــه ويتــر َّدد علــى مؤسســة املدعــى‬\n      ‫عليــه دون جــدوى لــذا فإنــي موكلــي يطلــب اآلتــي‪ :‬أوالً‪ /‬مبلــغ وقــدره‬\n      ‫ثمــان وثمانــون ألفـ ًا وثالثمائــة ريــال ثمــن الســيارة املوصوفــة‪ .‬ثانيـاً‪ /‬مبلــغ‬\n      ‫وقــدره ســبعة آالف ريــال ثمــن إيجــار الســيارة التــي اســتأجرها موكلــي‪.‬‬\n      ‫ليكــون إجمالــي مــا يطالــب بــه موكلــي املدعــى عليــه مبلــغ وقــدره‬\n      ‫خمســة وتســعون ألف ـ ًا وثالثمائــة ريــال أطلــب إلزامــه بتســليمها‪ .‬هــذه‬\n      ‫ـدي البينــة علــى مــا‬\n                            ‫إجابتــي‪ .‬وبطلــب البينــة مــن املدعــي وكالــة قــال‪ :‬لـ َّ‬\n      ‫ذكــرت أطلــب إمهالــي إلحضارهــا؛ ويف يــوم األربعــاء ‪1433/6/18‬ه ـ‬\n      ‫فتحــت اجللســة متــام الســاعة العاشــرة وبهــا حضــر املدعــي وكالــة كمــا‬\n      ‫حضــر املدعــى عليــه ‪ ..................‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ .................‬الوكيــل الشــرعي عــن ‪ ..................‬مبوجــب‬\n      ‫الوكالــة الصــادرة مــن كتابــة عــدل الدمــام الثانيــة برقــم ‪ 32318‬يف‬\n      ‫‪1432/6/27‬ه ـ واملتضمنــة أن لــه احلــق يف املطالبــة واملرافعــة واملدافعــة‬\n      ‫والصلــح التنــازل ويف هــذه اجللســة جــرى عــرض الدعــوى علــى املدعــى‬\n      ‫عليــه وكالــة وبســؤاله عنهــا أجــاب قائـاً‪ :‬مــا ذكــره املدعــي يف دعــواه‬\n      ‫بعضــه صحيــح وبعضــه غيــر صحيــح فمــا ذكــره مــن كــون موكلــه‬\n      ‫اشــترى الســيارة املذكورة من مؤسســة موكلي وســلم له كامل ثمنها‬\n\n\n‫‪147‬‬\n\f‫وأنــه أرجــع الســيارة إلــى املعــرض فهــذا صحيــح أمــا مــا ذكــره من كون‬\n‫الســيارة مغشوشــة وأنــه أرجعهــا بعــد أربعــن دقيقــة مــن اســتالمها فهــذا‬\n‫غيــر صحيــح والــذي حصــل أن الســيارة وردت إلينــا مــن الوكيــل ومت‬\n‫اســتالمها وبعــد ثالثــة أيــام باعهــا موكلــي للمدعــي أصالــة ثــم أرجعهــا‬\n‫ال‬‫لنــا بعــد يــوم تقريب ـ ًا لكونهــا مغشوشــة ومت فحصهــا فحص ـ ًا شــام ً‬\n‫عــن طريــق وكالــة ‪ .............‬فتبــن أنهــا ســليمة ومــا زالــت الســيارة عنــد‬\n‫موكلــي وال مانــع لديــه مــن تســليمه إياهــا‪ .‬لــذا فــا يســتحق املدعــي‬\n‫علــى دعــواه شــيئ ًا وال ســبيل لــه علــى موكلــي‪ .‬هــذه إجابتــي‪ .‬وبعــد‬\n‫ـدي البينــة‬‫ســماع اإلجابــة قــال املدعــي وكالــة الصحيــح مــا ذكرتــه ولـ َّ‬\n‫علــى مــا ذكــرت وأحضــر للشــهادة وأدائهــا ‪ ...........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .................‬البالــغ مــن العمــر ثالثــن عامـ ًا‬\n‫ويعمــل بــوزارة الصحــة وال قرابــة لــه باملدعــي أصالــة وبســؤاله عمــا لديــه‬\n‫مــن شــهادة أجــاب قائ ـاً‪ :‬أشــهد أنــه يف إحــدى األيــام ال أذكــر تاريــخ‬\n‫ذلــك بالتحديــد رافقــت املدعــي وكالــة إلــى معــرض ‪ ...........‬حيــث‬\n‫أخبرنــي أن أخــاه اشــترى ســيارة منهــم نــوع كامــري صنــع عــام ‪2012‬‬\n‫فقمــت بالشــخوض معــه إلــى املعــرض وأحضــر شــخص فلبينــي يعمــل‬\n‫يف محــات فحــص الســيارات فقــام بفحــص الســيارة التــي أشــار إليهــا‬\n‫املدعــي وكالــة وكان معــه جهــاز وقــام بالفحــص مــن عــدة أماكــن‬\n‫يف الســيارة ثــم قــال للمدعــي وكالــة إن قــراءات الســيارة تختلــف ولــم‬\n‫ـدي‬‫أشــهد عقـ َـد شــراء الســيارة يــن املدعــي واملدعــى عليــه‪ .‬هــذا مــا لـ َّ‬\n‫وبــه أشــهد‪ .‬اهــ‪ .‬كمــا أحضــر للشــهادة وأدائهــا ‪ .........................‬مينــي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...................‬البالــغ مــن العمــر‬\n‫خمســة وعشــرين عام ـ ًا ويعمــل بســمكرة الســيارات وال قرابــة لــه‬\n\n\n                                                                                         ‫‪148‬‬\n\f      ‫باملدعــي وبســؤاله عمــا لديــه مــن شــهادة أجــاب قائ ـاً‪ :‬أشــهد أنــه يف‬\n      ‫أحــد األيــام ال أذكــر تاريــخ ذلــك بالتحديــد أخبرنــي املدعــي وكالــة‬\n      ‫أنــه اشــترى ســيارة مــن ‪ .....‬وطلــب منــي الشــخوص لرؤيتهــا فذهبــت إلــى‬\n      ‫معــرض ‪ .....‬وأشــار إلــى ســيارة نــوع كامــري لونهــا أبيــض أظــن أنهــا‬\n      ‫صنــع عــام ‪2011‬م وحينمــا رأيتهــا اتضــح لــي أن عليهــا أثــر ســمكرة‬\n      ‫يف اجلانــب األيســر ولــم أشــهد عقــد املبايعــة بــن املدعــي واملدعــى عليــه‪.‬‬\n      ‫ـدي وبــه أشــهد‪ .‬اهــ‪ .‬وبعــرض الشــاهدين وشــهادتهما علــى‬       ‫هــذا مــا لـ َّ‬\n      ‫إن‬\n       ‫املدعــى عليــه وكالــة قــال‪ :‬مــا ذكــره الشــاهدان غيــر صحيــح ثــم َّ‬\n      ‫مــا يتعلــق باجلهــاز الــذي مت فحصــه مــن قبــل الفلبينــي فهــو غيــر معتــرف‬\n      ‫بــه وال أقــول يف الشــاهدين شــيئ ًا وال مطعــن فيــه فيهمــا‪ .‬اهــ‪ .‬بعدهــا‬\n      ‫قــررت الكتابــة إلــى مــرور الدمــام مــن أجــل إجــراء الفحــص علــى‬\n      ‫الســيارة عــن طريــق اجلهــة املختصــة بفحــص الســيارات واإلفــادة عــن‬\n      ‫حالتهــا؛ ويف يــوم الثالثــاء ‪1433/8/13‬ه ـ فتحــت اجللســة متــام احلاديــة‬\n      ‫عشــرة وعشــر دقائــق وبهــا حضــر املدعــي وكالــة ولــم حتضــر املدعــى‬\n      ‫عليهــا ولــم يحضــر وكيــل عنهــا وقــد جــرت الكتابــة إلــى مديــر مــرور‬\n      ‫معــارض الدمــام بخطابنــا رقــم ‪ 33/1486355‬يف ‪1433/8/7‬ه ـ فــورد‬\n      ‫إلـ َّـي خطــاب مــرور الدمــام رقــم ‪/298‬م‪/‬ط يف ‪1433/8/12‬ه ـ وبرفقــه‬\n      ‫كشــف املهنــدس وقــد تضمــن أنه مت الكشــف على الســيارة نــوع تويوتا‬\n      ‫صنــع عــام ‪2011‬م نــوع كامــري رقــم اللوحــة ‪ ...............‬اللــون أبيــض‬\n      ‫ملالكهــا ‪ ..................‬وقــد مت االســتعانة بجهــاز حســاب كثافــة الصبــغ‬\n      ‫ووجــد فــارق يف الكثافــة باملقارنــة مــع ســيارات أخــرى لــذا تبــن بعــد‬\n      ‫الكشــف أنــه مت إعــادة صبــغ الســيارة بالكــرو أو الصبــغ حيــث اجلهــاز‬\n      ‫يعطــي عــدة قــراءات يف عــدة أماكــن مــن الســيارة‪ .‬املهنــدس‪ .‬التوقيــع‪.‬‬\n\n\n‫‪149‬‬\n\f‫رئيــس قســم رخــص الســير النقيــب ‪...................‬اهــ‪ .‬ويف يــوم الســبت‬\n‫‪1433/11/27‬ه ـ فتحــت اجللســة متــام الثانيــة عشــرة والنصــف ولــم يتــم‬\n‫فتحهــا يف موعدهــا حللــول وقــت الصــاة وبهــا حضــر املدعــي وكالــة‬\n‫وقــد أبــرز يف هــذه اجللســة وكالــة أخــرى صــادرة مــن كتابــة عــدل رابــغ‬\n‫برقــم ‪ 3093‬يف ‪1433/11/23‬ه ـ وقــد تضمنــت أن لــه احلــق يف املطالبــة‬\n‫واملدافعــة والتنــازل كمــا حضــر املدعــى عليــه وكالــة ‪......................‬‬\n‫املــدون هويتــه ووكالتــه ســابقاً‪ .‬ويف هــذه اجللســة قــرر املدعــي وكالــة‬\n‫قائ ـاً‪ :‬إن موكلــي يحصــر دعــواه يف املطالبــة بــرد ثمــن الســيارة فقــط‬\n‫مــع االحتفــاظ بحقــه يف رفــع دعــوى مســتقلة بشــأن الضــرر املــادي الــذي‬\n‫حلقــه بســبب العيــب يف الســيارة محــل النــزاع‪ .‬اهــ‪ .‬بعدهــا جــرى عــرض‬\n‫خطــاب مــرور الدمــام املــدون ســابق ًا وهــو ذو الرقــم ‪/298‬م‪/‬ط يف‬\n‫‪1433/8/12‬ه ـ مــع قــرار املهنــدس املرفــق علــى املدعــى عليــه وكالــة‬\n‫ـاء‬\n‫فقــال‪ :‬ال أعلــم عــن هــذا القــرار شــيئ ًا وال مطعــن لــي فيــه‪ .‬اهــ‪ .‬فبنـ ً‬\n‫علــى مــا تقـ َّـدم مــن دعــوى املدعــي وكالــة املتضمنــة أن موكلــه اشــترى‬\n‫الســيارة املوصوفــة وأنــه وجــد بهــا عيبـ ًا فأرجــع الســيارة مــن حــن علمــه‬\n‫وطلــب َر َّد ثمنهــا وأن الســيارة لــدى املدعــى عليهــا وجــواب املدعــى عليــه‬\n‫وكالــة املتضمــن املصادقــة علــى شــراء الســيارة بالثمــن املذكــور وأن‬\n‫املدعــي قــام بإرجــاع الســيارة بعــد شــرائها بيــوم تقريبـ ًا وأنكــر كونهــا‬\n‫معيبــة ومبــا أ َّنــه قــد جــرت الكتابــة إلــى مديــر مــرور املعــارض وقــد‬\n‫تضمــن قــرار املهنــدس أنــه مت إعــادة صبــغ الســيارة محــل النــزاع ومبــا‬\n‫أن إعــادة صبــغ الســيارة يعــده التجــار نقص ـ ًا يف قيمــة املبيــع وهــذا هــو‬\n‫ضابــط العيــب الــذي يثبــت بــه اخليــار ( ينظــر‪ :‬الــروض املربــع ‪)441/4‬‬\n‫ومبــا أن املدعــى عليــه وكالــة صــا َدق علــى أن املدعــي أرجــع الســيارة‬\n\n\n                                                                                     ‫‪150‬‬\n\f      ‫مباشــرة ومبــا أنــه لــم يظهــر مــن املدعــي مــا يــدل علــى الرضــا بالعيــب‬\n      ‫أن املقــرر عنــد أهــل العلــم أن خيــار العيــب يثبــت فيــه إمــا‬\n                                                                         ‫املذكــور ومبــا َّ‬\n      ‫أن املدعــي اختــار الــرد‬‫اإلمســاك مــع األرش أو الــرد وأخــذ الثمــن ومبــا َّ‬\n      ‫وأخــذ ثمنــه ومبــا أن خيــار العيــب ال يحتــاج إلــى حكــم حاكــم لــذا فقــد‬\n                                       ‫ـدي أن الســيارة املوصوفــة معيبــة عيب ـ ًا‬‫ثبــت لـ َّ‬\n      ‫ـدي انفســاخ بيــع املؤسســة املدعــى عليهــا الســيارة‬ ‫شــرعي ًا كمــا ثبــت لـ َّ‬\n      ‫املوصوفــة للمدعــي وحكمــت علــى املؤسســة املدعــى عليهــا مؤسســة‬\n      ‫‪ ...............‬بتســليم املدعــي ‪ ..............‬املبلــغ املدعــى بــه وقــدره ثمــان‬\n      ‫وثمانــون ألف ـ ًا وثالثمائــة ريــال وبعــرض احلكــم علــى املدعــى عليــه‬\n      ‫وكالــة قــرر عــدم القناعــة وطلــب رفــع املعاملــة إلى محكمة االســتئناف‬\n      ‫بالئحــة اعتراضيــة فأفهــم بــأن مــدة االعتــراض ثالثــون يوم ـ ًا تبــدأ مــن‬\n      ‫يــوم األربعــاء ‪1433/12/1‬ه ـ إذا مضــت ولــم يقــدم اعتراضــه اكتســب‬\n      ‫احلكــم القطعيــة وأصبــح با َّت ـ ًا واجــب التنفيــذ وكانــت ســاعة النطــق‬\n      ‫باحلكــم متــام الواحــدة ظهــر ًا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/11/27‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/2/25‬ه ـ فتحــت‬\n      ‫اجللسة متام الساعة العاشرة والنصف بناء على ورود املعاملة من محكمة‬\n      ‫االســتئناف باملنطقــة الشــرقية برقم‪34396314‬وتاريخ‪1434/2/13‬ه ـ‬\n      ‫ورفقهــا القــرار رقــم ‪3431085‬وتاريخ‪1434/2/5‬ه ـ واملتضمــن ‪:‬‬\n      ‫املصادقــة علــى احلكــم‪ ،‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                       ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/2/25‬ه ـ ‪.‬‬\n\n\n\n\n‫‪151‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":145,"source_page_end":151,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9b8748591f60ecfeb92fb472ef620e2674ec9f32628e696b872e4604039e0d80","normalized_text_hash":"ee847094cead13b83c85a80b1aefa96429944bca7e920a0d588212c468749d79","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p145-33466823"},{"id":"0bb671d6-fa27-5310-b69e-5afd47ec1e8d","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع أرض محددة احلدود واملعالم بعقد -النص على خلو املبيع من املشاكل وإال فالعقد الغي ا مع اإللزام بإعادة القيمة كاملة -مصادقة املدعى عليه على العقد -وجود مشاكل يف األرض -األصل يف العقود اإللزام -إلزام املدعى عليه بإعادة الثمن.","document_number":"3435647","case_number":"3358940","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط مبوجب قرار رئيس مجلس القضاء األعلى","circuit":"الدائرة احلقوقية األولى برقم 34251014وتاريخ 1434/6/25ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/11","year":"1434","subject":"بيع -بيع أرض محددة احلدود واملعالم بعقد -النص على خلو املبيع من املشاكل وإال فالعقد الغي ا مع اإللزام بإعادة القيمة كاملة -مصادقة املدعى عليه على العقد -وجود مشاكل يف األرض -األصل يف العقود اإللزام -إلزام املدعى عليه بإعادة الثمن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/11 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3435647 :‬‬\n                    ‫َر ْق ُم الدعوى‪3358940 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34251014‬تاريخه‪1434/6/25 :‬هـ‬\n\n\n‫بيــع ‪ -‬بيــع أرض محــددة احلــدود واملعالــم بعقــد ‪ -‬النــص علــى خلــو‬\n‫املبيــع مــن املشــاكل وإال فالعقــد الغي ـ ًا مــع اإللــزام بإعــادة القيمــة‬\n‫كاملــة ‪ -‬مصادقــة املدعــى عليــه علــى العقــد ‪ -‬وجــود مشــاكل يف‬\n‫األرض ‪ -‬األصــل يف العقــود اإللــزام ‪ -‬إلــزام املدعــى عليــه بإعــادة الثمــن‪.‬‬\n\n\n\n\n                     ‫‪ -‬قوله تعالى ( يا أيها الذين آمنوا أوفوا بالعقود ) ‪.‬‬\n               ‫‪ -‬قوله صلى اهلل عليه وسلم ( املسلمون على شروطهم ) ‪.‬‬\n\n\n\n\n‫اشــترى املدعــي مــن املدعــى عليــه قطعــة أرض محــددة احلــدود واملعالــم‬\n‫مبوجــب عقــد ‪ -‬وقــد نــص يف العقــد علــى تســليم األرض خاليــة مــن‬\n‫املشــاكل ويف حالــة ثبــوت خــاف ذلــك فــإن العقــد يعتبــر الغي ـ ًا مــع‬\n‫إعــادة قيمــة األرض كاملــة ‪ -‬وقــد صــادق املدعــى عليــه علــى ذلــك‪ ،‬إال‬\n‫أن املدعــي بعــد تســلمه لــأرض وجــد بهــا مشــاكل‪ .‬وملــا كان األصــل‬\n‫يف العقــود اإللــزام حكمــت احملكمــة بإلــزام املدعــى عليــه بــرد الثمــن‬\n‫إلــى املدعــي ‪ -‬اعتــرض املدعــى عليــه ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                 ‫االســتئناف ‪.‬‬\n\n\n\n                                                                                    ‫‪152‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي املنتــدب يف احملكمــة‬\n      ‫العامة بخميس مشــيط مبوجب قرار رئيس مجلس القضاء األعلى رقم‬\n      ‫‪ 22536‬يف ‪1433/11/29‬ه ـ واملكلــف بعمــل املكتــب القضائــي الرابع‬\n      ‫مبوجــب خطــاب رئيــس هــذه احملكمــة رقــم ‪ 3433830‬يف ‪1434/1/5‬‬\n      ‫ه ـ وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بخميــس مشــيط برقــم ‪ 3358940‬وتاريــخ ‪ 1433/01/23‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33151869‬وتاريــخ ‪ 1433/01/23‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافــق‪ 1434/02/10‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 30‬‬\n      ‫وفيهــا حضــر ‪ ............... /‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم‪ ...........‬وحضــر حلضــوره ‪ ..........‬يحمــل ســجل مدنــي رقــم ‪..............‬‬\n      ‫ا لقــد اشــتريت مــن هــذا احلاضــر أرض ـ ًا مبدينــة‬      ‫فادعــى األول قائ ـ ً‬\n      ‫‪ ..........‬وحدودهــا وأطوالهــا كالتالــي ‪( :‬الشــمال مخطــط احلســنية‬\n      ‫بطــول الضلــع ‪25‬م اجلنــوب شــارع عــرض ‪15‬م بطــول الضلــع ‪25‬م الشــرق‬\n      ‫قطعــة أرض رقــم ‪ 5‬بطــول الضلــع ‪30‬م الغــرب قطعــة أرض رقــم ‪7‬‬\n      ‫بطــول الضلــع ‪30‬م وكامــل املســاحة اإلجماليــة ‪750‬م) مببلــغ وقــدره‬\n      ‫ثالثــة وخمســون ألــف ريــال وقــد اتفقنــا يف العقــد علــى تســليم األرض‬\n      ‫خاليــة مــن املشــاكل وال يكــون عليهــا أي خــاف وإن ثبــت خــاف ذلــك‬\n      ‫فتلغــى املبايعــة ويعــد العقــد الغيـ ًا وبعــد إمتــام العقــد وتســليم املبلــغ نزلــت‬\n      ‫إلــى األرض املذكــورة وبــدأت يف إنشــاء جــدار حولهــا إال أن أصحــاب‬\n      ‫األراضــي املجــاورة منعونــي وقالــوا إن هــذه األرض ليســت للشــخص‬\n      ‫الــذي باعــك وعليهــا عــدة مشــاكل ولــن منكنــك مــن العمــل فيهــا عندها‬\n\n‫‪153‬‬\n\f‫رجعــت إلــى املدعــى عليــه وأفهمتــه بذلــك ولكنــه رفــض إرجــاع املبلــغ لي‬\n‫لــذا فإنــي أطلــب تنفيــذ العقــد الــذي بيننــا بكامــل شــروطه ‪ ،‬وبعــرض‬\n‫ذلــك علــى املدعــى عليــه أجــاب مــا ذكــره املدعــي يف دعــواه صحيــح‬\n‫ا ولكــن قــد بينــت لــه أن األرض ليــس عليهــا صــك متلــك‬        ‫جملــة وتفصيـ ً‬\n‫والعقــد املبــرم بيننــا صحيــح والتوقيــع توقيعــي وبالرجــوع ألوراق املعاملــة‬\n‫جــرى االطــاع علــى عقــد املبايعــة فوجدتــه متضمنـ ًا مــا يلــي ‪ ( :‬ففــي يــوم‬\n‫الســبت بتاريــخ ‪1433/1/15‬ه ـ مت االتفــاق بــن كل مــن األشــخاص ‪-1‬‬\n‫طــرف أول البائــع ‪ .............‬وعنوانــه خميــس مشــيط حامــل احلفيظــة رقــم‬\n‫‪ ................‬وتاريــخ ‪1416/2/21‬ه ـ ســجل خميــس مشــيط ‪ -2‬طــرف‬\n‫ثانــي املشــتري ‪ .................‬وعنوانــه خميــس مشــيط حامــل احلفيظــة رقــم‬\n‫‪ ...........‬وتاريــخ ‪1406/5/11‬ه ـ ســجل ظهــران اجلنــوب فقــرر الطــرف‬\n‫األول بأنــه بــاع برضائــه واختيــاره ومــن غيــر جبــر وال إكــراه وال تغريــر‬\n‫إلــى الطــرف الثانــي أرض رقــم ‪ 6‬مخطــط الروضــة ( الكــدره ) الكائن‬\n‫يف حــي الــدرب مبدينــة ‪ ...............‬احملــدودة كاآلتــي ‪ :‬الشــمال مخطــط‬\n‫احلســنية بطــول الضلــع ‪25‬م اجلنــوب شــارع عــرض ‪15‬م بطــول الضلع ‪25‬م‬\n‫الشــرق قطعــة أرض رقــم ‪ 5‬بطــول الضلــع ‪30‬م الغــرب قطعــة أرض رقــم‬\n‫‪ 7‬بطــول الضلــع ‪30‬م وكامــل املســاحة اإلجماليــة ‪750‬م وذلــك مبوجــب‬\n‫عقــود مسلســلة حســب العقــود الســابقة وذلــك مبلــغ وقــدره وبيانــه ثالثــة‬\n‫وخمســون ألــف ريــال وقــد اســتلم البائــع مــن القيمــة كامــل املبلــغ‬\n‫ال مــن الطرفــن املبيــع ومت التوقيــع‬    ‫والباقــي ال يوجــد وقــد اســتلم ك ً‬\n‫مبجلــس البيــع وأكــد الطــرف األول بــأن املبــاع خالــي ممــا قــد يســبب‬\n‫عرقلــة اســتفادة الطــرف الثانــي منــه وفيمــا لــو تبــن خــاف ذلــك فــإن‬\n‫الطــرف األول ملــزم بإعــادة القيمــة كاملــة وحتمــل داللــة املكتــب ‪ ،‬أن‬\n\n\n                                                                                      ‫‪154‬‬\n\f      ‫توقيــع الطرفــن علــى هــذا العقــد يعنــي فهمهمــا لــكل الشــروط الــواردة‬\n      ‫بــه وموافقتهمــا علــى مــا جــاء بــه هــذا واهلل ولــي التوفيــق والنجاح ‪ .‬شــهود‬\n      ‫احلــال شــهد بذلــك ‪ .............‬اســمه وتوقيعــه وشــهد بذلــك ‪ ..........‬اســمه‬\n      ‫وتوقيعــه البائــع ‪ ..........‬اســمه وتوقيعــه املشــتري ‪ ...........‬اســمه وتوقيعــه )‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــر ًا لكــون املدعــى عليــه‬\n      ‫قــد أقــر وصــادق علــى العقــد الصــادر بينهمــا وألن األصــل يف العقــود‬\n      ‫اإللــزام والنفــاذ لقولــه تعالــى ( يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود )‬\n      ‫ولقولــه صلــى اهلل عليــه وســلم ( املســلمون علــى شــروطهم ) لذلــك فقــد‬\n      ‫ألزمــت املدعــى عليــه بتســليم املدعــي مبلغـ ًا وقــدره ثــاث وخمســون ألــف‬\n      ‫ريــال وبعــرض احلكــم علــى الطرفــن قــرر املدعــي القناعــة واملدعــى‬\n      ‫عليــه عــدم القناعــة وطلــب االســتئناف مــع تقــدمي الئحــة اعتــراض‬\n      ‫فأجبتــه لطلبــه ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/11‬ه ـ ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/7/18‬ه ـ‬\n      ‫فتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف مبنطقــة‬\n      ‫عســير برقــم ‪ 341461888‬وتاريــخ ‪1434/7/8‬ه ـ واملرفــق بهــا قــرار‬\n      ‫الدائــرة احلقوقيــة األولــى برقــم ‪ 34251014‬وتاريــخ ‪1434/6/25‬ه ـ‬\n      ‫واملوقــع مــن قضــاة الدائــرة احلقوقيــة األولــى واملتضمــن بدراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر املوافقــة‬\n      ‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬قاضــي اســتئناف ‪ .............‬توقيعــه وختمــه وقاضــي‬\n      ‫اســتئناف ‪ ............‬توقيعــه وختمــه ورئيــس الدائــرة ‪ ...............‬توقيعــه‬\n      ‫وختمــه وللبيــان جــرى إحلاقــه حتــى ال يحفــى وبــاهلل التوفيــق وصلــى اهلل‬\n\n\n‫‪155‬‬\n\f                                    ‫نبينــا محمــد حــرر يف ‪1434/7/18‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬املــازم القضائــي يف احملكمــة‬\n‫العامــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بخميــس مشــيط برقــم ‪ 3358940‬وتاريــخ‬\n‫‪ 1433/01/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33151869‬وتاريــخ‬\n‫‪ 1433/01/23‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/09/13‬ه ـ افتتحــت‬\n‫اجللســة الســاعة الواحــدة بعــد الظهــر ‪ ،‬وفيهــا حضــر ‪ ............‬ســعودي‬\n‫اجلنســية بالســجل املدنــي رقــم ‪ ...........‬وقــرر اســتالمه كامــل املبلــغ‬\n‫املدعــى بــه أعــاه وقــدره ثالثــة وخمســون ألــف (‪ )53000‬ريــال ولــم‬\n‫يبــق لــه مطالبــة جتــاه املدعــى عليــه بخصــوص هــذه الدعــوى وعليــه‬\n‫تكــون هــذه الدعــوى منتهيــة ‪ .‬وللبيــان جــرى إحلاقــه ‪ .‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                          ‫‪ 1434/09/13‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪156‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":152,"source_page_end":156,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f95ba851b930938b62eaf1a855d076a7902ca275b6cdf70ad6786e857eafcc21","normalized_text_hash":"f4566def7894b47205dbe319bfc0fce564563138665a9d14978063ad3c67ece6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p152-3435647"},{"id":"ad081d27-ff0f-5cad-9381-670615c8fe15","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -ثمن مبيع -مطالبة املضمون له الضام ن بتسليم ما بقي من ثمن املكيفات -غياب املدعى عليه وتبلغه لشخصه -االطاع على العقود والكمبياالت ،وحلف املدعي مين االستظهار -احلكم على الضامن بتسليم باقي ثمن املكيفات -اعتبار احلكم حضوري ا .","document_number":"33132641","case_number":"3361783","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبنطقة تبوك لتقرير ما يرونه أصحاب الفضيلة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/3/14","year":"1434","subject":"بيع -ثمن مبيع -مطالبة املضمون له الضام ن بتسليم ما بقي من ثمن املكيفات -غياب املدعى عليه وتبلغه لشخصه -االطاع على العقود والكمبياالت ،وحلف املدعي مين االستظهار -احلكم على الضامن بتسليم باقي ثمن املكيفات -اعتبار احلكم حضوري ا .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/3/14 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33132641 :‬‬\n                          ‫َر ْق ُم الدعوى‪3361783 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34232762‬تاريخه‪1434/2/9 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬ثمــن مبيــع ‪ -‬مطالبــة املضمــون لــه الضامـ َـن بتســليم مــا بقــي‬\n      ‫مــن ثمــن املكيفــات‪ -‬غيــاب املدعــى عليــه وتبلغــه لشــخصه ‪ -‬االطــاع‬\n      ‫علــى العقــود والكمبيــاالت ‪ ،‬وحلــف املدعــي ميــن االســتظهار ‪ -‬احلكــم‬\n      ‫علــى الضامــن بتســليم باقــي ثمــن املكيفــات‪ -‬اعتبــار احلكــم حضوريـ ًا ‪.‬‬\n\n\n\n\n                    ‫‪ .1‬قوله تعالى‪( :‬وملن جاء به حمل بعير وأنا به زعيم) ‪.‬‬\n                           ‫‪ .2‬قوله صلى اهلل عليه وسلم‪ ( :‬الزعيم غارم ) ‪.‬‬\n      ‫‪ .3‬املــواد ‪ 1/55‬و ‪ 2/55‬و‪ 178‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n                                                               ‫التنفيذيــة ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي أنــه بــاع خمســة مكيفــات بقيمــة إجماليــة قدرهــا اثنــا‬\n      ‫عشــر ألف ـ ًا وخمســمائة ريــال مقســطة علــى أقســاط شــهرية مقــدار‬\n      ‫القســط الواحــد ألفــان وخمســمائة ريــال وأن املشــتري ســلم مــن الثمــن‬\n      ‫ألفــن وســتمائة ريــال وبقــي يف ذمتــه تســعة آالف وتســعمائة ريــال‬\n      ‫كلهــا حالــة ‪ ،‬وأن املدعــى عليــه الغائــب عــن مجلــس احلكــم‪ ،‬واملتبلــغ‬\n      ‫لشــخصه ‪ ،‬قــد كفــل املشــتري كفالــة غرميــة‪ ،‬وطلــب إلــزام املدعــى‬\n      ‫عليــه بتســليم املبلــغ الــذي يدعــي بــه وقــدره تســعة آالف وتســعمائة ريــال‬\n\n‫‪157‬‬\n\f‫حــا ًال ‪ -‬بطلــب البينــة مــن املدعــي علــى صحــة دعــواه أبــرز عقديــن‪،‬‬\n‫وســندين ‪ ،‬وبتفحصهــا وجــد مضمونهــا كمــا ذكــر املدعــي يف دعــواه‬\n‫‪ -‬بطلــب ميــن االســتظهار مــن املدعــي علــى دعــواه‪ ،‬حلفهــا ‪ -‬بنــاء علــى‬\n‫مــا أبــرزه املدعــي مــن العقــود والســندات املبرمــة بينــه وبــن املدعــى عليــه‬\n‫‪ -‬وأداء املدعــي ميــن االســتظهار علــى بقــاء حقــه يف ذمــة املدعــى عليــه‬\n‫‪ -‬وتبلــغ املدعــى عليــه لشــخصه‪ ،‬ولــم يحضــر واســتناد ًا للمــواد ‪ 1/55‬و‬\n‫‪ 2/55‬و‪ 178‬مــن نظــام املرافعــات الشــرعية ولوائحــه ‪ -‬ولقولــه تعالــى‬\n‫(وملــن جــاء بــه حمــل بعيــر وأنــا بــه زعيــم ) وقولــه صلــى اهلل عليــه وســلم‬\n‫( الزعيــم غــارم ) ‪ -‬ثبــت أن يف ذمــة املدعــى عليــه لصالــح املدعــي مبلغـ ًا‬\n‫وقــدره تســعة آالف وتســعمائة ريــال كلهــا حالــة يف ذمتــه ‪ -‬مت احلكــم‬\n‫بإلزامــه بدفــع هــذا املبلــغ حــا ًال ‪ -‬يعــد احلكــم يف حــق املدعــى عليــه‬\n‫حضوريـ ًا ‪ -‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫هــذا اليــوم األحــد املوافــق ‪1433/2/21‬ه ـ الســاعة الثامنــة والنصــف‬\n‫صباح ـ ًا فتحــت اجللســة لــدي أنــا (‪ )....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫ـاء علــى املعاملــة احملالــة لــي بشــرح فضيلــة الرئيــس املســاعد‬ ‫بتبــوك بنـ ً‬\n‫برقــم ‪ 3361783‬وتاريــخ ‪1433/1/24‬هـ ـ وفيهــا حضــر املدعــي ‪...........‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )............‬ولــم يحضــر‬\n‫املدعــى عليــه ‪ ...........‬ولــم تــرد إفــادة بتبلغــه مــن عدمــه لــذا ســيجري‬\n‫حتديــد موعــد آخــر وذلــك يف يــوم األحد املوافق ‪1433/3/13‬هـ الســاعة‬\n‫احلاديــة عشــرة والنصــف صباحـ ًا وعليــه جــرى التوقيــع وصلــى اهلل وســلم‬\n\n                                                                                        ‫‪158‬‬\n\f      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن وحــرر يف الســاعة الثامنــة‬\n                        ‫والنصــف مــن ضحــى يــوم األحــد املوافــق ‪1433/2/21‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعده وبعــد ففي هذا‬\n      ‫اليــوم االثنــن املوافــق ‪1433/3/14‬ه ـ الســاعة احلاديــة عشــرة والنصــف‬\n      ‫صباحـ ًا فتحــت اجللســة لــدي أنــا ‪ ...............‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫ـاء علــى املعاملــة احملالــة لــي مــن فضيلــة الرئيــس املســاعد‬     ‫بتبــوك بنـ ً‬\n      ‫برقــم ‪ 3361783‬يف ‪1433/1/24‬ه ـ وفيهــا حضــر املدعــي ‪............‬‬\n      ‫ســعودي مبوجــب الســجل املدنــي رقــم ( ‪ ) ............‬فادعــى ضــد الغائــب‬\n      ‫عــن مجلــس احلكــم الشــرعي ‪ .........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم (………‪ )..‬ويعمــل عســكري ًا يف ســرية ‪ ........‬مبنطقــة‬\n      ‫ا يف حتريــر دعــواه عليــه ‪ :‬لقــد بعــت للمدعــو ‪ ............‬عــدد‬  ‫تبــوك قائ ـ ً‬\n      ‫خمســة مكيفــات مــن نــوع هوائــي بقيمــة إجماليــة قدرهــا اثنــا عشــر‬\n      ‫ألفـ ًا وخمســمائة ريــال وذلــك علــى أقســاط شــهرية قيمــة القســط الواحد‬\n      ‫ـداء مــن تاريــخ ‪1433/12/27‬ه ـ وقــد‬    ‫ألفــان وخمســمائة ريــال وذلــك ابتـ ً‬\n      ‫ســدد مبلغ ـ ًا وقــدره ألفــان وســتمائة ريــال وتبقــى يف ذمتــه تســعة آالف‬\n      ‫وتســعمائة ريــال كلهــا حالــة يف ذمتــه وقــد كفلــه املدعــى عليــه الغائــب‬\n      ‫عــن مجلــس احلكــم الشــرعي كفالــة غــرم وأداء وذلــك حســب العقــد‬\n      ‫املرفــق باملعاملــة برقــم (‪ )00570‬وتاريــخ ‪1432/1/3‬ه ـ والعقــد املرفــق‬\n      ‫برقــم (‪ )00551‬وتاريــخ ‪1431/12/27‬ه ـ وحســب الســندين املرفقــن‬\n      ‫برقــم (‪ )0061‬ورقــم (‪ )0159‬لــذا أطلــب إلــزام املدعــى عليــه بتســديد‬\n      ‫جميــع املبلــغ الــذي أدعــي بــه وقــدره تســعة آالف وتســعمائة ريــال حــا ًال‬\n      ‫هــذه دعــواي ومبــا أن املدعــى عليــه قــد تبلــغ بنفســه مبوعــد األمــس يف‬\n      ‫يــوم األحــد املوافــق ‪1433/3/13‬ه ـ يف الســاعة احلاديــة عشــرة والنصــف‬\n\n\n‫‪159‬‬\n\f‫صباحـ ًا حســب خطــاب محضــري اخلصــوم يف احملكمــة واملرفــق أصلــه‬\n‫يف املعاملــة ومت انتظــاره حتــى نهايــة الــدوام ولــم يحضــر ولــم يقــدم عــذر ًا‬\n‫عــن عــدم حضــوره ولــم يقــدم مذكــرة بدفاعــه لــذا فقــد طلبــت مــن‬\n‫املدعــي البينــة علــى صحــة دعــواه فأبــرز العقــد املرفــق باملعاملــة برقــم‬\n‫(‪ )00570‬وتاريــخ ‪1432/1/3‬ه ـ والعقــد املرفــق برقــم (‪ )00551‬وتاريــخ‬\n‫‪1431/12/27‬ه ـ كمــا أبــرز الســندين املرفقني باملعاملــة برقم (‪)0061‬‬\n‫ورقــم (‪ )0159‬وبتفحصهــا وجــدت مضمونهــا كمــا ذكــر املدعــي يف‬\n‫دعــواه وقــد أرفقــت يف املعاملــة صــورة مــن جميــع مــا ذكــر ثــم أفهمــت‬\n‫املدعــي أن عليــه اليمــن الشــرعية علــى بقــاء حقــه يف ذمــة املدعــى‬\n‫ا ( أقســم بــاهلل العظيــم أننــي‬ ‫عليــه فتفهــم ذلــك فأذنــت لــه فحلــف قائ ـ ً‬\n‫قــد بعــت املدعــو ‪ .......‬عــدد خمســة مكيفــات مــن نــوع هوائــي بقيمــة‬\n‫إجماليــة قدرهــا اثنــا عشــر ألف ـ ًا وخمســمائة ريــال وقــد وصلنــي مــن‬\n‫املبلــغ ألفــان وســتمائة ريــال وتبقــى يف ذمتــه تســعة آالف وتســعمائة ريــال‬\n‫لــم يســدده لــي حتــى اآلن وهــي حالــة يف ذمتــه وقــد كفلــه املدعــى عليــه‬\n‫الغائــب عــن مجلــس احلكــم الشــرعي ‪ .........‬كفالــة غــرم وأداء أقســم‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى وللبينــة‬  ‫بــاهلل العظيــم علــى هــذا ) فبنـ ً‬\n‫التــي ذكرهــا املدعــي يف دعــواه وهــي العقــود والســندات املبرمــة بينــه‬\n‫وبــن املدعــى عليــه وذلــك بتوقيعــه وإمضائــه ونظــر ًا ألداء املدعــي ميــن‬\n‫االســتظهار علــى بقــاء حقــه يف ذمــة املدعــى عليــه ونظــر ًا لتبلــغ املدعــى‬\n‫عليــه بنفســه مبوعــد هــذه اجللســة ولــم يحضــر واســتناد ًا للمادتــن ‪1/55‬‬\n‫و ‪ 2/55‬و‪ 178‬مــن نظــام املرافعــات الشــرعية ولوائحــه وبعــد اطالعــي‬\n‫علــى الكمبيالــة املشــار إليهــا وجــدت مضمونــه كمــا ذكــر املدعــي‬\n‫يف دعــواه ولقولــه تعالــى ( وملــن جــاء بــه حمــل بعيــر وأنــا بــه زعيــم )‬\n\n\n                                                                                        ‫‪160‬‬\n\f      ‫وقولــه صلــى اهلل عليــه وســلم ( الزعيــم غــارم ) لــذا فقــد ثبــت لــدي أن‬\n      ‫يف ذمــة املدعــى عليــه ‪ ...........‬لصالــح املدعــي مبلغ ـ ًا وقــدره تســعة آالف‬\n      ‫وتســعمائة ريــال كلهــا حالــة يف ذمتــه وقــررت إلزامــه بدفــع املبلــغ حــا ًال‬\n      ‫هــذا مــا ظهــر لــي وبــه حكمــت ويعــد احلكــم يف حــق املدعــى عليــه‬\n      ‫حضوري ـ ًا وقــد قــررت بعــث نســخة مــن الصــك لــه إلبالغــه بــه وإفهامــه‬\n      ‫بــأن لــه حــق االعتــراض علــى احلكــم مــدة ثالثــن يومــا مــن تاريــخ التبليــغ‬\n      ‫فــإن لــم يقــدم اعتراضــه فــإن احلكــم يكتســب الصفــة القطعيــة وعليــه‬\n      ‫جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫أجمعــن حــرر يف الســاعة احلاديــة عشــرة وأربعــن دقيقــة مــن ضحــى‬\n      ‫يــوم االثنــن املوافــق ‪1433/3/14‬ه ـ حمــد هلل وحــده وبعــد ففــي هــذا‬\n      ‫اليــوم الثالثــاء املوافــق ‪1434/1/20‬ه ـ الســاعة احلاديــة عشــرة صباح ـ ًا‬\n      ‫فتحــت اجللســة وفيهــا مت االطــاع علــى هــذه املعاملــة وقــد متــت الكتابــة‬\n      ‫بشــأن تبليــغ املدعــى عليــه بنســخة احلكــم أكثــر مــن مــرة ولــم جنــد‬\n      ‫جوابـ ًا حيــث مت متــت الكتابــة ألول مــرة بتاريــخ ‪1433/3/15‬ه ـ لســعادة‬\n      ‫قائــد مجموعــة الشــرطة ‪ ..........‬بتبوك ـ بشــأن تبليــغ املدعــى عليــه ولــم‬\n      ‫تــرد إفــادة ثــم جــرت الكتابــة بخطــاب إحلاقــي بتاريــخ ‪1433/6/22‬ه‬\n      ‫ولــم تــرد إفــادة ثــم جــرت الكتابــة مــرة ثالثــة حســب اخلطــاب املــؤرخ يف‬\n      ‫‪1433/9/12‬ه ـ ولــم تــرد إفــادة حتــى تاريخــه ‪ ،‬وحيــث األمــر مــا ذكــر‬\n      ‫وألن أمــد القضيــة قــد طــال ‪ ،‬والظــن أنــه يصعــب تبلــغ املدعــى عليــه‬\n      ‫باحلكــم لــذا فإنــي أرفــع املعاملــة إلــى أصحــاب الفضيلــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة تبــوك لتقريــر مــا يرونــه أصحــاب الفضيلــة ‪ ،‬وعليــه‬\n      ‫جــرى التوقيــع ‪ ،‬حــرر يف الســاعة احلاديــة عشــرة والنصــف مــن ضحــى‬\n                                                 ‫يــوم الثالثــاء املوافــق ‪1434/1/20‬ه ـ‬\n\n\n‫‪161‬‬\n\f‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ :‬فقــد اطلعنــا نحــن‬\n‫قضــاة الدائــرة احلقوقيــة األولــى يف محكمــة االســتئناف مبنطقــة تبــوك‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك‬\n‫برقــم ‪ 33159943‬وتاريــخ ‪1434/1/25‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة الشــيخ ‪ .............‬وفقــه اهلل برقــم ‪ 33132641‬وتاريــخ‬\n‫‪1433/3/14‬ه ـ اخلــاص بدعــوى ‪ ...........‬ضــد ‪ ...........‬وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة جــرت املصادقــة علــى احلكــم وبــاهلل‬\n          ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                               ‫‪162‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":157,"source_page_end":162,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b18f9c7dfd559bb910ac9783028a798f34b995afd7e80a664c5984213841c571","normalized_text_hash":"a31117343cb9885d95613a29f8414e497602dde1a79a537ff3f6fab267f96a7f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p157-33132641"},{"id":"51b81cfa-4dd1-5deb-89da-c2200286291d","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع رؤوس غنم دون قبض الثمن -عدم حضور املدعى عليه -شهادة الشهود العدول ومين املدعي -احلكم غيابي ا بدفع الثمن املطالب به -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","document_number":"33457039","case_number":"3384608","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/16","year":"1434","subject":"بيع -بيع رؤوس غنم دون قبض الثمن -عدم حضور املدعى عليه -شهادة الشهود العدول ومين املدعي -احلكم غيابي ا بدفع الثمن املطالب به -الغائب على حجته متى حضر -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/16 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33457039 :‬‬\n                           ‫َر ْق ُم الدعوى‪3384608 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34214353‬تاريخه‪1434/5/18 :‬هـ‬\n\n\n       ‫بيــع ‪ -‬بيــع رؤوس غنــم دون قبــض الثمــن ‪ -‬عــدم حضــور املدعــى عليــه‬\n       ‫‪ -‬شــهادة الشــهود العــدول وميــن املدعــي ‪ -‬احلكــم غيابيـ ًا بدفــع الثمــن‬\n       ‫املطالــب بــه ‪ -‬الغائــب علــى حجتــه متــى حضــر ‪ -‬رفــع احلكــم حملكمــة‬\n                                ‫االســتئناف لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪.‬‬\n\n\n\n\n       ‫‪ -1‬قــال ابــن تيميــة‪( :‬وقــد ثبــت يف صحيــح مســلم عــن ابــن عبــاس أن‬\n       ‫النبــي صلــى اهلل عليــه وســلم قضــى بشــاهد وميــن رواه الترمــذي وابــن‬\n       ‫ماجــه مــن حديــث جابــر ورواه أبــو داود والترمــذي وابــن ماجــه مــن‬\n       ‫حديــث أبــي هريــره وروي ذلــك عــن النبــي مــن وجــوه كثيــره وهــذه‬\n       ‫األحاديــث أصــح وأشــهر مــا روي عــن النبــي صلــى اهلل عليــه وســلم يف‬\n       ‫هــذا البــاب وابــن عبــاس رضــي اهلل عنــه الــذي يــروي عــن النبــي صلــى‬\n       ‫اهلل عليــه وســلم أنــه قضــى باليمــن مــع الشــاهد وأن هــذا قضــي بــه يف‬\n                  ‫دعــاوى وأقــر بهــذا بدعاوى)أ‪.‬ه ـ مجمــوع الفتــاوى ‪،139/35‬‬\n       ‫‪ -2‬قــال ابــن القيــم رحمــه اهلل تعالــى يف كتابــه الطــرق احلكميــة يف‬\n       ‫السياســة الشــرعية ص ‪172‬مانصــه (احلكــم بالشــاهد واليمــن وهــو‬\n       ‫مذهــب فقهــاء احلديــث كلهــم ومذهــب فقهــاء األمصــار مــا خــا أبــي‬\n                                                        ‫حنيفــة وأصحابــه) أ‪.‬هــ‪.‬‬\n       ‫‪ -3‬قــال ابــن قدامــة رحمــه اهلل تعالــى يف كتابــه الــكايف ‪ 128/6‬مــا‬\n\n\n‫‪163‬‬\n\f‫نصه(فــإن امتنــع اخلصــم مــن احلضــور عنــد احلاكــم حكــم عليــه‬\n‫ألنــه لــو لــم يحكــم عليــه جلعــل االمتنــاع واالســتتار طريق ـ ًا لتضييــع‬\n                                                                 ‫احلقــوق) ا‪.‬هــ‪.‬‬\n‫‪ -4‬قــال أبــو إســحاق إبراهيــم بــن احلســن يف كتابــه معــن احلــكام‬\n‫‪ 615/2‬مــا نصــه ( مســألة قــال املــاوردي يف تفســير قــول اهلل تعالــى « وإذا‬\n‫دعــوا إلــى اهلل ورســوله ليحكــم بينهــم » اآليــة دليــل علــى أنــه مــن دعــي‬\n‫إلــى حاكــم مــن حــكام املســلمني فعليــه اإلجابــة ويجــرح إن تأخــر وقــد‬\n‫ورد عــن احلســن بــن علــي رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه‬\n‫وســلم قــال « مــن دعــي إلــى حاكــم مــن حــكام املســلمني فلــم يجــب فهــو‬\n                                                            ‫ظالــم ال حــق لــه) ‪.‬‬\n                     ‫‪ -5‬املواد (‪ 53‬و‪ 55‬و‪ )56‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫بــاع املدعــي للمدعــى عليــه بعضـ ًا مــن رؤوس املاعــز دون قبــض الثمــن‪،‬‬\n‫طالــب املدعــي املدعــى عليــه بالســداد إال أنــه لــم يحضــر‪ ،‬قــدم املدعــي‬\n‫لصحــة دعــواه ورقــة أقّ ــر فيهــا املدعــى عليــه مبديونيــة للمدعــي باملبلــغ‬\n‫املطالــب بــه‪ ،‬كمــا قــدم شــاهدين عدلــن وحلــف اليمــن الشــرعية‬\n‫تأكيــد ًا لذلــك‪ .‬لــذا حكمــت احملكمــة غيابي ـ ًا بإلــزام املدعــى عليــه‬\n‫بدفــع املبلــغ املطالــب بــه‪ ،‬مصادقــة محكمــة االســتئناف علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪164‬‬\n\f      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ..............‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 3384608‬وتاريــخ ‪ 1433/2/2‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33222671‬وتاريــخ ‪ 1433/2/2‬ه ـ املتعلقــة بدعــوى‬\n      ‫‪ .............‬ضــد ‪ ...........‬يف دعــوى يف مبلــغ ويف يــوم االحــد ‪1433/4/18‬‬\n      ‫ه ـ افتتحــت اجللســة يف متــام الســاعة العاشــرة والنصــف صباحــا وجــرى‬\n      ‫النــداء علــى املدعــي واملدعــى عليــه فلــم يحضــر منهمــا أحــد ولــم يقدمــا‬\n      ‫عــذر لتخلفهمــا عــن هــذه اجللســة ولــم يتقــدم وكيــل عــن اي منهمــا وقــد‬\n      ‫حــدد لهمــا موعــد يف هــذا اليــوم يف متــام الســاعة العاشــرة صباحــا وجــرى‬\n      ‫النــداء واالنتظــار مــن بدايــة وقــت اجللســة وحتــى انتهــاء وقتهــا فلم يحضر‬\n      ‫أحــد وقــد مت بعــث تبليــغ للمدعــى عليــه عــن طريــق محضــري اخلصــوم‬\n      ‫بهــذه احملكمــة برقــم ‪ 33235040‬يف ‪1433/2/6‬ه ـ ووقــد أفادنــا‬\n      ‫احملضــر بهــذه احملكمــة ‪ ..........‬انــه مت تســليم التبليــغ لعمــدة حــي نخــب‬\n      ‫ولــم يردنــا مــا يفيــد بتبليــغ املدعــى عليــه مــن عدمــه فعليــه وبنــاء علــى‬\n      ‫املــادة (‪ )53‬مــن نظــام املرافعــات الشــرعية فقــد أمــرت بشــطب هــذه‬\n      ‫القضيــة للمــرة األولــى وال تنظــر إال بعــذر يتقــدم بــه املدعــي أو وكيــل‬\n      ‫عنــه وتقبلــه احملكمــة وأمــرت بحفــظ هــذه الدعــوى يف األرشــيف وباهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                       ‫‪1433/4/18‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n\n\n‫‪165‬‬\n\f‫العامــة بالطائــف برقــم ‪ 3384608‬وتاريــخ ‪ 1433/02/02‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33222671‬وتاريــخ ‪ 1433/02/02‬ه ـ ويف يــوم‬\n‫الســبت ‪ 1433/07/12‬ه ـ افتتحــت اجللســة الســاعة ‪11.20‬للنظــر يف‬\n‫الدعــوى املرفوعــة مــن ‪ ............‬ضــد ‪ ...........‬يف دعــوى يف مبلــغ مالــي‬\n‫وفيهــا حضــر املدعــي ‪ ............‬يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪...........‬‬\n‫ولــم يحضــر املدعــى عليــه ‪ .......‬ولــم يــرد إلينــا مــا يفيــد بتبليغــه فعليــه‬\n‫وبنــاء علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية فقــد‬\n‫قــررت النظــر يف دعــوى املدعــي يف غيــاب املدعــى عليــه فجــرى ســؤال‬\n‫املدعــي عــن دعــواه علــى الغائــب عــن املجلــس الشــرعي فقــال ادعــي علــى‬\n‫الغائــب عــن املجلــس الشــرعي ‪ ........‬بــأن قــد اشــترى منــي أربعــن رأســا‬\n‫مــن املاعــز يف ‪1431/9/14‬ه ـ مببلــغ خمســة وعشــرين ألــف ريــال علــى‬\n‫أن يســددها يف ‪1432/10/30‬ه ـ مببلــغ خمســة وعشــرين ألــف ريــال‬\n‫ولــم يصلنــي منهــا أي شــيء ولــم أقــم بإعفائــه عــن أي جــزء وهــذا املبلــغ‬\n‫جميعــه حــال لــذا أطلــب إلــزام املدعــى عليــه بــأن يدفــع لــي مبلــغ خمســة‬\n‫وعشــرين ألــف ريــال هــذه دعــواي فجــرى ســؤاله هــل لديــك البينــة علــى‬\n‫صحــة دعــواك فقــال نعــم ثــم ابــرز ورقــة وتتضمــن مــا نصــه( أقــر انــا‬\n‫‪ .........‬بــأن يف ذمتــي مبلــغ خمســة وعشــرين ألــف ريــال لــأخ ‪ ..........‬يقــوم‬\n‫بســدادها يف ‪1432/1/30‬ه ـ املقــر بصمتــه ) أ‪.‬ه ـ فجــرى ســؤاله هــل‬\n‫لديــك زيــادة بينــة فقــال نعــم وأطلــب املهلــة إلحضارهــا هكــذا قــرر ثــم‬\n‫رفعــت اجللســة يف الســاعه‪ 11.30‬وحتــى يــوم الثالثــاء ‪1433/11/16‬ه ـ‬\n‫الســاعة ‪10.00‬صباحــا و حــرر يف ‪ 1433/07/12‬ه ـ ‪ ،‬وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء ‪ 1433/11/16‬ه ـ افتتحــت‬\n\n\n                                                                                          ‫‪166‬‬\n\f      ‫اجللســة الســاعة ‪ 11،00‬وفيهــا حضــر املدعــي ‪............‬املدونــة هويتــه‬\n      ‫ســابقا ولــم يحضــر املدعــى عليــه ‪ .........‬ولــم يــرد إلينــا مــا يفيــد بتبليغــه‬\n      ‫فجــرى ســؤال املدعــي هــل أحضــرت البينــة التــي وعــدت بهــا فقــال نعــم‬\n      ‫ثــم احضــر ‪ ........‬يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪ ...............‬من مواليد‬\n      ‫‪1364/7/1‬ه ـ وذكــر بأنــه يســكن يف الشــهداء اجلنوبيــة ومتقاعــد وان‬\n      ‫املدعــي مــن اجلماعــة أمــا املدعــى عليــه فليــس بينــي وبينــه أي قرابــه‬\n      ‫وبســؤاله عمــا لديــه مــن شــهاده قــال اشــهد هلل تعالــى انــه باألمــس يــوم‬\n      ‫االثنــن ‪1433/11/15‬ه ـ ذهبــت أنــا واملدعــي علــى منــزل املدعــى عليــه‬\n      ‫‪ ............‬والوقــع بــوادي النمــل وتقابلنــا مــع املدعــى عليــه يف الشــارع‬\n      ‫وقــد قــرر أمامــي املدعــى عليــه ‪................‬بــأن يف ذمتــه ل‪ .........‬مبلــغ‬\n      ‫خمســة وعشــرين ألــف ريــال وذلــك قيمــة غنــم ولكنــه يطلــب الصلــح يف‬\n      ‫ذلــك ولــم يوافقــه املدعــي وكان ذلــك قبــل آذان املغــرب هــذا مــا لــدي‬\n      ‫وبــه اشــهد هكــذا اشــهد فجــرى ســؤال املدعــي هــل لديــك زيــادة بينــة‬\n      ‫فقــال ليــس لــدي ســوى مــا أحضــرت هكــذا قــرر ثــم احضــر مزكيــن‬\n      ‫لشــاهده وهمــا ‪ ..........‬يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪.........‬و‪..........‬‬\n      ‫يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪.............‬وبســؤالهما عمــا لديهمــا مــن‬\n      ‫شــهاده شــهدا كل واحــد منهمــا مبفــرده قائــا اشــهد هلل تعالــى بــأن‬\n      ‫شــاهد املدعــي وهــو ‪ ............‬ثقــة عــدل مرضــي الشــاهدة هــذا مــا لدينــا‬\n      ‫وبــه نشــهد هكــذا شــهدا فجــرى ســؤال املدعــي هــل انــت مســتعد ببــذل‬\n      ‫اليمــن تكملــة للشــاهد فقــال نعــم فجــرى نصحــه وتخويفــه بــاهلل عــز‬\n      ‫وجــل مــن مغبــة هــذه اليمــن إال انــه أصــر فأذنــت فحلــف قائــا واهلل‬\n      ‫العظيــم الــذي ال إلــه هــو املهلــك املــدرك بــأن املدعــى عليــه الغائــب عــن‬\n      ‫املجلــس الشــرعي ‪ .............‬قــد اشــترى منــي اربعــن رأســا مــن املاعــز‬\n\n\n‫‪167‬‬\n\f‫مببلــغ خمســة وعشــرين ألــف ريــال وهــذا املبلــغ جميعــه حــال ولــم يصلنــي‬\n‫منــه أي شــيء ولــم أقــم بإعفائــه عــن أي جــزء واهلل العظيــم هكــذا حلــف‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى وبنــاء علــى املــادة اخلامســة واخلمســن‬\n‫ومبــا أن املدعــي قــد احضــر شــاهده واملدونــة شــهادته آنفــا واملعدلــة‬\n‫التعديــل الشــرعي وقــد تضمنــت شــهادته بــأن يف ذمــة املدعــى عليــه ‪........‬‬\n‫للمدعــي ‪ .............‬مبلــغ خمســة وعشــرين ألــف ريــال ومبــا أن املدعــي قــد‬\n‫بــذل اليمــن املكملــة للشــاهد وقــد ذكــر شــيخ اإلســام ابــن تيميــه يف‬\n‫مجمــوع الفتــاوى ‪ 391/35‬مــا نصــه (وقــد ثبــت يف صحيــح مســلم عــن‬\n‫ابــن عبــاس أن النبــي صلــى اهلل عليــه وســلكم قضــى بشــاهد وميــن‬\n‫رواه الترمــذي وابــن ماجــه مــن حديــث جابــر ورواه أبــو داود والترمــذي‬\n‫وابــن ماجــه مــن حديــث أبــي هريــره وروي ذلــك عــن النبــي مــن وجــوه‬\n‫كثيــره وهــذه األحاديــث أصــح واشــهر مــا روي عــن النبــي صلــى اهلل‬\n‫عليــه وســلم يف هــذا البــاب وابــن عبــاس رضــي اهلل عنــه الــذي يــروي‬\n‫عــن النبــي صلــى اهلل عليــه وســلم انــه قضــى باليمــن مــع الشــاهد وان‬\n‫هــذا قضــي بــه يف دعــاوى واقــر بهــذا بدعاوى)أ‪.‬ه ـ وقــد ذكــر ابــن القيــم‬\n‫رحمــه اهلل تعالــى يف كتابــه الطــرق احلكميــة يف السياســة الشــرعية‬\n‫ص ‪172‬مانصه(احلكــم بالشــاهد واليمــن وهــو مذهــب فقهــاء احلديــث‬\n‫كلهــم ومذهــب فقهــاء األمصــار مــا خــا أبــي حنيفــة وأصحابه)أ‪.‬ه ـ‬\n‫وقــد ذكــر ابــن قدامــة رحمــه اهلل تعالــى يف كتابــه الــكايف ‪128/6‬‬\n‫مــا نصــه (فــإن امتنــع اخلصــم مــن احلضــور عنــد احلاكــم حكــم عليــه‬\n‫ألنــه لــو لــم يحكــم عليــه جلعــل االمتنــاع واالســتتار طريق ـ ًا لتضييــع‬\n‫احلقــوق) ا‪.‬ه ـ وقــد ذكــر أبــو إســحاق إبراهيــم بــن احلســن يف كتابــه‬\n‫معــن احلــكام ‪ 615/2‬مــا نصــه (مســألة قــال املــاوردي يف تفســير قــول‬\n\n\n                                                                                     ‫‪168‬‬\n\f      ‫اهلل تعالــى « وإذا دعــوا إلــى اهلل ورســوله ليحكــم بينهــم » اآليــة دليــل‬\n      ‫علــى أنــه مــن دعــي إلــى حاكــم مــن حــكام املســلمني فعليــه اإلجابــة‬\n      ‫ويجــرح إن تأخــر وقــد ورد عــن احلســن بــن علــي رضــي اهلل عنهمــا أن‬\n      ‫النبــي صلــى اهلل عليــه وســلم قــال « مــن دعــي إلــى حاكــم مــن حــكام‬\n      ‫املســلمني فلــم يجــب فهــو ظالــم ال حــق لــه » جلميــع ذلــك فقــد ألزمــت‬\n      ‫املدعــى عليــه ‪ ............‬بــأن يدفــع للمدعــي ‪ .............‬مبلــغ وقــدره خمســة‬\n      ‫وعشــرين ألــف ريــال وبــه حكمــت وبعرضــه عليــه قنــع بــه املدعــي وأفهــم‬\n      ‫بــأن هــذا احلكــم حكــم غيابــي خاضــع لالســتئناف حســب التعليمــات‬\n                                                        ‫و حــرر يف ‪ 1433/11/16‬ه ـ‬\n                            ‫وصلى اهلل على نبينا محمد وعلى آله وصحبه وسلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .........‬رئيــس احملكمــة العامــة‬\n      ‫بالطائف‪/‬املســاعد والقائــم بعمــل املكتــب القضائــي الســادس ويف هذا‬\n      ‫اليــوم األحد‪1434/01/04‬ه ـ افتتحــت اجللســة يف متــام الســاعة الثامنــة‬\n      ‫وخمســة وأربعــن دقيقــة وفيهــا قــد مت بعــث صــورة مــن صــك احلكــم‬\n      ‫رقــم ‪ 33457039‬يف ‪1433/11/16‬ه ـ للمدعــى عليــه ‪ ........‬لتقــدمي‬\n      ‫الالئحــة االعتراضيــة علــى احلكــم إن رغــب يف ذلــك خــال ثالثــن يومــا‬\n      ‫مــن اســتالمه لهــا وإذا مضــت املــدة ولــم يتقــدم بالالئحــة فســوف يســقط‬\n      ‫حقــه يف طلــب االســتئناف وبذلــك يعتبــر احلكــم نافــذا وذلــك مبوجــب‬\n      ‫خطابنــا رقــم ‪ 33/2070206‬يف ‪1433/11/21‬ه ـ وقــد أفادنــا احملضــر‬\n      ‫بهــذه احملكمــة ‪ .............‬أنــه تعــذر تســليم صــورة الصــك املشــار إلــى‬\n      ‫رقمــه أعــاه لعــدم وضــوح العنــوان ولعــدم مراجعــة املدعــي علمــا بــأن‬\n      ‫النظام ال يســمح بتســليم صورة احلكم اال للمدعي أو وكيله الشــرعي‬\n      ‫فعليــه وبنــاء علــى املــادة السادســة والســبعني بعــد املائــة واملــادة السادســة‬\n\n\n‫‪169‬‬\n\f‫واخلمســن مــن نظــام املرافعــات الشــرعية فقــد أمــرت برفــع هــذا احلكــم‬\n‫مــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                           ‫يف‪1434/01/04‬ه ـ‬\n‫احلمد هلل وحده وبعد لدي أنا (‪ )....‬القاضي باحملكمة العامة بالطائف‬\n‫واخللــف لفضيلــة الشــيخ (‪ )....‬ويف هــذا اليــوم اإلثنــن ‪1434/06/05‬ه ـ‬\n‫افتتحــت اجللســة يف متــام الســاعة الثامنــة وخمســة وأربعــن دقيقــة وفيهــا‬\n‫وردت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم‬\n‫‪ 34635067‬يف ‪1434/05/22‬ه ـ وقــد جــرى تدقيــق احلكــم مــن الدائرة‬\n‫احلقوقيــة األولــى مبحكمــة االســتئناف وصــدر بشــأنه القــرار رقــم‬\n‫‪ 34214353‬يف ‪1434/05/18‬ه ـ املــدون علــى ظهــر الصــك واملتضمــن‬\n‫(احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم ‪33457039‬‬\n‫وتاريــخ ‪1433/11/16‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ............‬واصدرنــا‬\n‫القــرار رقــم ‪ 34214353‬وتاريــخ ‪1434/05/18‬ه ـ املتضمــن املوافقــة‬\n‫علــى احلكــم والغائــب علــى دعــواه واهلل املوفــق عضــو ‪ ...........‬ختمــه‬\n‫وتوقيعــه عضــو ‪ .............‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ .........‬ختمــه‬\n‫وتوقيعه)أ‪.‬ه ـ وعليــه فقــد أمــرت بإحلــاق ذلــك بضبطــه وســجله وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                             ‫يف‪1434/06/05‬ه ـ الســاعة التاســعة صباح ـاً‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى احلكــم الصــادر مــن‬\n‫فضيلــة الشــيخ (‪ )....‬القاضــي باحملكمــة العامــة بالطائــف واملســجل‬\n\n\n                                                                                   ‫‪170‬‬\n\f      ‫بعــدد ‪ 33457039‬وتاريــخ ‪ 1433/11/16‬هـ ـ واملتضمــن دعــوى (‪)....‬‬\n      ‫ضــد (‪ )....‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬وبدراســة احلكــم وصــورة‬\n      ‫ضبطــه تقــررت املوافقــة علــى احلكــم والغائــب علــى دعــواه واهلل املوفــق‪.‬‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪171‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":163,"source_page_end":171,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f5a3c9d286ba1a272012a82c7458b1220b2534b088828fc126fed78973597fda","normalized_text_hash":"eb818761d565269c0648ffcba55da119efa131eb81347d48cd4a10d23618658a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p163-33457039"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
